{
  "name": "BizFlow Architect",
  "description": "Multimodal Business Process Digitalization tool. Upload menu images and voice rules to generate a functional ordering app instantly.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface MenuItem {
  id: string;
  name: string;
  price: number;
  description?: string;
  category: string;
}

export interface BusinessRule {
  type: 'threshold_discount' | 'threshold_free_delivery' | 'item_discount';
  threshold: number;
  benefitValue: number; // e.g., 0 for free delivery, 10 for 10% off
  originalText: string;
}

export interface AppState {
  menuItems: MenuItem[];
  rule: BusinessRule | null;
  step: 'upload-menu' | 'upload-rule' | 'preview-app';
  isLoading: boolean;
  loadingMessage: string;
}

export type FileType = 'image' | 'audio';

import { GoogleGenAI, Type } from "@google/genai";
import { MenuItem, BusinessRule } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Helper to convert file to base64
export const fileToGenerativePart = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove data url prefix (e.g. "data:image/jpeg;base64,")
      const base64Data = base64String.split(',')[1];
      resolve(base64Data);
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const extractMenuFromImage = async (base64Image: string, mimeType: string): Promise<MenuItem[]> => {
  const modelId = "gemini-2.5-flash"; // Supports multimodal

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image,
            mimeType: mimeType
          }
        },
        {
          text: `Extract all menu items from this image. Return a JSON array. 
          Each item must have:
          - id (unique string)
          - name (string)
          - price (number)
          - category (string, e.g., "Starters", "Mains", "Drinks")
          - description (string, optional)

          If prices are just numbers, assume USD. Cleanup text.`
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            name: { type: Type.STRING },
            price: { type: Type.NUMBER },
            category: { type: Type.STRING },
            description: { type: Type.STRING },
          },
          required: ["id", "name", "price", "category"]
        }
      }
    }
  });

  if (response.text) {
    return JSON.parse(response.text) as MenuItem[];
  }
  return [];
};

export const extractRuleFromAudio = async (base64Audio: string, mimeType: string): Promise<BusinessRule> => {
  const modelId = "gemini-2.5-flash"; // Supports audio

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Audio,
            mimeType: mimeType
          }
        },
        {
          text: `Listen to this audio rule for a restaurant ordering system. 
          Extract the logic into a JSON object.

          Supported Rule Types:
          1. "threshold_free_delivery": If total > X, delivery is free (benefitValue = 0).
          2. "threshold_discount": If total > X, get Y% discount (benefitValue = Y).

          Return JSON matching this structure:
          {
            "type": "threshold_free_delivery" | "threshold_discount",
            "threshold": number,
            "benefitValue": number,
            "originalText": string
          }`
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          type: { type: Type.STRING, enum: ["threshold_free_delivery", "threshold_discount"] },
          threshold: { type: Type.NUMBER },
          benefitValue: { type: Type.NUMBER },
          originalText: { type: Type.STRING }
        },
        required: ["type", "threshold", "benefitValue", "originalText"]
      }
    }
  });

  if (response.text) {
    return JSON.parse(response.text) as BusinessRule;
  }

  // Fallback default
  return {
    type: 'threshold_free_delivery',
    threshold: 1000000,
    benefitValue: 0,
    originalText: "No audible rule detected."
  };
};

import React, { useRef, useState } from 'react';
import { Upload, FileAudio, FileImage, CheckCircle, AlertCircle, Loader2 } from 'lucide-react';
import { FileType } from '../types';

interface FileUploadProps {
  type: FileType;
  onUpload: (file: File) => Promise<void>;
  label: string;
  subLabel: string;
}

const FileUpload: React.FC<FileUploadProps> = ({ type, onUpload, label, subLabel }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [status, setStatus] = useState<'idle' | 'uploading' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const processFile = async (file: File) => {
    if (!file) return;

    // Validate type
    if (type === 'image' && !file.type.startsWith('image/')) {
      setStatus('error');
      setErrorMessage('Please upload an image file.');
      return;
    }
    if (type === 'audio' && !file.type.startsWith('audio/')) {
      setStatus('error');
      setErrorMessage('Please upload an audio file.');
      return;
    }

    setStatus('uploading');
    try {
      await onUpload(file);
      setStatus('success');
    } catch (e) {
      console.error(e);
      setStatus('error');
      setErrorMessage('Failed to process file. Please try again.');
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  return (
    <div 
      className={`relative border-2 border-dashed rounded-xl p-10 transition-all duration-300 ease-in-out
        ${isDragging ? 'border-blue-500 bg-blue-50' : 'border-slate-300 hover:border-slate-400 bg-white'}
        ${status === 'success' ? 'border-green-500 bg-green-50' : ''}
        ${status === 'error' ? 'border-red-300 bg-red-50' : ''}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileSelect} 
        className="hidden" 
        accept={type === 'image' ? "image/*" : "audio/*"}
      />

      <div className="flex flex-col items-center text-center space-y-4">
        {status === 'uploading' ? (
          <div className="animate-spin text-blue-600">
            <Loader2 size={48} />
          </div>
        ) : status === 'success' ? (
           <div className="text-green-600">
            <CheckCircle size={48} />
          </div>
        ) : status === 'error' ? (
           <div className="text-red-500">
            <AlertCircle size={48} />
          </div>
        ) : (
          <div className={`p-4 rounded-full ${type === 'image' ? 'bg-indigo-100 text-indigo-600' : 'bg-pink-100 text-pink-600'}`}>
             {type === 'image' ? <FileImage size={32} /> : <FileAudio size={32} />}
          </div>
        )}

        <div>
          <h3 className="text-lg font-semibold text-slate-800">
            {status === 'uploading' ? 'Processing...' : status === 'success' ? 'Upload Complete' : label}
          </h3>
          <p className="text-slate-500 mt-1">
            {status === 'error' ? errorMessage : subLabel}
          </p>
        </div>

        {status !== 'uploading' && status !== 'success' && (
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="px-6 py-2 bg-slate-900 text-white rounded-lg font-medium hover:bg-slate-800 transition-colors"
          >
            Select File
          </button>
        )}
      </div>
    </div>
  );
};

export default FileUpload;

import React, { useState, useMemo } from 'react';
import { MenuItem, BusinessRule } from '../types';
import { ShoppingCart, Check, Info, Trash2, Plus, Minus } from 'lucide-react';

interface GeneratedFormProps {
  menuItems: MenuItem[];
  rule: BusinessRule | null;
  onReset: () => void;
}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ menuItems, rule, onReset }) => {
  const [cart, setCart] = useState<Record<string, number>>({});
  const [orderPlaced, setOrderPlaced] = useState(false);

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => {
      const current = prev[itemId] || 0;
      const next = Math.max(0, current + delta);
      const newCart = { ...prev, [itemId]: next };
      if (next === 0) delete newCart[itemId];
      return newCart;
    });
  };

  const cartTotal = useMemo(() => {
    return Object.entries(cart).reduce((total, [id, qty]) => {
      const item = menuItems.find(i => i.id === id);
      return total + (item ? item.price * qty : 0);
    }, 0);
  }, [cart, menuItems]);

  const deliveryFee = 5.00; // Standard fee

  // Apply Rule Logic
  let discount = 0;
  let finalDeliveryFee = deliveryFee;
  let ruleApplied = false;

  if (rule) {
    if (rule.type === 'threshold_free_delivery' && cartTotal > rule.threshold) {
      finalDeliveryFee = 0;
      ruleApplied = true;
    } else if (rule.type === 'threshold_discount' && cartTotal > rule.threshold) {
      discount = cartTotal * (rule.benefitValue / 100);
      ruleApplied = true;
    }
  }

  const finalTotal = cartTotal + finalDeliveryFee - discount;

  // Group items by category
  const categories = useMemo(() => {
    const cats: Record<string, MenuItem[]> = {};
    menuItems.forEach(item => {
      const c = item.category || 'Other';
      if (!cats[c]) cats[c] = [];
      cats[c].push(item);
    });
    return cats;
  }, [menuItems]);

  if (orderPlaced) {
    return (
      <div className="max-w-md mx-auto bg-white rounded-xl shadow-lg p-8 text-center animate-in fade-in zoom-in duration-500">
        <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <Check size={40} />
        </div>
        <h2 className="text-2xl font-bold text-slate-900 mb-2">Order Received!</h2>
        <p className="text-slate-600 mb-8">Your automated order has been processed successfully.</p>
        <button 
          onClick={() => { setOrderPlaced(false); setCart({}); }}
          className="w-full py-3 bg-slate-900 text-white rounded-lg font-semibold hover:bg-slate-800"
        >
          Start New Order
        </button>
        <button 
          onClick={onReset}
          className="w-full mt-4 py-2 text-slate-500 text-sm hover:text-slate-700 underline"
        >
          Back to Architect Mode
        </button>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 h-full">
      {/* Menu Column */}
      <div className="lg:col-span-2 space-y-8 overflow-y-auto pb-20">
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <h1 className="text-2xl font-bold text-slate-900 mb-2">My Generated Restaurant</h1>
          <p className="text-slate-500 text-sm">Automated Menu based on uploaded image</p>
        </div>

        {Object.entries(categories).map(([category, items]) => (
          <div key={category} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="bg-slate-50 px-6 py-3 border-b border-slate-100">
              <h3 className="font-semibold text-slate-700 uppercase tracking-wide text-sm">{category}</h3>
            </div>
            <div className="divide-y divide-slate-100">
              {items.map(item => (
                <div key={item.id} className="p-6 flex justify-between items-center hover:bg-slate-50 transition-colors">
                  <div className="flex-1 pr-4">
                    <h4 className="font-medium text-slate-900">{item.name}</h4>
                    {item.description && <p className="text-slate-500 text-sm mt-1">{item.description}</p>}
                    <p className="text-indigo-600 font-semibold mt-2">${item.price.toFixed(2)}</p>
                  </div>
                  <div className="flex items-center space-x-3">
                    {cart[item.id] ? (
                      <>
                        <button 
                          onClick={() => updateQuantity(item.id, -1)}
                          className="w-8 h-8 rounded-full border border-slate-300 flex items-center justify-center text-slate-600 hover:bg-slate-100"
                        >
                          <Minus size={16} />
                        </button>
                        <span className="w-6 text-center font-medium">{cart[item.id]}</span>
                        <button 
                          onClick={() => updateQuantity(item.id, 1)}
                          className="w-8 h-8 rounded-full bg-slate-900 text-white flex items-center justify-center hover:bg-slate-700"
                        >
                          <Plus size={16} />
                        </button>
                      </>
                    ) : (
                      <button 
                        onClick={() => updateQuantity(item.id, 1)}
                        className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 text-sm font-medium hover:border-slate-400 hover:bg-slate-50 transition-all"
                      >
                        Add
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Cart Column (Sticky) */}
      <div className="lg:col-span-1">
        <div className="sticky top-6 bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden flex flex-col">
          <div className="p-4 bg-slate-900 text-white flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <ShoppingCart size={20} />
              <span className="font-semibold">Your Order</span>
            </div>
            <span className="bg-slate-700 px-2 py-0.5 rounded text-xs font-mono">LIVE PREVIEW</span>
          </div>

          <div className="p-6 flex-1 overflow-y-auto max-h-[calc(100vh-300px)]">
            {Object.keys(cart).length === 0 ? (
              <div className="text-center py-10 text-slate-400">
                <ShoppingCart size={48} className="mx-auto mb-3 opacity-20" />
                <p>Your cart is empty</p>
              </div>
            ) : (
              <div className="space-y-4">
                {Object.entries(cart).map(([id, qty]) => {
                  const item = menuItems.find(i => i.id === id);
                  if (!item) return null;
                  return (
                    <div key={id} className="flex justify-between items-start text-sm">
                      <div className="flex-1">
                        <span className="font-medium text-slate-800">{item.name}</span>
                        <div className="text-slate-500 text-xs">x{qty}</div>
                      </div>
                      <div className="flex items-center space-x-3">
                        <span className="font-medium text-slate-900">${(item.price * qty).toFixed(2)}</span>
                        <button onClick={() => updateQuantity(id, -qty)} className="text-slate-300 hover:text-red-500">
                          <Trash2 size={14} />
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          <div className="bg-slate-50 p-6 border-t border-slate-100">
             {/* Dynamic Rule Display */}
             {rule && (
              <div className={`mb-4 p-3 rounded-lg border flex items-start space-x-2 text-xs
                ${ruleApplied ? 'bg-green-50 border-green-200 text-green-700' : 'bg-blue-50 border-blue-200 text-blue-700'}
              `}>
                <Info size={16} className="shrink-0 mt-0.5" />
                <div>
                  <span className="font-semibold block mb-0.5">Automated Rule Active:</span>
                  "{rule.originalText}"
                  {!ruleApplied && (
                    <div className="mt-1 text-slate-500">
                      Add ${(rule.threshold - cartTotal).toFixed(2)} more to qualify.
                    </div>
                  )}
                </div>
              </div>
            )}

            <div className="space-y-2 text-sm mb-6">
              <div className="flex justify-between text-slate-600">
                <span>Subtotal</span>
                <span>${cartTotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-slate-600">
                <span>Delivery</span>
                <span className={finalDeliveryFee === 0 ? 'text-green-600 font-bold' : ''}>
                  {finalDeliveryFee === 0 ? 'FREE' : `$${deliveryFee.toFixed(2)}`}
                </span>
              </div>
              {discount > 0 && (
                 <div className="flex justify-between text-green-600">
                 <span>Discount</span>
                 <span>-${discount.toFixed(2)}</span>
               </div>
              )}
              <div className="flex justify-between text-lg font-bold text-slate-900 pt-2 border-t border-slate-200">
                <span>Total</span>
                <span>${finalTotal.toFixed(2)}</span>
              </div>
            </div>

            <button 
              disabled={Object.keys(cart).length === 0}
              onClick={() => setOrderPlaced(true)}
              className="w-full py-3 bg-indigo-600 text-white rounded-lg font-semibold hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-md hover:shadow-lg"
            >
              Place Order
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GeneratedForm;

import React, { useState } from 'react';
import { ArrowRight, Bot, Zap, Image as ImageIcon, Mic } from 'lucide-react';
import FileUpload from './components/FileUpload';
import GeneratedForm from './components/GeneratedForm';
import { AppState, MenuItem, BusinessRule } from './types';
import { extractMenuFromImage, extractRuleFromAudio, fileToGenerativePart } from './services/gemini';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    menuItems: [],
    rule: null,
    step: 'upload-menu',
    isLoading: false,
    loadingMessage: ''
  });

  const handleMenuUpload = async (file: File) => {
    setState(prev => ({ ...prev, isLoading: true, loadingMessage: 'Analyzing menu structure and extracting items...' }));
    try {
      const base64 = await fileToGenerativePart(file);
      const items = await extractMenuFromImage(base64, file.type);

      // Simulate a small delay for better UX if extraction is too fast
      await new Promise(r => setTimeout(r, 800));

      setState(prev => ({ 
        ...prev, 
        menuItems: items, 
        step: 'upload-rule', 
        isLoading: false 
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({ ...prev, isLoading: false }));
      alert("Failed to analyze menu image. Please try another image.");
    }
  };

  const handleRuleUpload = async (file: File) => {
    setState(prev => ({ ...prev, isLoading: true, loadingMessage: 'Listening to audio logic and synthesizing business rules...' }));
    try {
      const base64 = await fileToGenerativePart(file);
      const rule = await extractRuleFromAudio(base64, file.type);

      await new Promise(r => setTimeout(r, 800));

      setState(prev => ({ 
        ...prev, 
        rule: rule, 
        step: 'preview-app', 
        isLoading: false 
      }));
    } catch (error) {
      console.error(error);
      setState(prev => ({ ...prev, isLoading: false }));
      alert("Failed to process audio rule. Please try again.");
    }
  };

  const handleReset = () => {
    setState({
      menuItems: [],
      rule: null,
      step: 'upload-menu',
      isLoading: false,
      loadingMessage: ''
    });
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans selection:bg-indigo-100 selection:text-indigo-800">

      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="bg-indigo-600 p-2 rounded-lg">
              <Zap className="text-white h-5 w-5" />
            </div>
            <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600">
              BizFlow Architect
            </span>
          </div>
          <div className="flex items-center space-x-4 text-sm text-slate-500">
            <div className={`flex items-center space-x-2 ${state.step === 'upload-menu' ? 'text-indigo-600 font-medium' : ''}`}>
              <span className="flex items-center justify-center w-6 h-6 rounded-full border border-current text-xs">1</span>
              <span>Input Data</span>
            </div>
            <div className="h-px w-8 bg-slate-300"></div>
            <div className={`flex items-center space-x-2 ${state.step === 'upload-rule' ? 'text-indigo-600 font-medium' : ''}`}>
              <span className="flex items-center justify-center w-6 h-6 rounded-full border border-current text-xs">2</span>
              <span>Define Logic</span>
            </div>
            <div className="h-px w-8 bg-slate-300"></div>
            <div className={`flex items-center space-x-2 ${state.step === 'preview-app' ? 'text-indigo-600 font-medium' : ''}`}>
              <span className="flex items-center justify-center w-6 h-6 rounded-full border border-current text-xs">3</span>
              <span>Live App</span>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">

        {/* Loading Overlay */}
        {state.isLoading && (
          <div className="fixed inset-0 bg-white/80 backdrop-blur-sm z-50 flex items-center justify-center">
            <div className="text-center max-w-md mx-auto p-8">
              <div className="relative w-24 h-24 mx-auto mb-8">
                 <div className="absolute inset-0 border-t-4 border-indigo-600 border-solid rounded-full animate-spin"></div>
                 <div className="absolute inset-4 bg-indigo-50 rounded-full flex items-center justify-center">
                   <Bot className="text-indigo-600" size={32} />
                 </div>
              </div>
              <h3 className="text-xl font-bold text-slate-800 mb-2">AI Architect Working</h3>
              <p className="text-slate-500">{state.loadingMessage}</p>
            </div>
          </div>
        )}

        {/* Step 1: Upload Menu */}
        {state.step === 'upload-menu' && (
          <div className="max-w-2xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="text-center mb-10">
              <h1 className="text-4xl font-bold text-slate-900 mb-4">Digitize Your Business</h1>
              <p className="text-lg text-slate-600">Start by uploading a photo of your menu, inventory list, or catalog.</p>
            </div>

            <div className="bg-white p-8 rounded-2xl shadow-xl border border-slate-100">
              <div className="flex items-center space-x-4 mb-6">
                <div className="p-3 bg-indigo-100 text-indigo-600 rounded-lg">
                  <ImageIcon size={24} />
                </div>
                <div>
                  <h2 className="text-xl font-semibold text-slate-900">Input Source: Vision</h2>
                  <p className="text-slate-500 text-sm">Extracts items, prices, and categories from images.</p>
                </div>
              </div>

              <FileUpload 
                type="image" 
                label="Upload Menu Image" 
                subLabel="Supports JPG, PNG (Max 5MB)"
                onUpload={handleMenuUpload} 
              />

              <div className="mt-6 flex justify-between items-center text-sm text-slate-400">
                <span>Example: Handwritten chalkboard, Printed menu</span>
                <span className="bg-slate-100 px-2 py-1 rounded text-slate-500">Step 1 of 3</span>
              </div>
            </div>
          </div>
        )}

        {/* Step 2: Upload Rule */}
