import React, { useRef, useState } from 'react';
import { Upload, FileAudio, FileImage, CheckCircle, AlertCircle, Loader2 } from 'lucide-react';
import { FileType } from '../types';

interface FileUploadProps {
  type: FileType;
  onUpload: (file: File) => void;
  label: string;
  subLabel: string;
  currentFile?: File | null;
}

const FileUpload: React.FC<FileUploadProps> = ({ type, onUpload, label, subLabel, currentFile }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const processFile = (file: File) => {
    if (!file) return;

    // Validate type
    if (type === 'image' && !file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }
    if (type === 'audio' && !file.type.startsWith('audio/')) {
      alert('Please upload an audio file.');
      return;
    }
    onUpload(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const hasFile = !!currentFile;

  return (
    <div 
      className={`relative group border rounded-xl p-8 transition-all duration-300 ease-in-out cursor-pointer
        ${isDragging ? 'border-indigo-500 bg-slate-800 scale-[1.02]' : 'border-slate-700 bg-slate-800/50 hover:bg-slate-800 hover:border-indigo-500/50 hover:shadow-2xl hover:-translate-y-1'}
        ${hasFile ? 'border-green-500/50 bg-slate-800' : ''}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => fileInputRef.current?.click()}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileSelect} 
        className="hidden" 
        accept={type === 'image' ? "image/*" : "audio/*"}
      />

      <div className="flex flex-col items-center text-center space-y-4">
        {hasFile ? (
           <div className="text-green-400 bg-green-400/10 p-4 rounded-full mb-2 shadow-[0_0_15px_rgba(74,222,128,0.3)]">
            <CheckCircle size={32} />
          </div>
        ) : (
          <div className={`p-4 rounded-full transition-colors duration-300 ${type === 'image' ? 'bg-indigo-500/20 text-indigo-400 group-hover:bg-indigo-500/30' : 'bg-pink-500/20 text-pink-400 group-hover:bg-pink-500/30'}`}>
             {type === 'image' ? <FileImage size={32} /> : <FileAudio size={32} />}
          </div>
        )}

        <div>
          <h3 className="text-lg font-semibold text-slate-100">
            {hasFile ? currentFile.name : label}
          </h3>
          <p className="text-slate-400 text-sm mt-1">
            {hasFile ? 'Click to replace' : subLabel}
          </p>
        </div>
      </div>
    </div>
  );
};

export default FileUpload;

import React, { useState, useMemo } from 'react';
import { MenuItem, BusinessRule } from '../types';
import { ShoppingCart, Check, Info, Trash2, Plus, Minus, Truck, Tag, ArrowLeft } from 'lucide-react';

interface GeneratedFormProps {
  menuItems: MenuItem[];
  rule: BusinessRule | null;
  onReset: () => void;
}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ menuItems, rule, onReset }) => {
  const [cart, setCart] = useState<Record<string, number>>({});
  const [orderPlaced, setOrderPlaced] = useState(false);

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => {
      const current = prev[itemId] || 0;
      const next = Math.max(0, current + delta);
      const newCart = { ...prev, [itemId]: next };
      if (next === 0) delete newCart[itemId];
      return newCart;
    });
  };

  const cartTotal = useMemo(() => {
    return Object.entries(cart).reduce((total, [id, qty]) => {
      const item = menuItems.find(i => i.id === id);
      return total + (item ? item.price * qty : 0);
    }, 0);
  }, [cart, menuItems]);

  const deliveryFee = 5.00;

  // Apply Rule Logic
  let discount = 0;
  let finalDeliveryFee = deliveryFee;
  let ruleApplied = false;

  if (rule) {
    if (rule.type === 'threshold_free_delivery' && cartTotal >= rule.threshold) {
      finalDeliveryFee = 0;
      ruleApplied = true;
    } else if (rule.type === 'threshold_discount' && cartTotal >= rule.threshold) {
      discount = cartTotal * (rule.benefitValue / 100);
      ruleApplied = true;
    }
  }

  const finalTotal = cartTotal + finalDeliveryFee - discount;

  const categories = useMemo(() => {
    const cats: Record<string, MenuItem[]> = {};
    menuItems.forEach(item => {
      const c = item.category || 'Other';
      if (!cats[c]) cats[c] = [];
      cats[c].push(item);
    });
    return cats;
  }, [menuItems]);

  if (orderPlaced) {
    return (
      <div className="max-w-md mx-auto bg-slate-800 rounded-xl shadow-2xl p-8 text-center animate-in fade-in zoom-in duration-500 border border-slate-700">
        <div className="w-20 h-20 bg-green-500/20 text-green-400 rounded-full flex items-center justify-center mx-auto mb-6">
          <Check size={40} />
        </div>
        <h2 className="text-2xl font-bold text-white mb-2">Order Received!</h2>
        <p className="text-slate-400 mb-8">Your automated order has been processed successfully.</p>
        <button 
          onClick={() => { setOrderPlaced(false); setCart({}); }}
          className="w-full py-3 bg-indigo-600 text-white rounded-lg font-semibold hover:bg-indigo-500 transition-colors"
        >
          Start New Order
        </button>
        <button 
          onClick={onReset}
          className="w-full mt-4 py-2 text-slate-500 text-sm hover:text-slate-400 underline"
        >
          Back to Architect Mode
        </button>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-140px)]">
        {/* Header Bar for Live App */}
        <div className="flex items-center justify-between mb-6">
             <button onClick={onReset} className="flex items-center space-x-2 text-slate-400 hover:text-white transition-colors">
                <ArrowLeft size={20} />
                <span>Exit Preview</span>
             </button>
             <div className="px-3 py-1 bg-green-500/20 text-green-400 text-xs font-mono rounded-full border border-green-500/30">
                LIVE APP RUNNING
             </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 flex-1 overflow-hidden">
        {/* Menu Column */}
        <div className="lg:col-span-2 space-y-6 overflow-y-auto pr-2 pb-20 custom-scrollbar">
            <div className="bg-slate-800 rounded-xl shadow-lg border border-slate-700 p-6 flex justify-between items-end bg-gradient-to-br from-slate-800 to-slate-900">
            <div>
                <h1 className="text-2xl font-bold text-white mb-2">My Generated Restaurant</h1>
                <p className="text-slate-400 text-sm">Automated Menu System</p>
            </div>
            {rule && rule.type === 'threshold_free_delivery' && (
                <div className="hidden sm:flex items-center space-x-2 bg-green-500/10 text-green-400 px-3 py-2 rounded-lg text-sm font-medium border border-green-500/20">
                <Truck size={18} />
                <span>Free Delivery over ${rule.threshold}</span>
                </div>
            )}
            </div>

            {Object.keys(categories).length === 0 ? (
            <div className="bg-slate-800 rounded-xl p-12 text-center text-slate-500 border border-dashed border-slate-700">
                <p>No menu items found.</p>
            </div>
            ) : (
            Object.entries(categories).map(([category, items]) => (
                <div key={category} className="bg-slate-800 rounded-xl shadow-lg border border-slate-700 overflow-hidden">
                <div className="bg-slate-900/50 px-6 py-3 border-b border-slate-700">
                    <h3 className="font-semibold text-indigo-400 uppercase tracking-wide text-xs">{category}</h3>
                </div>
                <div className="divide-y divide-slate-700">
                    {items.map(item => (
                    <div key={item.id} className="p-6 flex justify-between items-center hover:bg-slate-700/30 transition-colors">
                        <div className="flex-1 pr-4">
                        <h4 className="font-medium text-slate-200 text-lg">{item.name}</h4>
                        {item.description && <p className="text-slate-500 text-sm mt-1">{item.description}</p>}
                        <p className="text-indigo-400 font-semibold mt-2">${item.price.toFixed(2)}</p>
                        </div>
                        <div className="flex items-center space-x-3">
                        {cart[item.id] ? (
                            <>
                            <button 
                                onClick={() => updateQuantity(item.id, -1)}
                                className="w-8 h-8 rounded-full border border-slate-600 flex items-center justify-center text-slate-400 hover:bg-slate-700 hover:text-white"
                            >
                                <Minus size={16} />
                            </button>
                            <span className="w-6 text-center font-medium text-white">{cart[item.id]}</span>
                            <button 
                                onClick={() => updateQuantity(item.id, 1)}
                                className="w-8 h-8 rounded-full bg-indigo-600 text-white flex items-center justify-center hover:bg-indigo-500"
                            >
                                <Plus size={16} />
                            </button>
                            </>
                        ) : (
                            <button 
                            onClick={() => updateQuantity(item.id, 1)}
                            className="px-4 py-2 bg-slate-700 border border-slate-600 rounded-lg text-slate-300 text-sm font-medium hover:border-slate-500 hover:text-white hover:bg-slate-600 transition-all"
                            >
                            Add
                            </button>
                        )}
                        </div>
                    </div>
                    ))}
                </div>
                </div>
            ))
            )}
        </div>

        {/* Cart Column (Sticky) */}
        <div className="lg:col-span-1">
            <div className="bg-slate-800 rounded-xl shadow-xl border border-slate-700 overflow-hidden flex flex-col h-[calc(100vh-200px)] sticky top-0">
            <div className="p-4 bg-slate-900 text-white flex items-center justify-between border-b border-slate-700">
                <div className="flex items-center space-x-2">
                <ShoppingCart size={20} />
                <span className="font-semibold">Your Order</span>
                </div>
            </div>

            <div className="p-6 flex-1 overflow-y-auto custom-scrollbar">
                {Object.keys(cart).length === 0 ? (
                <div className="text-center py-10 text-slate-600">
                    <ShoppingCart size={48} className="mx-auto mb-3 opacity-20" />
                    <p>Your cart is empty</p>
                </div>
                ) : (
                <div className="space-y-4">
                    {Object.entries(cart).map(([id, qty]) => {
                    const item = menuItems.find(i => i.id === id);
                    if (!item) return null;
                    return (
                        <div key={id} className="flex justify-between items-start text-sm">
                        <div className="flex-1">
                            <span className="font-medium text-slate-200">{item.name}</span>
                            <div className="text-slate-500 text-xs">x{qty}</div>
                        </div>
                        <div className="flex items-center space-x-3">
                            <span className="font-medium text-white">${(item.price * qty).toFixed(2)}</span>
                            <button onClick={() => updateQuantity(id, -qty)} className="text-slate-500 hover:text-red-400 transition-colors">
                            <Trash2 size={14} />
                            </button>
                        </div>
                        </div>
                    );
                    })}
                </div>
                )}
            </div>

            <div className="bg-slate-900/50 p-6 border-t border-slate-700">
                {/* Dynamic Rule Display */}
                {rule && (
                <div className={`mb-4 p-3 rounded-lg border flex items-start space-x-3 text-xs transition-colors duration-300
                    ${ruleApplied 
                        ? 'bg-green-500/10 border-green-500/30 text-green-400' 
                        : 'bg-indigo-500/10 border-indigo-500/30 text-indigo-400'}
                `}>
                    <div className={`mt-0.5 p-1 rounded-full ${ruleApplied ? 'bg-green-500/20' : 'bg-indigo-500/20'}`}>
                    {rule.type === 'threshold_free_delivery' ? <Truck size={14} /> : <Tag size={14} />}
                    </div>
                    <div>
                    <span className="font-bold block mb-0.5 text-white">
                        {rule.type === 'threshold_free_delivery' ? 'Free Delivery Offer' : 'Special Discount'}
                    </span>
                    <div className="italic mb-1 opacity-80">"{rule.originalText}"</div>
                    {!ruleApplied && (
                        <div className="font-medium mt-1">
                        Add <span className="underline font-bold text-white">${(rule.threshold - cartTotal).toFixed(2)}</span> more to qualify.
                        </div>
                    )}
                    {ruleApplied && (
                        <div className="font-bold flex items-center mt-1 text-white">
                        <Check size={12} className="mr-1" /> Offer Applied!
                        </div>
                    )}
                    </div>
                </div>
                )}

                <div className="space-y-2 text-sm mb-6">
                <div className="flex justify-between text-slate-400">
                    <span>Subtotal</span>
                    <span>${cartTotal.toFixed(2)}</span>
                </div>
                <div className="flex justify-between text-slate-400">
                    <span>Delivery</span>
                    <span className={finalDeliveryFee === 0 ? 'text-green-400 font-bold' : ''}>
                    {finalDeliveryFee === 0 ? 'FREE' : `$${deliveryFee.toFixed(2)}`}
                    </span>
                </div>
                {discount > 0 && (
                    <div className="flex justify-between text-green-400 font-medium">
                    <span>Discount applied</span>
                    <span>-${discount.toFixed(2)}</span>
                </div>
                )}
                <div className="flex justify-between text-lg font-bold text-white pt-2 border-t border-slate-700">
                    <span>Total</span>
                    <span>${finalTotal.toFixed(2)}</span>
                </div>
                </div>

                <button 
                disabled={Object.keys(cart).length === 0}
                onClick={() => setOrderPlaced(true)}
                className="w-full py-3 bg-indigo-600 text-white rounded-lg font-semibold hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg hover:shadow-indigo-500/25"
                >
                Place Order
                </button>
            </div>
            </div>
        </div>
        </div>
    </div>
  );
};

