import React, { useState } from 'react';
import { Bot, Zap, Image as ImageIcon, Mic, Layout, FileText, ArrowRight } from 'lucide-react';
import FileUpload from './components/FileUpload';
import GeneratedForm from './components/GeneratedForm';
import AnalysisReview from './components/AnalysisReview';
import { AppState, MenuItem, BusinessRule } from './types';
import { extractMenuFromImages, extractRuleFromAudio, extractRuleFromText, fileToGenerativePart } from './services/gemini';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    uploadedImages: [],
    uploadedAudio: null,
    manualRuleText: '',
    menuItems: [],
    rule: null,
    step: 'input',
    isLoading: false,
    loadingMessage: ''
  });

  const handleImageUpload = (file: File) => {
    // For this hackathon MVP, we'll replace the image, but logic supports arrays
    setState(prev => ({ ...prev, uploadedImages: [file] }));
  };

  const handleAudioUpload = (file: File) => {
    setState(prev => ({ ...prev, uploadedAudio: file, manualRuleText: '' })); // clear text if audio uploaded
  };

  const handleAnalyze = async () => {
    if (state.uploadedImages.length === 0) {
      alert("Please upload a menu image first.");
      return;
    }

    setState(prev => ({ ...prev, isLoading: true, loadingMessage: 'Processing Multimodal Inputs...' }));

    try {
      // 1. Process Images
      const imageParts = await Promise.all(state.uploadedImages.map(fileToGenerativePart));

      // 2. Process Logic (Audio OR Text)
      let rule: BusinessRule | null = null;

      if (state.uploadedAudio) {
        const audioPart = await fileToGenerativePart(state.uploadedAudio);
        rule = await extractRuleFromAudio(audioPart.inlineData.data, audioPart.inlineData.mimeType);
      } else if (state.manualRuleText.trim().length > 0) {
        rule = await extractRuleFromText(state.manualRuleText);
      }

      // 3. Extract Menu
      const items = await extractMenuFromImages(imageParts);

      setState(prev => ({
        ...prev,
        menuItems: items,
        rule: rule,
        step: 'review',
        isLoading: false
      }));

    } catch (e) {
      console.error(e);
      setState(prev => ({ ...prev, isLoading: false }));
      alert("Analysis failed. Please check your inputs and try again.");
    }
  };

  const handleReset = () => {
    setState({
      uploadedImages: [],
      uploadedAudio: null,
      manualRuleText: '',
      menuItems: [],
      rule: null,
      step: 'input',
      isLoading: false,
      loadingMessage: ''
    });
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans selection:bg-indigo-500/30 selection:text-indigo-200 flex flex-col">

      {/* Header with Stepper */}
      <header className="bg-slate-900/80 backdrop-blur-md border-b border-slate-800 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-2 rounded-xl shadow-lg shadow-indigo-500/20">
              <Zap className="text-white h-6 w-6" />
            </div>
            <div>
                <h1 className="text-xl font-bold text-white tracking-tight">BizFlow Architect</h1>
                <p className="text-xs text-slate-400">Gemini 3 Pro Powered</p>
            </div>
          </div>

          {/* Stepper */}
          <div className="hidden md:flex items-center space-x-4">
             {['input', 'review', 'app'].map((s, idx) => {
                const isActive = state.step === s;
                const isCompleted = (state.step === 'review' && idx === 0) || (state.step === 'app' && idx < 2);

                return (
                    <div key={s} className="flex items-center">
                        <div className={`
                            flex items-center space-x-2 px-4 py-2 rounded-full border transition-all duration-300
                            ${isActive ? 'bg-indigo-500/10 border-indigo-500 text-indigo-400' : 
                              isCompleted ? 'bg-green-500/10 border-green-500/50 text-green-400' : 'border-transparent text-slate-600'}
                        `}>
                            <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold
                                ${isActive ? 'bg-indigo-500 text-white' : 
                                  isCompleted ? 'bg-green-500 text-slate-900' : 'bg-slate-800 text-slate-500'}
                            `}>
                                {idx + 1}
                            </div>
                            <span className="capitalize font-medium text-sm">
                                {s === 'input' ? 'Input Data' : s === 'review' ? 'Analysis' : 'Live App'}
                            </span>
                        </div>
                        {idx < 2 && <div className="w-8 h-px bg-slate-800 ml-4"></div>}
                    </div>
                );
             })}
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full relative">

        {/* Loading Overlay */}
        {state.isLoading && (
          <div className="absolute inset-0 bg-slate-900/90 backdrop-blur-sm z-50 flex flex-col items-center justify-center rounded-xl animate-in fade-in duration-300">
             <div className="relative mb-8">
                 <div className="w-24 h-24 border-t-4 border-indigo-500 border-solid rounded-full animate-spin"></div>
                 <div className="absolute inset-0 flex items-center justify-center">
                   <Bot className="text-indigo-400 animate-pulse" size={40} />
                 </div>
              </div>
              <h3 className="text-2xl font-bold text-white mb-2">Architecting Solution...</h3>
              <p className="text-slate-400 font-mono">{state.loadingMessage}</p>
          </div>
        )}

        {/* STEP 1: INPUT */}
        {state.step === 'input' && (
          <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
             <div className="text-center mb-12">
              <h1 className="text-4xl md:text-5xl font-bold text-white mb-6 bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 via-purple-400 to-indigo-400">
                Transform Chaos into Code
              </h1>
              <p className="text-lg text-slate-400 max-w-2xl mx-auto">
                Upload your raw business documents and voice notes. We'll synthesize a fully functional application in seconds.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
                {/* Visual Input Card */}
                <div className="space-y-4">
                    <div className="flex items-center space-x-3 mb-2">
                        <div className="p-2 bg-indigo-500/20 rounded-lg text-indigo-400"><ImageIcon size={20} /></div>
                        <h2 className="text-xl font-semibold text-white">1. Visual Source</h2>
