                {/* Logic Input Card */}
                <div className="space-y-4">
                    <div className="flex items-center space-x-3 mb-2">
                        <div className="p-2 bg-pink-500/20 rounded-lg text-pink-400"><Layout size={20} /></div>
                        <h2 className="text-xl font-semibold text-white">2. Business Logic</h2>
                    </div>

                    <div className="bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-xl relative overflow-hidden group">
                        {/* Tab-like switching effect could go here, but keeping it simple: Split view */}
                        <div className="p-6 space-y-6">

                            {/* Option A: Audio */}
                            <div className={state.manualRuleText ? "opacity-40 grayscale transition-all" : "transition-all"}>
                                <div className="flex items-center justify-between mb-2">
                                    <span className="text-sm font-medium text-slate-300 flex items-center gap-2">
                                        <Mic size={14} /> Voice Rule
                                    </span>
                                </div>
                                <FileUpload 
                                    type="audio"
                                    label="Upload Voice Note"
                                    subLabel="MP3, WAV"
                                    onUpload={handleAudioUpload}
                                    currentFile={state.uploadedAudio}
                                />
                            </div>

                            <div className="relative flex items-center py-2">
                                <div className="flex-grow border-t border-slate-700"></div>
                                <span className="flex-shrink-0 mx-4 text-slate-500 text-xs uppercase font-bold tracking-widest">OR</span>
                                <div className="flex-grow border-t border-slate-700"></div>
                            </div>

                             {/* Option B: Text */}
                             <div className={state.uploadedAudio ? "opacity-40 pointer-events-none transition-all" : "transition-all"}>
                                <label className="text-sm font-medium text-slate-300 flex items-center gap-2 mb-3">
                                    <FileText size={14} /> Manual Entry
                                </label>
                                <textarea
                                    value={state.manualRuleText}
                                    onChange={(e) => setState(prev => ({ ...prev, manualRuleText: e.target.value, uploadedAudio: null }))}
                                    placeholder="e.g. If orders are above $50, delivery is free."
                                    className="w-full h-24 bg-slate-900/50 border border-slate-700 rounded-lg p-4 text-slate-200 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none resize-none placeholder-slate-600 transition-all hover:bg-slate-900"
                                />
                             </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex justify-center">
                <button
                    onClick={handleAnalyze}
                    disabled={state.uploadedImages.length === 0}
                    className="group relative inline-flex items-center justify-center px-8 py-4 font-bold text-white transition-all duration-200 bg-indigo-600 font-lg rounded-full focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-600 hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_20px_rgba(79,70,229,0.3)] hover:shadow-[0_0_30px_rgba(79,70,229,0.5)]"
                >
                    <span>Process & Analyze</span>
                    <ArrowRight className="ml-2 -mr-1 w-5 h-5 group-hover:translate-x-1 transition-transform" />
