                menuItems={state.menuItems}
                rule={state.rule}
                onBack={() => setState(prev => ({ ...prev, step: 'input' }))}
                onConfirm={() => setState(prev => ({ ...prev, step: 'app' }))}
             />
        )}

        {/* STEP 3: APP */}
        {state.step === 'app' && (
             <GeneratedForm 
               menuItems={state.menuItems} 
               rule={state.rule} 
               onReset={handleReset}
             />
        )}

      </main>
    </div>
  );
};

