import React, { useRef, useState } from 'react';
import { Upload, FileAudio, FileImage, CheckCircle, AlertCircle, Loader2, X } from 'lucide-react';
import { FileType } from '../types';

interface FileUploadProps {
  type: FileType;
  onUpload: (file: File) => void;
  label: string;
  subLabel: string;
  currentFile?: File | null;
  onRemove?: () => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ type, onUpload, label, subLabel, currentFile, onRemove }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const processFile = (file: File) => {
    if (!file) return;

    // Validate type
    if (type === 'image' && !file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }
    if (type === 'audio' && !file.type.startsWith('audio/')) {
      alert('Please upload an audio file.');
      return;
    }
    onUpload(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const hasFile = !!currentFile;

  return (
    <div 
      className={`relative group border rounded-xl p-8 transition-all duration-300 ease-in-out cursor-pointer
        ${isDragging ? 'border-indigo-500 bg-slate-800 scale-[1.02]' : 'border-slate-700 bg-slate-800/50 hover:bg-slate-800 hover:border-indigo-500/50 hover:shadow-2xl hover:-translate-y-1'}
        ${hasFile ? 'border-green-500/50 bg-slate-800' : ''}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => fileInputRef.current?.click()}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileSelect} 
        className="hidden" 
        accept={type === 'image' ? "image/*" : "audio/*"}
      />

      {hasFile && onRemove && (
        <button
          onClick={(e) => {
            e.stopPropagation();
            onRemove();
          }}
          className="absolute top-3 right-3 p-2 bg-slate-700/80 hover:bg-red-500/20 text-slate-400 hover:text-red-400 rounded-full transition-colors z-10 backdrop-blur-sm"
          title="Remove file"
        >
          <X size={18} />
        </button>
      )}

      <div className="flex flex-col items-center text-center space-y-4">
        {hasFile ? (
           <div className="text-green-400 bg-green-400/10 p-4 rounded-full mb-2 shadow-[0_0_15px_rgba(74,222,128,0.3)]">
            <CheckCircle size={32} />
          </div>
        ) : (
          <div className={`p-4 rounded-full transition-colors duration-300 ${type === 'image' ? 'bg-indigo-500/20 text-indigo-400 group-hover:bg-indigo-500/30' : 'bg-pink-500/20 text-pink-400 group-hover:bg-pink-500/30'}`}>
             {type === 'image' ? <FileImage size={32} /> : <FileAudio size={32} />}
          </div>
        )}

        <div>
          <h3 className="text-lg font-semibold text-slate-100 max-w-[200px] truncate mx-auto">
            {hasFile ? currentFile.name : label}
          </h3>
          <p className="text-slate-400 text-sm mt-1">
            {hasFile ? 'Click to replace' : subLabel}
          </p>
        </div>
      </div>
    </div>
  );
};

