import { GoogleGenAI, Type } from "@google/genai";
import { GenericItem, BusinessRule } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Helper to convert file to base64
export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type
        }
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const extractDataFromImages = async (imageParts: Array<{ inlineData: { data: string; mimeType: string } }>): Promise<GenericItem[]> => {
  const modelId = "gemini-2.5-flash";

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        ...imageParts,
        {
          text: `You are an expert business data digitizer. 
          Analyze the provided image(s), which could be an invoice, inventory list, product catalog, restaurant menu, or service price list.

          Extract all actionable items into a structured JSON list.

          For each item, identify:
          - id: A unique generic string identifier (e.g., "item_1", "item_2").
          - name: The name of the item, service, or product.
          - value: The primary numeric value associated (Price, Unit Cost, Fee). Strip currency symbols.
          - category: The section or group (e.g., "Services", "Materials", "Labor", "Mains"). Infer if not explicit.
          - description: Any details, SKUs, or specs (optional).

          Ensure accuracy for handwritten or printed text. Ignore non-item text like addresses or headers.`
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            name: { type: Type.STRING },
            value: { type: Type.NUMBER },
            category: { type: Type.STRING },
            description: { type: Type.STRING },
          },
          required: ["id", "name", "value", "category"]
        }
      }
    }
  });

  if (response.text) {
    try {
      return JSON.parse(response.text) as GenericItem[];
    } catch (e) {
      console.error("Failed to parse extracted items JSON", e);
      return [];
    }
  }
  return [];
};

const RULE_PROMPT = `You are a business logic engine. Analyze the provided input (audio or text) describing a business rule, condition, or promotion.

Extract the single most prominent rule that affects the total value.

Supported Rule Types:
1. "threshold_free_delivery": e.g., "Waive shipping/delivery fees if total is over $500".
    - set 'threshold' to the amount.
    - set 'benefitValue' to 0.

2. "threshold_discount": e.g., "Spend $1000 and get 10% discount".
    - set 'threshold' to the amount.
    - set 'benefitValue' to the percentage number (e.g., 10).

If no conditional rule is found, return a null-like object.
Capture the 'originalText' exactly as stated.`;

const RULE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    type: { type: Type.STRING, enum: ["threshold_free_delivery", "threshold_discount"] },
    threshold: { type: Type.NUMBER },
    benefitValue: { type: Type.NUMBER },
    originalText: { type: Type.STRING }
  },
  required: ["type", "threshold", "benefitValue", "originalText"]
};

export const extractRuleFromAudio = async (base64Audio: string, mimeType: string): Promise<BusinessRule> => {
  const modelId = "gemini-2.5-flash";

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        { inlineData: { data: base64Audio, mimeType: mimeType } },
        { text: RULE_PROMPT }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: RULE_SCHEMA
    }
  });

  if (response.text) {
    try { return JSON.parse(response.text) as BusinessRule; } catch (e) { console.error(e); }
  }
  return getDefaultRule();
};

export const extractRuleFromText = async (textRule: string): Promise<BusinessRule> => {
  const modelId = "gemini-2.5-flash";

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        { text: `Input Text Rule: "${textRule}"\n\n${RULE_PROMPT}` }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: RULE_SCHEMA
    }
  });

  if (response.text) {
    try { return JSON.parse(response.text) as BusinessRule; } catch (e) { console.error(e); }
  }
  return getDefaultRule();
};

function getDefaultRule(): BusinessRule {
  return {
    type: 'threshold_free_delivery',
    threshold: 1000000,
    benefitValue: 0,
    originalText: "No specific rule detected."
  };
}

import React, { useRef, useState } from 'react';
import { FileAudio, FileImage, CheckCircle, X } from 'lucide-react';
