interface FileUploadProps {
  type: FileType;
  onUpload: (file: File) => void;
  label: string;
  subLabel: string;
  currentFile?: File | null;
  onRemove?: () => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ type, onUpload, label, subLabel, currentFile, onRemove }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const processFile = (file: File) => {
    if (!file) return;
    if (type === 'image' && !file.type.startsWith('image/')) {
      alert('Please upload an image file.');
      return;
    }
    if (type === 'audio' && !file.type.startsWith('audio/')) {
      alert('Please upload an audio file.');
      return;
    }
    onUpload(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const hasFile = !!currentFile;

  return (
    <div 
      className={`relative group border rounded-2xl p-8 transition-all duration-300 ease-out cursor-pointer
        ${isDragging 
          ? 'border-teal-400 bg-slate-800 scale-[1.02] shadow-[0_0_30px_rgba(45,212,191,0.2)]' 
          : 'border-slate-700 bg-slate-800/80 hover:bg-slate-800 hover:border-indigo-500/60 hover:shadow-[0_20px_40px_-10px_rgba(0,0,0,0.5)] hover:-translate-y-2'}
        ${hasFile ? 'border-teal-500/50 bg-slate-800' : ''}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => fileInputRef.current?.click()}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileSelect} 
        className="hidden" 
        accept={type === 'image' ? "image/*" : "audio/*"}
      />

      {hasFile && onRemove && (
        <button
          onClick={(e) => {
            e.stopPropagation();
            onRemove();
          }}
          className="absolute top-4 right-4 p-2 bg-slate-700/80 hover:bg-red-500/20 text-slate-400 hover:text-red-400 rounded-full transition-all duration-200 z-10 backdrop-blur-sm hover:scale-110 active:scale-95"
          title="Remove file"
        >
          <X size={18} />
        </button>
      )}

      <div className="flex flex-col items-center text-center space-y-4">
        {hasFile ? (
           <div className="text-teal-400 bg-teal-400/10 p-5 rounded-full mb-2 shadow-[0_0_20px_rgba(45,212,191,0.3)] animate-in zoom-in duration-300">
            <CheckCircle size={36} />
          </div>
        ) : (
          <div className={`p-5 rounded-full transition-all duration-500 
            ${type === 'image' 
              ? 'bg-indigo-500/10 text-indigo-400 group-hover:bg-indigo-500/20 group-hover:scale-110 group-hover:shadow-[0_0_20px_rgba(99,102,241,0.3)]' 
              : 'bg-teal-500/10 text-teal-400 group-hover:bg-teal-500/20 group-hover:scale-110 group-hover:shadow-[0_0_20px_rgba(45,212,191,0.3)]'}`}>
             {type === 'image' ? <FileImage size={36} /> : <FileAudio size={36} />}
          </div>
        )}

        <div>
          <h3 className="text-lg font-bold text-slate-100 max-w-[200px] truncate mx-auto tracking-wide">
            {hasFile ? currentFile.name : label}
          </h3>
          <p className="text-slate-400 text-sm mt-1 font-medium tracking-wide">
            {hasFile ? 'Click to replace' : subLabel}
          </p>
        </div>
      </div>
    </div>
  );
};

