import React, { useState, useMemo } from 'react';
import { GenericItem, BusinessRule } from '../types';
import { ShoppingCart, Check, Trash2, Plus, Minus, Truck, Tag, ArrowLeft, Layers, FileText, CreditCard } from 'lucide-react';

interface GeneratedFormProps {
  extractedItems: GenericItem[];
  rule: BusinessRule | null;
  onReset: () => void;
}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ extractedItems, rule, onReset }) => {
  const [cart, setCart] = useState<Record<string, number>>({});
  const [orderPlaced, setOrderPlaced] = useState(false);

  const updateQuantity = (itemId: string, delta: number) => {
    setCart(prev => {
      const current = prev[itemId] || 0;
      const next = Math.max(0, current + delta);
      const newCart = { ...prev, [itemId]: next };
      if (next === 0) delete newCart[itemId];
      return newCart;
    });
  };

  const cartTotal = useMemo(() => {
    return Object.entries(cart).reduce((total, [id, qty]) => {
      const item = extractedItems.find(i => i.id === id);
      return total + (item ? item.value * qty : 0);
    }, 0);
  }, [cart, extractedItems]);

  const deliveryFee = 15.00; // Generic processing fee

  // Apply Rule Logic
  let discount = 0;
  let finalFee = deliveryFee;
  let ruleApplied = false;

  if (rule) {
    if (rule.type === 'threshold_free_delivery' && cartTotal >= rule.threshold) {
      finalFee = 0;
      ruleApplied = true;
    } else if (rule.type === 'threshold_discount' && cartTotal >= rule.threshold) {
      discount = cartTotal * (rule.benefitValue / 100);
      ruleApplied = true;
    }
  }

  const finalTotal = cartTotal + finalFee - discount;

  const categories = useMemo(() => {
    const cats: Record<string, GenericItem[]> = {};
    extractedItems.forEach(item => {
      const c = item.category || 'General';
      if (!cats[c]) cats[c] = [];
      cats[c].push(item);
    });
    return cats;
  }, [extractedItems]);

  if (orderPlaced) {
    return (
      <div className="flex items-center justify-center h-full min-h-[500px]">
        <div className="max-w-md w-full bg-slate-800 rounded-2xl shadow-2xl p-10 text-center animate-in fade-in zoom-in duration-500 border border-slate-700 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-teal-400 to-indigo-500"></div>
