          </p>
          <button 
            onClick={() => { setOrderPlaced(false); setCart({}); }}
            className="w-full py-4 bg-slate-700 text-white rounded-xl font-semibold hover:bg-slate-600 transition-colors mb-4"
          >
            Start New Workflow
          </button>
          <button 
            onClick={onReset}
            className="text-indigo-400 hover:text-indigo-300 text-sm font-medium transition-colors"
          >
            Back to Architect
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] animate-in fade-in duration-700">
        {/* Header Bar for Live App */}
        <div className="flex items-center justify-between mb-6 px-1">
             <button onClick={onReset} className="group flex items-center space-x-2 text-slate-400 hover:text-white transition-colors">
                <div className="p-2 rounded-full bg-slate-800 group-hover:bg-slate-700 transition-colors">
                  <ArrowLeft size={18} />
                </div>
                <span className="font-medium">Exit App Preview</span>
             </button>
             <div className="flex items-center space-x-2 px-4 py-1.5 bg-teal-500/10 text-teal-400 text-xs font-mono font-bold rounded-full border border-teal-500/20 shadow-[0_0_15px_rgba(45,212,191,0.1)]">
                <span className="w-2 h-2 rounded-full bg-teal-400 animate-pulse"></span>
                <span>LIVE SYSTEM ACTIVE</span>
             </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 flex-1 overflow-hidden">
        {/* Menu Column */}
        <div className="lg:col-span-2 space-y-6 overflow-y-auto pr-2 pb-20 custom-scrollbar">
            <div className="bg-gradient-to-br from-indigo-900 to-slate-900 rounded-2xl shadow-lg border border-indigo-500/20 p-8 flex justify-between items-end relative overflow-hidden">
               <div className="absolute top-0 right-0 p-32 bg-indigo-500/10 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none"></div>
               <div className="relative z-10">
                  <h1 className="text-3xl font-bold text-white mb-2 tracking-tight">Generated Business App</h1>
                  <p className="text-indigo-200 text-sm font-medium">Digital Workflow & Procurement System</p>
               </div>
               {rule && rule.type === 'threshold_free_delivery' && (
                  <div className="hidden sm:flex items-center space-x-2 bg-teal-500/10 text-teal-300 px-4 py-2 rounded-lg text-sm font-bold border border-teal-500/20 shadow-lg backdrop-blur-sm z-10">
                    <Truck size={18} />
                    <span>Fees Waived @ {rule.threshold}</span>
                  </div>
               )}
            </div>

            {Object.keys(categories).length === 0 ? (
            <div className="bg-slate-800 rounded-2xl p-12 text-center text-slate-500 border border-dashed border-slate-700">
                <Layers size={48} className="mx-auto mb-4 opacity-30" />
                <p>No actionable items found in the document.</p>
            </div>
            ) : (
            Object.entries(categories).map(([category, items]) => (
                <div key={category} className="bg-slate-800 rounded-2xl shadow-xl border border-slate-700/50 overflow-hidden">
                <div className="bg-slate-900/80 px-6 py-4 border-b border-slate-700 flex items-center space-x-2">
