                </div>
                <div className="divide-y divide-slate-700/50">
                    {items.map(item => (
                    <div key={item.id} className="p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center hover:bg-slate-700/30 transition-colors group">
                        <div className="flex-1 pr-4 mb-4 sm:mb-0">
                          <h4 className="font-semibold text-slate-100 text-lg group-hover:text-indigo-300 transition-colors">{item.name}</h4>
                          {item.description && <p className="text-slate-400 text-sm mt-1">{item.description}</p>}
                          <div className="flex items-center mt-2">
                             <span className="text-slate-500 text-xs font-mono mr-2">UNIT VAL:</span>
                             <p className="text-teal-400 font-mono font-medium">{item.value.toFixed(2)}</p>
                          </div>
                        </div>
                        <div className="flex items-center space-x-3 bg-slate-900/50 p-1.5 rounded-xl border border-slate-700/50">
                        {cart[item.id] ? (
                            <>
                            <button 
                                onClick={() => updateQuantity(item.id, -1)}
                                className="w-8 h-8 rounded-lg bg-slate-800 flex items-center justify-center text-slate-400 hover:bg-red-500/20 hover:text-red-400 transition-colors"
                            >
                                <Minus size={16} />
                            </button>
                            <span className="w-8 text-center font-bold text-white font-mono">{cart[item.id]}</span>
                            <button 
                                onClick={() => updateQuantity(item.id, 1)}
                                className="w-8 h-8 rounded-lg bg-indigo-600 text-white flex items-center justify-center hover:bg-indigo-500 transition-colors shadow-lg shadow-indigo-500/20"
                            >
                                <Plus size={16} />
                            </button>
                            </>
                        ) : (
                            <button 
                            onClick={() => updateQuantity(item.id, 1)}
                            className="px-5 py-2 bg-slate-800 border border-slate-600 rounded-lg text-slate-300 text-sm font-bold hover:border-indigo-500 hover:text-white hover:bg-slate-700 transition-all active:scale-95"
