                    </div>
                    <p className="font-medium">No items selected</p>
                    <p className="text-sm mt-1 opacity-60">Add items from the list to proceed</p>
                </div>
                ) : (
                <div className="space-y-4">
                    {Object.entries(cart).map(([id, qty]) => {
                    const item = extractedItems.find(i => i.id === id);
                    if (!item) return null;
                    return (
                        <div key={id} className="flex justify-between items-start text-sm group">
                        <div className="flex-1 pr-2">
                            <span className="font-medium text-slate-200 block">{item.name}</span>
                            <div className="text-slate-500 text-xs mt-0.5">Unit: {item.value.toFixed(2)} x {qty}</div>
                        </div>
                        <div className="flex items-center space-x-3">
                            <span className="font-mono font-medium text-white">{ (item.value * qty).toFixed(2) }</span>
                            <button onClick={() => updateQuantity(id, -qty)} className="text-slate-600 hover:text-red-400 transition-colors opacity-0 group-hover:opacity-100">
                            <Trash2 size={14} />
                            </button>
                        </div>
                        </div>
                    );
                    })}
                </div>
                )}
            </div>

            <div className="bg-slate-900/80 p-6 border-t border-slate-700 backdrop-blur-sm">
                {/* Dynamic Rule Display */}
                {rule && (
                <div className={`mb-5 p-4 rounded-xl border flex items-start space-x-3 text-xs transition-all duration-500
                    ${ruleApplied 
                        ? 'bg-teal-500/10 border-teal-500/30 text-teal-300 shadow-[0_0_20px_rgba(45,212,191,0.1)]' 
                        : 'bg-indigo-500/10 border-indigo-500/30 text-indigo-300'}
                `}>
                    <div className={`mt-0.5 p-1.5 rounded-full ${ruleApplied ? 'bg-teal-500/20' : 'bg-indigo-500/20'}`}>
                    {rule.type === 'threshold_free_delivery' ? <Truck size={14} /> : <Tag size={14} />}
