                    <div className="flex-1">
                    <span className="font-bold block mb-1 text-white uppercase tracking-wider text-[10px]">
                        {rule.type === 'threshold_free_delivery' ? 'Fee Waiver Active' : 'Discount Active'}
                    </span>
                    <div className="italic mb-2 opacity-70 border-l-2 border-current pl-2">"{rule.originalText}"</div>
                    {!ruleApplied && (
                        <div className="font-medium mt-1 bg-slate-900/50 p-2 rounded flex items-center justify-between">
                          <span>Progress:</span>
                          <span>Add <span className="font-bold text-white font-mono">${(rule.threshold - cartTotal).toFixed(2)}</span></span>
                        </div>
                    )}
                    {ruleApplied && (
                        <div className="font-bold flex items-center mt-1 text-white bg-teal-500/20 p-2 rounded">
                        <Check size={14} className="mr-2" /> Conditions Met
                        </div>
                    )}
                    </div>
                </div>
                )}

                <div className="space-y-3 text-sm mb-6">
                <div className="flex justify-between text-slate-400">
                    <span>Subtotal</span>
                    <span className="font-mono">${cartTotal.toFixed(2)}</span>
                </div>
                <div className="flex justify-between text-slate-400">
                    <span>Processing/Fees</span>
                    <span className={`font-mono ${finalFee === 0 ? 'text-teal-400 font-bold' : ''}`}>
                    {finalFee === 0 ? 'WAIVED' : `${deliveryFee.toFixed(2)}`}
                    </span>
                </div>
                {discount > 0 && (
                    <div className="flex justify-between text-teal-400 font-medium">
                    <span>Discount applied</span>
                    <span className="font-mono">-{discount.toFixed(2)}</span>
                </div>
                )}
                <div className="flex justify-between text-xl font-bold text-white pt-4 border-t border-slate-700 mt-2">
                    <span>Total</span>
                    <span className="font-mono text-indigo-300">${finalTotal.toFixed(2)}</span>
                </div>
                </div>

                <button 
                disabled={Object.keys(cart).length === 0}
                onClick={() => setOrderPlaced(true)}
                className="w-full py-4 bg-gradient-to-r from-indigo-600 to-violet-600 text-white rounded-xl font-bold hover:from-indigo-500 hover:to-violet-500 disabled:opacity-50 disabled:grayscale transition-all shadow-lg hover:shadow-indigo-500/25 active:scale-95 flex items-center justify-center space-x-2"
                >
                  <span>Submit Request</span>
                  <ArrowRight size={18} />
                </button>
            </div>
            </div>
        </div>
        </div>
    </div>
  );
};

