              <Zap className="text-white h-6 w-6 fill-current" />
            </div>
            <div>
                <h1 className="text-xl font-bold text-white tracking-tight group-hover:text-indigo-300 transition-colors">BizFlow Architect</h1>
                <p className="text-[10px] text-slate-400 font-mono tracking-widest uppercase">Gemini 3 Pro Engine</p>
            </div>
          </div>

          {/* Stepper */}
          <div className="hidden md:flex items-center space-x-2">
             {['input', 'review', 'app'].map((s, idx) => {
                const isActive = state.step === s;
                const isCompleted = (state.step === 'review' && idx === 0) || (state.step === 'app' && idx < 2);

                return (
                    <div key={s} className="flex items-center">
