import { GoogleGenAI, Type } from "@google/genai";
import { GenericItem, BusinessRule, DocumentContext } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type
        }
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const extractDataFromImages = async (imageParts: Array<{ inlineData: { data: string; mimeType: string } }>): Promise<{ items: GenericItem[], context: DocumentContext }> => {
  const modelId = "gemini-2.5-flash";

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        ...imageParts,
        {
          text: `You are an expert AI Architect. Your job is to analyze a document image and "Architect" a digital app for it.

          1. CLASSIFY: Determine the type of document (e.g., Invoice, Medical Intake, School Report, Inventory List).
          2. ADAPT: Create a professional title for an app that would manage this data. Determine the primary action a user would take (e.g., "Pay", "Submit", "Restock").
          3. EXTRACT: Pull all list-based data (line items, questions, products) into a structured list.
             - 'value': Extract the primary number (price, quantity, score, time). If none, default to 1.
             - 'name': The main label for the row.
             - 'category': Grouping inference.
          `
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          context: {
            type: Type.OBJECT,
            properties: {
              detectedType: { type: Type.STRING },
              appTitle: { type: Type.STRING },
              actionButtonLabel: { type: Type.STRING },
              summaryLabel: { type: Type.STRING, description: "Label for the total value, e.g., 'Total Cost', 'Total Items'" }
            },
            required: ["detectedType", "appTitle", "actionButtonLabel", "summaryLabel"]
          },
          items: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                name: { type: Type.STRING },
                value: { type: Type.NUMBER },
                category: { type: Type.STRING },
                description: { type: Type.STRING },
              },
              required: ["id", "name", "value", "category"]
            }
          }
        },
        required: ["context", "items"]
      }
    }
  });

  if (response.text) {
    try {
      return JSON.parse(response.text) as { items: GenericItem[], context: DocumentContext };
    } catch (e) {
      console.error("Failed to parse extracted data", e);
      return { items: [], context: { detectedType: "Unknown", appTitle: "Data Viewer", actionButtonLabel: "Submit", summaryLabel: "Total" } };
    }
  }
  return { items: [], context: { detectedType: "Unknown", appTitle: "Data Viewer", actionButtonLabel: "Submit", summaryLabel: "Total" } };
};

const RULE_PROMPT = `Analyze the input business rule.
Extract the threshold logic.
If the rule implies a discount/deduction, use 'threshold_discount'.
If the rule implies an action/flag/alert/waiver, use 'threshold_action'.
Capture the action name if applicable (e.g., "Free Shipping", "Manager Review").`;

const RULE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    type: { type: Type.STRING, enum: ["threshold_action", "threshold_discount"] },
    threshold: { type: Type.NUMBER },
    benefitValue: { type: Type.NUMBER },
    actionName: { type: Type.STRING },
    originalText: { type: Type.STRING }
  },
  required: ["type", "threshold", "benefitValue", "originalText"]
};

export const extractRuleFromAudio = async (base64Audio: string, mimeType: string): Promise<BusinessRule> => {
  const modelId = "gemini-2.5-flash";
  const response = await ai.models.generateContent({
    model: modelId,
    contents: { parts: [{ inlineData: { data: base64Audio, mimeType: mimeType } }, { text: RULE_PROMPT }] },
    config: { responseMimeType: "application/json", responseSchema: RULE_SCHEMA }
  });
  if (response.text) try { return JSON.parse(response.text); } catch (e) {}
  return getDefaultRule();
};

export const extractRuleFromText = async (textRule: string): Promise<BusinessRule> => {
  const modelId = "gemini-2.5-flash";
  const response = await ai.models.generateContent({
    model: modelId,
    contents: { parts: [{ text: `Rule: "${textRule}"\n\n${RULE_PROMPT}` }] },
    config: { responseMimeType: "application/json", responseSchema: RULE_SCHEMA }
  });
  if (response.text) try { return JSON.parse(response.text); } catch (e) {}
  return getDefaultRule();
};

function getDefaultRule(): BusinessRule {
  return { type: 'threshold_action', threshold: 1000000, benefitValue: 0, originalText: "No specific rule detected." };
}

import React, { useRef, useState } from 'react';
import { FileAudio, FileImage, CheckCircle, X, UploadCloud } from 'lucide-react';
import { FileType } from '../types';

interface FileUploadProps {
  type: FileType;
  onUpload: (file: File) => void;
  label: string;
  subLabel: string;
  currentFile?: File | null;
  onRemove?: () => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ type, onUpload, label, subLabel, currentFile, onRemove }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const processFile = (file: File) => {
    if (!file) return;
    if (type === 'image' && !file.type.startsWith('image/')) return alert('Image files only.');
    if (type === 'audio' && !file.type.startsWith('audio/')) return alert('Audio files only.');
    onUpload(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files[0]) processFile(e.dataTransfer.files[0]);
  };

  const hasFile = !!currentFile;

  return (
    <div 
      className={`relative floating-card p-10 cursor-pointer border-2 transition-all duration-300
        ${isDragging 
          ? 'border-indigo-500 bg-indigo-50/50' 
          : 'border-transparent hover:border-indigo-100'}
        ${hasFile ? 'border-green-100 bg-green-50/30' : ''}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => fileInputRef.current?.click()}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} 
        className="hidden" 
        accept={type === 'image' ? "image/*" : "audio/*"}
      />

      {hasFile && onRemove && (
        <button
          onClick={(e) => { e.stopPropagation(); onRemove(); }}
          className="absolute top-4 right-4 p-2 bg-slate-100 hover:bg-red-50 text-slate-400 hover:text-red-500 rounded-full transition-colors z-10"
        >
          <X size={18} />
        </button>
      )}

      <div className="flex flex-col items-center text-center space-y-4">
        {hasFile ? (
           <div className="text-emerald-500 bg-emerald-100 p-5 rounded-full mb-2 animate-in zoom-in duration-300">
            <CheckCircle size={32} />
          </div>
        ) : (
          <div className={`p-5 rounded-full transition-all duration-500 
            ${type === 'image' 
              ? 'bg-blue-50 text-blue-600 group-hover:scale-110' 
              : 'bg-purple-50 text-purple-600 group-hover:scale-110'}`}>
             {type === 'image' ? <UploadCloud size={32} /> : <FileAudio size={32} />}
          </div>
        )}

        <div>
          <h3 className="text-xl font-bold text-slate-800 tracking-tight">
            {hasFile ? currentFile.name : label}
          </h3>
          <p className="text-slate-500 text-sm mt-2 font-medium">
            {hasFile ? 'Click to replace' : subLabel}
          </p>
        </div>
      </div>
    </div>
  );
};

export default FileUpload;

