}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ items, context, rule, onReset }) => {
  const [selectedItems, setSelectedItems] = useState<Record<string, number>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);

  const updateQuantity = (itemId: string, delta: number) => {
    setSelectedItems(prev => {
      const current = prev[itemId] || 0;
      const next = Math.max(0, current + delta);
      const newCart = { ...prev, [itemId]: next };
      if (next === 0) delete newCart[itemId];
      return newCart;
    });
  };

  const totalValue = useMemo(() => {
    return Object.entries(selectedItems).reduce((total, [id, qty]) => {
      const item = items.find(i => i.id === id);
      return total + (item ? item.value * qty : 0);
    }, 0);
  }, [selectedItems, items]);

  // Apply Logic
  let finalValue = totalValue;
  let ruleTriggered = false;
  let ruleMessage = "";

  if (rule) {
    if (totalValue >= rule.threshold) {
        ruleTriggered = true;
        if (rule.type === 'threshold_discount') {
            const discount = totalValue * (rule.benefitValue / 100);
            finalValue = totalValue - discount;
            ruleMessage = `Discount Applied: -${discount.toFixed(2)}`;
        } else {
            ruleMessage = rule.actionName || "Condition Met";
        }
    } else {
        ruleMessage = `Reach ${rule.threshold} to trigger ${rule.actionName || 'benefit'}`;
    }
  }

  const groupedItems = useMemo(() => {
    const cats: Record<string, GenericItem[]> = {};
    items.forEach(item => {
      const c = item.category || 'General';
      if (!cats[c]) cats[c] = [];
      cats[c].push(item);
    });
    return cats;
  }, [items]);

  if (isSubmitted) {
    return (
      <div className="flex items-center justify-center h-full min-h-[500px]">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-2xl p-10 text-center animate-in fade-in zoom-in duration-500 border border-slate-100">
          <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6">
            <Check size={48} />
          </div>
          <h2 className="text-3xl font-bold text-slate-900 mb-3">Success</h2>
          <p className="text-slate-500 mb-10 leading-relaxed">
            The {context?.appTitle || "Process"} has been completed. Records have been updated in the database.
          </p>
          <button onClick={() => { setIsSubmitted(false); setSelectedItems({}); }} className="w-full py-4 bg-slate-100 text-slate-700 rounded-xl font-bold hover:bg-slate-200 transition-colors mb-4">
            Process Another
          </button>
          <button onClick={onReset} className="text-indigo-600 hover:underline text-sm font-medium">
            Return to Architect
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] animate-in fade-in duration-700">
        <div className="flex items-center justify-between mb-6 px-1">
             <button onClick={onReset} className="flex items-center space-x-2 text-slate-500 hover:text-slate-900 transition-colors bg-white px-4 py-2 rounded-full shadow-sm border border-slate-200">
                <ArrowLeft size={16} />
                <span className="font-medium text-sm">Back to Editor</span>
             </button>
             <div className="flex items-center space-x-2 px-4 py-1.5 bg-green-100 text-green-700 text-xs font-bold rounded-full border border-green-200">
                <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                <span>LIVE PREVIEW</span>
             </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 flex-1 overflow-hidden">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6 overflow-y-auto pr-2 pb-20 custom-scrollbar">
            <div className="bg-white rounded-2xl shadow-xl border border-slate-100 p-8 flex justify-between items-end relative overflow-hidden">
               <div className="absolute top-0 right-0 p-32 bg-indigo-50 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none opacity-50"></div>
               <div className="relative z-10">
                  <div className="text-xs font-bold text-indigo-600 uppercase tracking-widest mb-1">{context?.detectedType}</div>
                  <h1 className="text-3xl font-extrabold text-slate-900 mb-2">{context?.appTitle}</h1>
                  <p className="text-slate-500 text-sm font-medium">Digital Workflow System v1.0</p>
               </div>
            </div>

            {Object.entries(groupedItems).map(([category, catItems]) => (
                <div key={category} className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="bg-slate-50 px-6 py-4 border-b border-slate-200">
                    <h3 className="font-bold text-slate-700 uppercase tracking-wider text-xs">{category}</h3>
                </div>
                <div className="divide-y divide-slate-100">
                    {catItems.map(item => (
                    <div key={item.id} className="p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center hover:bg-slate-50 transition-colors">
                        <div className="flex-1 pr-4 mb-4 sm:mb-0">
                          <h4 className="font-bold text-slate-800 text-lg">{item.name}</h4>
                          {item.description && <p className="text-slate-400 text-sm mt-1">{item.description}</p>}
                          <div className="inline-flex items-center mt-2 bg-slate-100 px-2 py-1 rounded text-xs font-mono text-slate-600">
                             {item.value}
                          </div>
                        </div>
                        <div className="flex items-center space-x-3">
                        {selectedItems[item.id] ? (
                            <div className="flex items-center bg-slate-100 rounded-lg p-1">
                                <button onClick={() => updateQuantity(item.id, -1)} className="p-1 hover:bg-white rounded shadow-sm transition-all"><Minus size={16} /></button>
                                <span className="w-8 text-center font-bold text-slate-800">{selectedItems[item.id]}</span>
                                <button onClick={() => updateQuantity(item.id, 1)} className="p-1 bg-white rounded shadow-sm text-indigo-600"><Plus size={16} /></button>
                            </div>
                        ) : (
                            <button 
                            onClick={() => updateQuantity(item.id, 1)}
                            className="px-5 py-2 bg-white border border-slate-200 rounded-lg text-slate-600 text-sm font-bold hover:border-indigo-500 hover:text-indigo-600 transition-all shadow-sm"
                            >
                            Select
                            </button>
                        )}
                        </div>
                    </div>
                    ))}
                </div>
                </div>
            ))}
        </div>

        {/* Sidebar / Action Panel */}
        <div className="lg:col-span-1">
            <div className="bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden flex flex-col h-[calc(100vh-180px)] sticky top-0">
            <div className="p-6 border-b border-slate-100 bg-slate-50/50">
                <h3 className="font-bold text-slate-800 text-lg">Action Summary</h3>
            </div>

            <div className="p-6 flex-1 overflow-y-auto custom-scrollbar">
                {Object.keys(selectedItems).length === 0 ? (
                <div className="text-center py-12">
                    <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-400">
                        <Layers size={32} />
                    </div>
                    <p className="font-medium text-slate-600">No items selected</p>
                </div>
                ) : (
                <div className="space-y-4">
                    {Object.entries(selectedItems).map(([id, qty]) => {
                    const item = items.find(i => i.id === id);
                    if (!item) return null;
                    return (
                        <div key={id} className="flex justify-between items-start text-sm">
                        <div className="flex-1 pr-2">
                            <span className="font-medium text-slate-800 block">{item.name}</span>
                        </div>
                        <div className="flex items-center space-x-3">
                            <span className="font-mono text-slate-600">{ (item.value * qty).toFixed(1) }</span>
                            <button onClick={() => updateQuantity(id, -qty)} className="text-slate-300 hover:text-red-500 transition-colors">
                            <Trash2 size={14} />
                            </button>
                        </div>
                        </div>
                    );
                    })}
                </div>
                )}
            </div>

            <div className="bg-slate-50 p-6 border-t border-slate-200">
                {/* Dynamic Rule Feedback */}
                {rule && (
                <div className={`mb-5 p-4 rounded-xl border flex items-start space-x-3 text-sm transition-all
                    ${ruleTriggered 
                        ? 'bg-indigo-50 border-indigo-200 text-indigo-700' 
                        : 'bg-white border-slate-200 text-slate-500'}
                `}>
                    <div className={`mt-0.5`}>
                       {ruleTriggered ? <ShieldCheck size={18} /> : <AlertCircle size={18} />}
                    </div>
                    <div className="flex-1">
                        <div className="font-bold">{ruleTriggered ? "Rule Active" : "Conditional Logic"}</div>
                        <div className="text-xs opacity-80 mt-1">{ruleMessage}</div>
                    </div>
                </div>
                )}

                <div className="space-y-3 text-sm mb-6">
                <div className="flex justify-between text-slate-500">
                    <span>{context?.summaryLabel || 'Total'}</span>
                    <span className="font-mono font-medium">{totalValue.toFixed(2)}</span>
                </div>

                <div className="flex justify-between text-xl font-extrabold text-slate-900 pt-4 border-t border-slate-200 mt-2">
                    <span>Final</span>
                    <span>{finalValue.toFixed(2)}</span>
                </div>
                </div>

                <button 
                disabled={Object.keys(selectedItems).length === 0}
                onClick={() => setIsSubmitted(true)}
                className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg hover:shadow-xl transform hover:-translate-y-0.5 flex items-center justify-center space-x-2"
                >
                  <span>{context?.actionButtonLabel || "Process"}</span>
                  <ArrowRight size={18} />
                </button>
            </div>
            </div>
        </div>
        </div>
    </div>
  );
};

export default GeneratedForm;

