                              label="Upload Document"
                              subLabel="Invoice, Contract, Inventory (JPG/PNG)"
                              onUpload={handleImageUpload}
                              currentFile={state.uploadedImages[0]}
                              onRemove={handleRemoveImage}
                          />
                        </div>
                        <button 
                           onClick={() => setIsScanning(true)}
                           className="w-full py-3 bg-slate-800 hover:bg-slate-700 border border-slate-700 text-slate-300 rounded-xl font-semibold transition-all flex items-center justify-center gap-2"
                        >
                           <ScanLine size={18} />
                           Scan Document (Simulated)
                        </button>
                      </div>
                    )}
                </div>

                <div className="space-y-4">
                     <h2 className="text-lg font-bold text-slate-300 flex items-center gap-3 px-2">
                        <span className="bg-fuchsia-500/20 text-fuchsia-400 w-7 h-7 flex items-center justify-center rounded-lg text-xs border border-fuchsia-500/30">2</span>
                        Business Logic (Optional)
                    </h2>
                    <div className="glass-card rounded-2xl p-1 overflow-hidden h-[320px] flex flex-col hover:border-fuchsia-500/30 transition-colors duration-300">
                        <div className="flex-1 p-6 space-y-4 bg-slate-900/30 rounded-xl flex flex-col">
                             {/* Text Input area always visible if no audio, or vice versa logic */}
                             {!state.uploadedAudio && (
                                <textarea
                                    value={state.manualRuleText}
                                    onChange={(e) => setState(prev => ({ ...prev, manualRuleText: e.target.value }))}
                                    placeholder="Describe a workflow rule... (e.g. 'If total exceeds $5,000, flag for VP approval')"
                                    className="w-full flex-1 bg-slate-950/50 border border-slate-700/50 rounded-xl p-4 text-slate-200 focus:ring-2 focus:ring-violet-500/50 focus:border-violet-500 outline-none resize-none placeholder-slate-600 text-sm transition-all"
                                />
                             )}

                             {state.manualRuleText.length === 0 && (
                                <div className="border-t border-slate-800/50 pt-4 mt-auto">
                                     <FileUpload 
                                        type="audio"
                                        label="Or Record Voice Instruction"
                                        subLabel="MP3/WAV Audio"
                                        onUpload={handleAudioUpload}
                                        currentFile={state.uploadedAudio}
                                        onRemove={handleRemoveAudio}
                                    />
                                </div>
                             )}
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex justify-center pb-12">
                <button
                    onClick={handleAnalyze}
                    disabled={state.uploadedImages.length === 0}
                    className="group relative inline-flex items-center justify-center px-12 py-6 font-bold text-white transition-all duration-300 bg-gradient-to-r from-violet-600 to-indigo-600 rounded-2xl hover:from-violet-500 hover:to-indigo-500 disabled:opacity-50 disabled:grayscale shadow-[0_0_40px_rgba(124,58,237,0.3)] hover:shadow-[0_0_60px_rgba(124,58,237,0.5)] transform hover:-translate-y-1 active:scale-95 text-lg"
                >
                    <span className="mr-3">Initiate Synthesis</span>
                    <Wand2 size={24} className="group-hover:rotate-12 transition-transform" />
                </button>
            </div>
          </div>
        )}

        {/* STEP 2: REVIEW */}
        {state.step === 'review' && (
             <AnalysisReview 
                extractedItems={state.extractedItems}
                context={state.documentContext}
                rule={state.rule}
                onBack={() => setState(prev => ({ ...prev, step: 'input' }))}
                onConfirm={() => setState(prev => ({ ...prev, step: 'app' }))}
             />
        )}

        {/* STEP 3: APP */}
        {state.step === 'app' && (
             <GeneratedForm 
               items={state.extractedItems} 
               context={state.documentContext}
               rule={state.rule} 
               onReset={handleReset}
             />
        )}

      </main>

      <Footer />
    </div>
  );
};

