      const response = await fetch(scanUrl);
      const blob = await response.blob();
      const file = new File([blob], "scanned_document.jpg", { type: blob.type });
      handleImageUpload(file);
      setIsScanning(false);
      setScanUrl('');
    } catch (err) {
      console.error(err);
