interface CameraScannerProps {
  onCapture: (file: File) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);

  useEffect(() => {
    let activeStream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        setError(null);
        activeStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' } 
        });
        setStream(activeStream);

        if (videoRef.current) {
          videoRef.current.srcObject = activeStream;
        }
      } catch (err) {
        console.error("Camera access error:", err);
        setError("Could not access camera. Please check permissions.");
      }
    };

    startCamera();

    return () => {
      if (activeStream) {
        activeStream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const handleCapture = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        canvas.toBlob((blob) => {
          if (blob) {
            const file = new File([blob], "camera_capture.jpg", { type: 'image/jpeg' });
            onCapture(file);
            onClose(); // Clean close
          }
        }, 'image/jpeg', 0.9);
      }
    }
  };

  return (
    <div className="relative glass-card rounded-2xl p-0 border border-violet-500/50 shadow-[0_0_30px_rgba(124,58,237,0.1)] animate-in zoom-in duration-300 h-[320px] flex flex-col overflow-hidden bg-black">
      {/* Live Camera View */}
      {error ? (
          <div className="flex flex-col items-center justify-center h-full p-8 text-center bg-slate-900">
              <div className="p-4 bg-red-500/10 rounded-full text-red-400 mb-4"><Camera size={32} /></div>
              <p className="text-red-300 font-medium mb-4 text-sm">{error}</p>
              <button onClick={onClose} className="flex items-center space-x-2 text-white bg-slate-800 px-4 py-2 rounded-lg hover:bg-slate-700 text-sm">
                  <X size={16} /> <span>Close</span>
              </button>
          </div>
      ) : (
          <>
            <video 
                ref={videoRef} 
                autoPlay 
                playsInline 
                muted
                className="absolute inset-0 w-full h-full object-cover"
            />

            {/* Scanning Laser Animation (Overlay) */}
            <div className="absolute top-0 left-0 w-full h-1 bg-emerald-400 shadow-[0_0_20px_rgba(52,211,153,0.8)] z-20 animate-[scan_2s_ease-in-out_infinite]"></div>

            {/* Controls Overlay */}
            <div className="absolute inset-0 z-30 flex flex-col justify-between p-4 pointer-events-none">
                <div className="flex justify-between items-center pointer-events-auto">
                    <div className="bg-black/60 px-3 py-1 rounded-full text-xs font-bold text-emerald-400 border border-emerald-500/30 flex items-center gap-2 backdrop-blur-md">
                        <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                        LIVE FEED
                    </div>
                    <button onClick={onClose} className="p-2 bg-black/60 text-white rounded-full hover:bg-red-500/80 transition-colors backdrop-blur-md">
                        <X size={20} />
                    </button>
                </div>

                <div className="flex justify-center pb-4 pointer-events-auto">
                    <button 
                        onClick={handleCapture}
                        className="w-16 h-16 rounded-full border-4 border-white/80 bg-white/20 hover:bg-white/40 backdrop-blur-md transition-all active:scale-95 flex items-center justify-center group shadow-2xl"
                        title="Take Photo"
                    >
                        <div className="w-12 h-12 bg-white rounded-full group-hover:scale-90 transition-transform"></div>
                    </button>
                </div>
            </div>
          </>
      )}
    </div>
  );
};


