const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [state, setState] = useState<AppState>({
    uploadedImages: [],
    uploadedAudio: null,
    manualRuleText: '',
    extractedItems: [],
    documentContext: null,
    rule: null,
    step: 'input',
    isLoading: false,
    loadingMessage: ''
  });

  const [isScanning, setIsScanning] = useState(false);

  const handleImageUpload = (file: File) => {
    setState(prev => ({ ...prev, uploadedImages: [file] }));
  };

  const handleAudioUpload = (file: File) => {
    setState(prev => ({ ...prev, uploadedAudio: file, manualRuleText: '' })); 
  };

  const handleRemoveImage = () => {
    setState(prev => ({ ...prev, uploadedImages: [] }));
  };

  const handleRemoveAudio = () => {
    setState(prev => ({ ...prev, uploadedAudio: null }));
  };

  const handleAnalyze = async () => {
    if (state.uploadedImages.length === 0) {
      alert("Please upload a business document first.");
      return;
    }

    setState(prev => ({ ...prev, isLoading: true, loadingMessage: 'VibeShift Engine Architecting Solution...' }));

    try {
      const imageParts = await Promise.all(state.uploadedImages.map(fileToGenerativePart));

      let rule: BusinessRule | null = null;
      if (state.uploadedAudio) {
        const audioPart = await fileToGenerativePart(state.uploadedAudio);
        rule = await extractRuleFromAudio(audioPart.inlineData.data, audioPart.inlineData.mimeType);
      } else if (state.manualRuleText.trim().length > 0) {
        rule = await extractRuleFromText(state.manualRuleText);
      }

      // Extract Data AND Context
      const { items, context } = await extractDataFromImages(imageParts);

      setState(prev => ({
        ...prev,
        extractedItems: items,
        documentContext: context,
        rule: rule,
        step: 'review',
        isLoading: false
      }));

    } catch (e) {
      console.error(e);
      setState(prev => ({ ...prev, isLoading: false }));
      alert("Analysis failed. Please check your inputs.");
    }
  };

  const handleReset = () => {
    setState({
      uploadedImages: [],
      uploadedAudio: null,
      manualRuleText: '',
      extractedItems: [],
      documentContext: null,
      rule: null,
      step: 'input',
      isLoading: false,
      loadingMessage: ''
    });
  };

  if (!isAuthenticated) {
    return <AuthLogin onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="min-h-screen flex flex-col font-sans text-slate-100 bg-[#020617] selection:bg-violet-500/30 selection:text-violet-200 overflow-x-hidden">

      {/* Background Grid & Effects */}
      <div className="fixed inset-0 z-0 pointer-events-none">
          <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
          <div className="absolute inset-0 bg-[linear-gradient(to_right,#1e293b_1px,transparent_1px),linear-gradient(to_bottom,#1e293b_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_0%,#000_70%,transparent_100%)] opacity-20"></div>
      </div>

      {/* Navbar */}
      <header className="bg-[#020617]/80 backdrop-blur-xl sticky top-0 z-50 border-b border-white/5">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between relative z-10">
          <a 
            href={LINKEDIN_URL} 
            target="_blank" 
            rel="noopener noreferrer"
            className="flex items-center space-x-3 cursor-pointer group"
          >
            <div className="p-2 bg-gradient-to-br from-violet-600 to-indigo-600 rounded-xl shadow-[0_0_20px_rgba(139,92,246,0.3)] group-hover:scale-105 transition-all duration-300">
              <Command className="text-white" size={24} />
            </div>
            <span className="text-2xl font-bold tracking-tight text-white group-hover:text-violet-400 transition-colors">VibeShift</span>
          </a>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center space-x-8">
            <a href={LINKEDIN_URL} target="_blank" className="text-sm font-medium text-slate-400 hover:text-white transition-colors">Features</a>
            <a href={LINKEDIN_URL} target="_blank" className="text-sm font-medium text-slate-400 hover:text-white transition-colors">Enterprise</a>
            <a href={LINKEDIN_URL} target="_blank" className="text-sm font-medium text-slate-400 hover:text-white transition-colors">Pricing</a>
            <a href={LINKEDIN_URL} target="_blank" className="text-sm font-medium text-slate-400 hover:text-white transition-colors">Docs</a>

            <div className="h-6 w-px bg-slate-800"></div>

            <div className="flex items-center space-x-1 bg-slate-900/50 p-1 rounded-full border border-slate-800">
             {['input', 'review', 'app'].map((s, idx) => {
                const isActive = state.step === s;
                const isCompleted = (state.step === 'review' && idx === 0) || (state.step === 'app' && idx < 2);

                return (
                    <div key={s} className="flex items-center">
                        <div className={`
                            flex items-center space-x-2 px-4 py-1.5 rounded-full transition-all duration-500
                            ${isActive ? 'bg-slate-800 text-white shadow-lg border border-slate-700' : 
                              isCompleted ? 'text-emerald-500' : 'text-slate-500 hover:text-slate-300'}
                        `}>
                            <div className={`text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full 
                              ${isActive ? 'bg-violet-600 shadow-[0_0_10px_rgba(124,58,237,0.5)]' : 
                                isCompleted ? 'bg-emerald-500/20' : 'bg-slate-800'}`}>
                                {isCompleted ? <Zap size={10} /> : idx + 1}
                            </div>
                            <span className="capitalize font-medium text-sm tracking-wide hidden lg:inline">
                                {s === 'input' ? 'Ingest' : s === 'review' ? 'Analyze' : 'Deploy'}
                            </span>
                        </div>
                    </div>
                );
             })}
            </div>
          </nav>
        </div>
      </header>

      <main className="flex-1 w-full max-w-7xl mx-auto px-6 py-12 relative z-10">

        {/* Ambient background glows */}
        <div className="absolute top-0 left-0 w-full h-[500px] bg-violet-600/5 rounded-full blur-[120px] pointer-events-none -translate-y-1/2"></div>

        {/* Loading Overlay */}
        {state.isLoading && (
          <div className="fixed inset-0 bg-[#020617]/90 backdrop-blur-lg z-[60] flex flex-col items-center justify-center animate-in fade-in duration-500">
             <div className="relative mb-10 p-10">
                 <div className="absolute inset-0 border-t-2 border-violet-500 rounded-full animate-spin blur-[2px]"></div>
                 <div className="w-24 h-24 border-t-2 border-indigo-500 rounded-full animate-spin"></div>
                 <div className="absolute inset-0 flex items-center justify-center">
                   <Sparkles className="text-white animate-pulse" size={36} />
                 </div>
              </div>
              <h3 className="text-4xl font-bold text-white mb-3 tracking-tight">Processing Data</h3>
              <p className="text-violet-400 font-mono animate-pulse">{state.loadingMessage}</p>
          </div>
        )}

        {/* STEP 1: INPUT */}
        {state.step === 'input' && (
          <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-700 pt-10">
             <div className="text-center mb-20 relative">
              <div className="inline-flex items-center space-x-2 px-4 py-1.5 rounded-full bg-indigo-500/10 border border-indigo-500/20 text-indigo-300 text-xs font-bold mb-8 tracking-widest uppercase shadow-[0_0_20px_rgba(99,102,241,0.1)]">
                 <Zap size={12} className="text-yellow-400 fill-yellow-400" /> 
                 <span>VibeShift AI Engine 3.0</span>
              </div>
              <h1 className="text-6xl md:text-8xl font-extrabold text-white mb-8 tracking-tight leading-none">
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-slate-200 to-slate-500">Transform</span> <br/>
                <span className="gradient-text drop-shadow-[0_0_30px_rgba(124,58,237,0.3)]">Chaos to Code.</span>
              </h1>
              <p className="text-xl text-slate-400 max-w-2xl mx-auto leading-relaxed">
                Upload any business document. Our adaptive AI interprets the context, extracts the data, and builds a production-ready application instantly.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-16">
                <div className="space-y-4">
                    <h2 className="text-lg font-bold text-slate-300 flex items-center gap-3 px-2">
                        <span className="bg-violet-500/20 text-violet-400 w-7 h-7 flex items-center justify-center rounded-lg text-xs border border-violet-500/30">1</span>
                        Source Material
                    </h2>

                    {isScanning ? (
                      <CameraScanner 
                         onCapture={handleImageUpload} 
                         onClose={() => setIsScanning(false)} 
                      />
                    ) : (
                      <div className="h-[320px] flex flex-col gap-4">
                        <div className="flex-1">
                          <FileUpload 
                              type="image"
                              label="Upload Document"
                              subLabel="Invoice, Contract, Inventory (JPG/PNG)"
                              onUpload={handleImageUpload}
                              currentFile={state.uploadedImages[0]}
                              onRemove={handleRemoveImage}
                          />
                        </div>
                        <button 
                           onClick={() => setIsScanning(true)}
                           className="w-full py-3 bg-slate-800 hover:bg-slate-700 border border-slate-700 text-slate-300 rounded-xl font-semibold transition-all flex items-center justify-center gap-2"
                        >
                           <Camera size={18} />
                           Scan Document (Camera)
                        </button>
                      </div>
                    )}
                </div>

                <div className="space-y-4">
                     <h2 className="text-lg font-bold text-slate-300 flex items-center gap-3 px-2">
                        <span className="bg-fuchsia-500/20 text-fuchsia-400 w-7 h-7 flex items-center justify-center rounded-lg text-xs border border-fuchsia-500/30">2</span>
                        Business Logic (Optional)
                    </h2>
                    <div className="glass-card rounded-2xl p-1 overflow-hidden h-[320px] flex flex-col hover:border-fuchsia-500/30 transition-colors duration-300">
                        <div className="flex-1 p-6 space-y-4 bg-slate-900/30 rounded-xl flex flex-col">
                             {/* Text Input area always visible if no audio, or vice versa logic */}
                             {!state.uploadedAudio && (
                                <textarea
                                    value={state.manualRuleText}
                                    onChange={(e) => setState(prev => ({ ...prev, manualRuleText: e.target.value }))}
                                    placeholder="Describe a workflow rule... (e.g. 'If total exceeds $5,000, flag for VP approval')"
                                    className="w-full flex-1 bg-slate-950/50 border border-slate-700/50 rounded-xl p-4 text-slate-200 focus:ring-2 focus:ring-violet-500/50 focus:border-violet-500 outline-none resize-none placeholder-slate-600 text-sm transition-all"
                                />
                             )}

                             {state.manualRuleText.length === 0 && (
                                <div className="border-t border-slate-800/50 pt-4 mt-auto">
                                     <FileUpload 
                                        type="audio"
                                        label="Or Record Voice Instruction"
                                        subLabel="MP3/WAV Audio"
                                        onUpload={handleAudioUpload}
                                        currentFile={state.uploadedAudio}
                                        onRemove={handleRemoveAudio}
                                    />
                                </div>
                             )}
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex justify-center pb-12">
                <button
                    onClick={handleAnalyze}
                    disabled={state.uploadedImages.length === 0}
                    className="group relative inline-flex items-center justify-center px-12 py-6 font-bold text-white transition-all duration-300 bg-gradient-to-r from-violet-600 to-indigo-600 rounded-2xl hover:from-violet-500 hover:to-indigo-500 disabled:opacity-50 disabled:grayscale shadow-[0_0_40px_rgba(124,58,237,0.3)] hover:shadow-[0_0_60px_rgba(124,58,237,0.5)] transform hover:-translate-y-1 active:scale-95 text-lg"
                >
                    <span className="mr-3">Initiate Synthesis</span>
                    <Wand2 size={24} className="group-hover:rotate-12 transition-transform" />
                </button>
            </div>
          </div>
        )}

        {/* STEP 2: REVIEW */}
        {state.step === 'review' && (
             <AnalysisReview 
                extractedItems={state.extractedItems}
                context={state.documentContext}
                rule={state.rule}
                onBack={() => setState(prev => ({ ...prev, step: 'input' }))}
                onConfirm={() => setState(prev => ({ ...prev, step: 'app' }))}
             />
        )}

        {/* STEP 3: APP */}
        {state.step === 'app' && (
             <GeneratedForm 
               items={state.extractedItems} 
               context={state.documentContext}
               rule={state.rule} 
               onReset={handleReset}
             />
        )}

      </main>

      <Footer />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { GenericItem, BusinessRule, DocumentContext } from '../types';
import { Check, Trash2, Plus, Minus, AlertCircle, ArrowLeft, ArrowRight, Layers, ShieldCheck, QrCode, Smartphone, FileCheck, Circle, CheckCircle2 } from 'lucide-react';

interface GeneratedFormProps {
  items: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  onReset: () => void;
}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ items, context, rule, onReset }) => {
  const [selectedItems, setSelectedItems] = useState<Record<string, boolean>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);

  const toggleSelection = (itemId: string) => {
    setSelectedItems(prev => ({
      ...prev,
      [itemId]: !prev[itemId]
    }));
  };

  const totalValue = useMemo(() => {
    return Object.entries(selectedItems).reduce((total, [id, isSelected]) => {
      if (!isSelected) return total;
      const item = items.find(i => i.id === id);
      return total + (item ? item.value : 0);
    }, 0);
  }, [selectedItems, items]);

  // Apply Logic
  let ruleTriggered = false;
  let ruleMessage = "";

  if (rule) {
    if (totalValue >= rule.threshold) {
        ruleTriggered = true;
        if (rule.type === 'threshold_discount') {
            // Adapted for generic context - just show the benefit
             ruleMessage = `Optimized: ${rule.benefitValue}% benefit applied`;
        } else {
            ruleMessage = rule.actionName || "Condition Met";
        }
    } else {
        ruleMessage = `Threshold: ${rule.threshold} needed for ${rule.actionName || 'action'}`;
    }
  }

  const groupedItems = useMemo(() => {
    const cats: Record<string, GenericItem[]> = {};
    items.forEach(item => {
      const c = item.category || 'General';
      if (!cats[c]) cats[c] = [];
      cats[c].push(item);
    });
    return cats;
  }, [items]);

  const selectedCount = Object.values(selectedItems).filter(Boolean).length;

  if (isSubmitted) {
    return (
      <div className="flex items-center justify-center h-full min-h-[500px]">
        <div className="max-w-md w-full glass-card rounded-2xl shadow-2xl p-10 text-center animate-in fade-in zoom-in duration-500 border border-slate-700">
          <div className="w-24 h-24 bg-emerald-500/10 text-emerald-400 rounded-full flex items-center justify-center mx-auto mb-6 shadow-[0_0_30px_rgba(16,185,129,0.3)]">
            <Check size={48} />
          </div>
          <h2 className="text-3xl font-bold text-white mb-3">Workflow Finalized</h2>
          <p className="text-slate-400 mb-10 leading-relaxed">
            The <span className="text-emerald-400 font-semibold">{context?.appTitle}</span> data has been successfully processed and archived.
          </p>
          <button onClick={() => { setIsSubmitted(false); setSelectedItems({}); }} className="w-full py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold transition-colors mb-4 border border-slate-700">
            Process Another Document
          </button>
          <button onClick={onReset} className="text-violet-400 hover:text-violet-300 text-sm font-medium hover:underline transition-colors">
            Return to VibeShift Architect
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] animate-in fade-in duration-700">
        <div className="flex items-center justify-between mb-6 px-1">
             <button onClick={onReset} className="flex items-center space-x-2 text-slate-400 hover:text-white transition-colors bg-slate-900/50 px-4 py-2 rounded-full border border-slate-800 hover:border-slate-600">
                <ArrowLeft size={16} />
                <span className="font-medium text-sm">Back to Architect</span>
             </button>
             <div className="flex items-center space-x-2 px-4 py-1.5 bg-emerald-500/10 text-emerald-400 text-xs font-bold rounded-full border border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.2)]">
                <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                <span>VIBESHIFT LIVE</span>
             </div>
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-4 gap-8 flex-1 overflow-hidden">
        {/* Main Content */}
        <div className="xl:col-span-3 space-y-6 overflow-y-auto pr-2 pb-20 custom-scrollbar">
            <div className="glass-card rounded-2xl p-8 flex justify-between items-end relative overflow-hidden group">
               {/* Ambient Glow */}
               <div className="absolute top-0 right-0 p-40 bg-gradient-to-br from-violet-600 to-indigo-600 rounded-full blur-[100px] -mr-20 -mt-20 opacity-20 pointer-events-none"></div>

               <div className="relative z-10 w-full">
                  <div className="flex justify-between items-start">
                      <div>
                        <div className="text-xs font-bold text-violet-400 uppercase tracking-widest mb-1 flex items-center gap-2">
                             <Layers size={14} /> {context?.detectedType}
                        </div>
                        <h1 className="text-3xl md:text-4xl font-extrabold text-white mb-2">{context?.appTitle}</h1>
                        <p className="text-slate-400 text-sm font-medium">Auto-Generated Interface v1.0</p>
                      </div>

                      {/* QR Code Feature */}
                      <div className="hidden md:flex bg-white p-3 rounded-xl shadow-lg transform rotate-2 hover:rotate-0 transition-transform duration-300">
                           <div className="text-center">
                                <img src={`https://api.qrserver.com/v1/create-qr-code/?size=100x100&data=VibeShiftDemo`} alt="QR Code" className="w-20 h-20 mb-2" />
                                <div className="text-[10px] font-bold text-slate-900 uppercase tracking-wider flex items-center justify-center gap-1">
                                    <Smartphone size={10} /> Mobile
                                </div>
                           </div>
                      </div>
                  </div>
               </div>
            </div>

            {(Object.entries(groupedItems) as [string, GenericItem[]][]).map(([category, catItems]) => (
                <div key={category} className="glass-card rounded-2xl overflow-hidden border border-slate-800">
                <div className="bg-slate-900/60 px-6 py-4 border-b border-slate-700/50 backdrop-blur-sm">
                    <h3 className="font-bold text-slate-300 uppercase tracking-wider text-xs flex items-center gap-2">
                        <span className="w-1.5 h-1.5 rounded-full bg-indigo-500"></span>
                        {category}
                    </h3>
                </div>
                <div className="divide-y divide-slate-800">
                    {catItems.map(item => {
                        const isSelected = !!selectedItems[item.id];
                        return (
                            <div 
                                key={item.id} 
                                onClick={() => toggleSelection(item.id)}
                                className={`p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center transition-colors group cursor-pointer
                                    ${isSelected ? 'bg-violet-900/20' : 'hover:bg-slate-800/40'}
                                `}
                            >
                                <div className="flex-1 pr-4 mb-4 sm:mb-0">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-1.5 rounded-full border transition-all duration-300 ${isSelected ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-slate-600 text-transparent'}`}>
                                            <Check size={14} />
                                        </div>
                                        <h4 className={`font-bold text-lg transition-colors ${isSelected ? 'text-white' : 'text-slate-300 group-hover:text-indigo-300'}`}>
                                            {item.name}
                                        </h4>
                                    </div>
                                    {item.description && <p className="text-slate-500 text-sm mt-1 ml-9">{item.description}</p>}
                                    {/* Only show value if it's meaningful (not just default 1) */}
                                    {item.value !== 1 && (
                                        <div className="inline-flex items-center mt-2 ml-9 bg-slate-800 border border-slate-700 px-3 py-1 rounded-full text-xs font-mono text-sky-400">
                                            Metric: {item.value}
                                        </div>
                                    )}
                                </div>
                                <div className="flex items-center space-x-3 ml-9 sm:ml-0">
                                    <button 
                                        className={`px-6 py-2.5 rounded-xl text-sm font-bold transition-all shadow-sm border
                                            ${isSelected 
                                                ? 'bg-emerald-600 border-emerald-500 text-white shadow-[0_0_15px_rgba(16,185,129,0.3)]' 
                                                : 'bg-slate-900 border-slate-700 text-slate-300 hover:border-indigo-500 hover:text-white'}
                                        `}
                                    >
                                        {isSelected ? 'Selected' : 'Select'}
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                </div>
                </div>
            ))}
        </div>

        {/* Sidebar / Action Panel */}
        <div className="xl:col-span-1">
            <div className="glass-card rounded-2xl flex flex-col h-[calc(100vh-180px)] sticky top-0 border border-slate-800 overflow-hidden">
            <div className="p-6 border-b border-slate-800 bg-slate-900/50">
                <h3 className="font-bold text-white text-lg flex items-center gap-2">
                    <FileCheck size={18} className="text-indigo-500" />
                    Workflow Progress
                </h3>
            </div>

            <div className="p-6 flex-1 overflow-y-auto custom-scrollbar">
                {selectedCount === 0 ? (
                <div className="text-center py-12">
                    <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-600 border border-slate-800">
                        <Circle size={32} />
                    </div>
                    <p className="font-medium text-slate-500">Select items to begin...</p>
                </div>
                ) : (
                <div className="space-y-3">
                    <div className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Selected Actions</div>
                    {Object.entries(selectedItems).map(([id, isSelected]) => {
                        if (!isSelected) return null;
                        const item = items.find(i => i.id === id);
                        if (!item) return null;
                        return (
                            <div key={id} className="flex items-center justify-between text-sm group p-3 rounded-lg bg-slate-800/50 border border-slate-800 hover:border-violet-500/30 transition-colors">
                                <div className="flex items-center gap-3 overflow-hidden">
                                    <CheckCircle2 size={16} className="text-emerald-500 flex-shrink-0" />
                                    <span className="font-medium text-slate-300 truncate">{item.name}</span>
                                </div>
                                <button onClick={(e) => { e.stopPropagation(); toggleSelection(id); }} className="text-slate-600 hover:text-red-400 transition-colors">
                                    <Trash2 size={14} />
                                </button>
                            </div>
                        );
                    })}
                </div>
                )}
            </div>

            <div className="bg-slate-900/80 p-6 border-t border-slate-800 backdrop-blur-xl">
                {/* Dynamic Rule Feedback */}
                {rule && (
                <div className={`mb-5 p-4 rounded-xl border flex items-start space-x-3 text-sm transition-all
                    ${ruleTriggered 
                        ? 'bg-indigo-500/10 border-indigo-500/30 text-indigo-300 shadow-[0_0_15px_rgba(99,102,241,0.1)]' 
                        : 'bg-slate-800/50 border-slate-700 text-slate-500'}
                `}>
                    <div className={`mt-0.5`}>
                       {ruleTriggered ? <ShieldCheck size={18} /> : <AlertCircle size={18} />}
                    </div>
                    <div className="flex-1">
                        <div className="font-bold">{ruleTriggered ? "System Logic Active" : "Conditional Logic"}</div>
                        <div className="text-xs opacity-70 mt-1">{ruleMessage}</div>
                    </div>
                </div>
                )}

                <div className="space-y-3 text-sm mb-6">
                    <div className="flex justify-between text-slate-400">
                        <span>Items Processed</span>
                        <span className="font-mono font-medium text-white">{selectedCount}</span>
                    </div>
                     <div className="w-full bg-slate-800 rounded-full h-1.5 mt-2">
                        <div 
                            className="bg-emerald-500 h-1.5 rounded-full transition-all duration-500" 
                            style={{ width: `${Math.min(100, (selectedCount / Math.max(1, items.length)) * 100)}%` }}
                        ></div>
                    </div>
                </div>

                <button 
                disabled={selectedCount === 0}
                onClick={() => setIsSubmitted(true)}
                className="w-full py-4 bg-gradient-to-r from-violet-600 to-indigo-600 text-white rounded-xl font-bold hover:from-violet-500 hover:to-indigo-500 disabled:opacity-50 disabled:grayscale transition-all shadow-lg hover:shadow-[0_0_25px_rgba(124,58,237,0.4)] active:scale-95 flex items-center justify-center space-x-2"
                >
                  <span>{context?.actionButtonLabel && context.actionButtonLabel !== 'Process' ? context.actionButtonLabel : "Finalize Workflow"}</span>
                  <ArrowRight size={18} />
                </button>
            </div>
            </div>
        </div>
        </div>
    </div>
  );
};

export default GeneratedForm;

import React, { useEffect, useState } from 'react';
import { GenericItem, BusinessRule, DocumentContext } from '../types';
import { ArrowRight, Sparkles, FileText, Zap, BrainCircuit, ScanLine, Terminal, CheckCircle2, Search, Database, Fingerprint } from 'lucide-react';

interface AnalysisReviewProps {
  extractedItems: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  onConfirm: () => void;
  onBack: () => void;
}

const AnalysisReview: React.FC<AnalysisReviewProps> = ({ extractedItems, context, rule, onConfirm, onBack }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const [activeStage, setActiveStage] = useState(0);

  useEffect(() => {
    const logMessages = [
      `[INIT] VibeShift Neural Engine v3.5 initialized.`,
      `[INFO] Multimodal Fusion: Loading tensor contexts...`,
      `[CV] OpenCV Module: Perspective correction & noise reduction applied.`,
      `[SUCCESS] OCR: Text extracted with 99.8% confidence.`,
      `[SUCCESS] NLP: Classification identified as '${context?.detectedType}'.`,
      `[DATA] Extraction: ${extractedItems.length} entities mapped to schema.`,
      `[LOGIC] Business Rule: ${rule ? 'Conditional logic tokenized' : 'Standard aggregation applied'}.`,
      `[READY] System Checksum OK. Awaiting deployment.`
    ];

    // Use any[] to avoid TypeScript environment conflicts
    const timers: any[] = [];
    let delay = 0;

    setLogs([]);

    logMessages.forEach((msg, index) => {
      delay += 400; 
      const timer = setTimeout(() => {
        setLogs(prev => [...prev, msg]);
        if (index === 4) setActiveStage(1);
        if (index === 6) setActiveStage(2);
        if (index === 7) setActiveStage(3);
      }, delay);
      timers.push(timer);
    });

    return () => {
      timers.forEach(t => clearTimeout(t));
    };
  }, [context, extractedItems.length, rule]);

  return (
    <div className="max-w-7xl mx-auto animate-in fade-in slide-in-from-bottom-8 duration-700">

      {/* HEADER */}
      <div className="text-center mb-12">
        <div className="inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-violet-500/10 border border-violet-500/20 text-violet-300 text-xs font-medium mb-4 shadow-[0_0_15px_rgba(139,92,246,0.3)]">
