        {/* LEFT COLUMN: THE THINKING PROCESS */}
        <div className="lg:col-span-7 space-y-6">

            {/* REASONING 1: CLASSIFICATION */}
            <div className={`glass-card rounded-2xl p-6 border transition-all duration-500 ${activeStage >= 1 ? 'border-emerald-500/50 bg-emerald-900/10' : 'border-slate-800'}`}>
                <div className="flex items-start justify-between mb-4">
