                        <div>
                            <h3 className="text-sm font-bold text-slate-300 uppercase tracking-wider">Reasoning 01</h3>
                            <p className="text-xs text-slate-500">Document Intent Classification</p>
                        </div>
                    </div>
                    {activeStage >= 1 && <CheckCircle2 size={20} className="text-emerald-500" />}
                </div>
                <div className="pl-12">
                    <div className="text-2xl font-bold text-white mb-1">{context?.detectedType || "Analyzing..."}</div>
                    <div className="text-sm text-slate-400">Target App: <span className="text-emerald-400 font-medium">{context?.appTitle}</span></div>
                </div>
            </div>

            {/* REASONING 2: EXTRACTION */}
            <div className={`glass-card rounded-2xl p-6 border transition-all duration-500 ${activeStage >= 2 ? 'border-sky-500/50 bg-sky-900/10' : 'border-slate-800'}`}>
                 <div className="flex items-start justify-between mb-4">
                    <div className="flex items-center space-x-3">
                        <div className={`p-2 rounded-lg ${activeStage >= 2 ? 'bg-sky-500 text-white' : 'bg-slate-800 text-slate-500'}`}>
                            <Database size={20} />
                        </div>
                        <div>
                            <h3 className="text-sm font-bold text-slate-300 uppercase tracking-wider">Reasoning 02</h3>
                            <p className="text-xs text-slate-500">Structured Data Extraction</p>
