                        <div className="text-xl font-bold text-white">{context?.summaryLabel || "Total"}</div>
                    </div>
                </div>
            </div>

            {/* REASONING 3: LOGIC */}
            <div className={`glass-card rounded-2xl p-6 border transition-all duration-500 ${activeStage >= 3 ? 'border-fuchsia-500/50 bg-fuchsia-900/10' : 'border-slate-800'}`}>
                 <div className="flex items-start justify-between mb-4">
                    <div className="flex items-center space-x-3">
                        <div className={`p-2 rounded-lg ${activeStage >= 3 ? 'bg-fuchsia-500 text-white' : 'bg-slate-800 text-slate-500'}`}>
                            <BrainCircuit size={20} />
