        </div>

        {/* RIGHT COLUMN: TERMINAL & ACTIONS */}
        <div className="lg:col-span-5 flex flex-col space-y-6">

            {/* VIBESHIFT VERIFICATION LOG */}
            <div className="glass-card rounded-2xl border border-slate-800 bg-[#050505] overflow-hidden shadow-2xl relative flex-1 min-h-[300px]">
                <div className="bg-slate-900/80 px-4 py-2 border-b border-slate-800 flex items-center justify-between">
                    <div className="flex items-center space-x-2">
                        <Terminal size={14} className="text-emerald-500" />
