import { GoogleGenAI, Type } from "@google/genai";
import { GenericItem, BusinessRule, DocumentContext } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type
        }
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const extractDataFromImages = async (imageParts: Array<{ inlineData: { data: string; mimeType: string } }>): Promise<{ items: GenericItem[], context: DocumentContext }> => {
  const modelId = "gemini-2.5-flash";

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        ...imageParts,
        {
          text: `You are an expert AI Solutions Architect. Your job is to analyze a document image and "Architect" a digital data entry application for it.

          1. CLASSIFY: Determine the specific document type (e.g., "US Passport Application", "Vendor Invoice", "Patient Intake Form").
          2. ADAPT: Create a professional title for the app. Determine the primary action (e.g., "Process Application", "Approve Invoice").
          3. EXTRACT: detailed fields to build a DIGITAL FORM.
             - If it is a Form: Extract every field (Name, DOB, Passport #) as an item. Set 'value' to an empty string or the text found in the field.
             - If it is a List/Invoice: Extract line items. Set 'value' to the price/quantity.
             - 'name': The label of the field (e.g., "Full Name").
             - 'category': Group related fields (e.g., "Personal Details", "Shipping Info", "Line Items").
             - 'type': Infer if it should be 'text', 'number', 'date', or 'textarea'.
          `
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          context: {
            type: Type.OBJECT,
            properties: {
              detectedType: { type: Type.STRING },
              appTitle: { type: Type.STRING },
              actionButtonLabel: { type: Type.STRING },
              summaryLabel: { type: Type.STRING, description: "Label for the progress metric, e.g., 'Fields Filled', 'Total Cost'" }
            },
            required: ["detectedType", "appTitle", "actionButtonLabel", "summaryLabel"]
          },
          items: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                name: { type: Type.STRING },
                value: { type: Type.STRING }, // Changed to STRING to support text fields
                category: { type: Type.STRING },
                description: { type: Type.STRING },
                type: { type: Type.STRING, enum: ['text', 'number', 'date', 'textarea'] }
              },
              required: ["id", "name", "category"]
            }
          }
        },
        required: ["context", "items"]
      }
    }
  });

  if (response.text) {
    try {
      return JSON.parse(response.text) as { items: GenericItem[], context: DocumentContext };
    } catch (e) {
      console.error("Failed to parse extracted data", e);
      return { items: [], context: { detectedType: "Unknown", appTitle: "Data Entry Portal", actionButtonLabel: "Submit Data", summaryLabel: "Fields" } };
    }
  }
  return { items: [], context: { detectedType: "Unknown", appTitle: "Data Entry Portal", actionButtonLabel: "Submit Data", summaryLabel: "Fields" } };
};

const RULE_PROMPT = `Analyze the input business rule.
Extract the threshold logic.
If the rule implies a discount/deduction, use 'threshold_discount'.
If the rule implies an action/flag/alert/waiver, use 'threshold_action'.
Capture the action name if applicable (e.g., "Free Shipping", "Manager Review").`;

const RULE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    type: { type: Type.STRING, enum: ["threshold_action", "threshold_discount"] },
    threshold: { type: Type.NUMBER },
    benefitValue: { type: Type.NUMBER },
    actionName: { type: Type.STRING },
    originalText: { type: Type.STRING }
  },
  required: ["type", "threshold", "benefitValue", "originalText"]
};

export const extractRuleFromAudio = async (base64Audio: string, mimeType: string): Promise<BusinessRule> => {
  const modelId = "gemini-2.5-flash";
  const response = await ai.models.generateContent({
    model: modelId,
    contents: { parts: [{ inlineData: { data: base64Audio, mimeType: mimeType } }, { text: RULE_PROMPT }] },
    config: { responseMimeType: "application/json", responseSchema: RULE_SCHEMA }
  });
  if (response.text) try { return JSON.parse(response.text); } catch (e) {}
  return getDefaultRule();
};

export const extractRuleFromText = async (textRule: string): Promise<BusinessRule> => {
  const modelId = "gemini-2.5-flash";
  const response = await ai.models.generateContent({
    model: modelId,
    contents: { parts: [{ text: `Rule: "${textRule}"\n\n${RULE_PROMPT}` }] },
    config: { responseMimeType: "application/json", responseSchema: RULE_SCHEMA }
  });
  if (response.text) try { return JSON.parse(response.text); } catch (e) {}
  return getDefaultRule();
};

function getDefaultRule(): BusinessRule {
  return { type: 'threshold_action', threshold: 1000000, benefitValue: 0, originalText: "No specific rule detected." };
}

import React, { useState, useMemo } from 'react';
import { GenericItem, BusinessRule, DocumentContext } from '../types';
import { Check, ArrowLeft, ArrowRight, Layers, Smartphone, FileCheck, Circle, Save, CreditCard, Calendar, Type as TypeIcon, Hash, AlertTriangle, ShieldCheck } from 'lucide-react';

interface GeneratedFormProps {
  items: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  onReset: () => void;
}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ items, context, rule, onReset }) => {
  // State to hold form values. Key = item.id, Value = user input
  const [formValues, setFormValues] = useState<Record<string, string | number>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);

  // Initialize form values with defaults from extraction
  useMemo(() => {
    const initial: Record<string, string | number> = {};
    items.forEach(item => {
      initial[item.id] = item.value || "";
    });
    setFormValues(initial);
  }, [items]);

  const handleInputChange = (id: string, value: string | number) => {
    setFormValues(prev => ({
      ...prev,
      [id]: value
    }));
  };

  // Group items for layout
  const groupedItems = useMemo(() => {
    const cats: Record<string, GenericItem[]> = {};
    items.forEach(item => {
      const c = item.category || 'General Information';
      if (!cats[c]) cats[c] = [];
      cats[c].push(item);
    });
    return cats;
  }, [items]);

  // Calculate some metric for the rule engine (e.g., sum of numeric fields)
  // Or just use filled count
  const numericTotal = Object.entries(formValues).reduce((acc, [key, val]) => {
     const num = parseFloat(val as string);
     return !isNaN(num) ? acc + num : acc;
  }, 0);

  const filledCount = Object.values(formValues).filter(v => v !== "" && v !== 0).length;
  const progressPercent = Math.min(100, Math.round((filledCount / items.length) * 100));

  // Business Logic Evaluation
  let ruleTriggered = false;
  let ruleMessage = "";

  if (rule) {
     // If the rule seems to be about a 'total' amount (high threshold), use numeric total
     // If threshold is small (e.g. < 50), it might be about quantity of items or days
     if (numericTotal >= rule.threshold) {
         ruleTriggered = true;
         ruleMessage = rule.actionName || "Approval Required";
         if (rule.type === 'threshold_discount') {
             ruleMessage = `Discount Applied: ${rule.benefitValue}%`;
         }
     } else {
         ruleMessage = `Current Total: ${numericTotal} / Threshold: ${rule.threshold}`;
     }
  }

  if (isSubmitted) {
    return (
      <div className="flex items-center justify-center h-full min-h-[500px]">
        <div className="max-w-md w-full glass-card rounded-2xl shadow-2xl p-10 text-center animate-in fade-in zoom-in duration-500 border border-slate-700">
          <div className="w-24 h-24 bg-emerald-500/10 text-emerald-400 rounded-full flex items-center justify-center mx-auto mb-6 shadow-[0_0_30px_rgba(16,185,129,0.3)]">
            <Check size={48} />
          </div>
          <h2 className="text-3xl font-bold text-white mb-3">Submission Successful</h2>
          <p className="text-slate-400 mb-10 leading-relaxed">
            Data for <span className="text-emerald-400 font-semibold">{context?.appTitle}</span> has been processed, validated against business rules, and synced to the core database.
          </p>
          <div className="bg-slate-900/50 rounded-xl p-4 mb-6 border border-slate-800 text-left">
              <div className="text-xs text-slate-500 uppercase font-bold mb-2">Transaction Summary</div>
              <div className="flex justify-between text-sm mb-1">
                  <span className="text-slate-400">Fields Captured</span>
                  <span className="text-white font-mono">{filledCount} / {items.length}</span>
              </div>
              <div className="flex justify-between text-sm">
                  <span className="text-slate-400">Logic Check</span>
                  <span className="text-emerald-400 font-bold">Passed</span>
              </div>
          </div>
          <button onClick={() => { setIsSubmitted(false); onReset(); }} className="w-full py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold transition-colors border border-slate-700">
            Process Next Document
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] animate-in fade-in duration-700">
        {/* Navigation Bar */}
        <div className="flex items-center justify-between mb-6 px-1">
             <button onClick={onReset} className="flex items-center space-x-2 text-slate-400 hover:text-white transition-colors bg-slate-900/50 px-4 py-2 rounded-full border border-slate-800 hover:border-slate-600">
                <ArrowLeft size={16} />
                <span className="font-medium text-sm">Back to Architect</span>
             </button>
             <div className="flex items-center space-x-2 px-4 py-1.5 bg-emerald-500/10 text-emerald-400 text-xs font-bold rounded-full border border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.2)]">
                <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                <span>VIBESHIFT LIVE DEPLOYMENT</span>
             </div>
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-4 gap-8 flex-1 overflow-hidden">

        {/* Main Content: The Generated Form */}
        <div className="xl:col-span-3 space-y-6 overflow-y-auto pr-2 pb-20 custom-scrollbar">

            {/* Header Card with QR */}
            <div className="glass-card rounded-2xl p-8 flex justify-between items-center relative overflow-hidden group border border-slate-700">
               <div className="absolute top-0 right-0 p-40 bg-gradient-to-br from-violet-600 to-indigo-600 rounded-full blur-[100px] -mr-20 -mt-20 opacity-20 pointer-events-none"></div>
               <div className="relative z-10 w-full flex justify-between items-center">
                  <div>
                    <div className="text-xs font-bold text-violet-400 uppercase tracking-widest mb-2 flex items-center gap-2">
                            <Layers size={14} /> {context?.detectedType}
                    </div>
                    <h1 className="text-3xl md:text-4xl font-extrabold text-white mb-2">{context?.appTitle}</h1>
                    <p className="text-slate-400 text-sm font-medium">Auto-Generated Data Entry Interface • v1.0.4</p>
                  </div>

                  {/* QR Code */}
                  <div className="hidden md:flex flex-col items-center bg-white/5 backdrop-blur-md border border-white/10 p-3 rounded-xl hover:bg-white/10 transition-colors cursor-pointer group/qr">
                       <div className="bg-white p-2 rounded-lg mb-2">
                           <img src={`https://api.qrserver.com/v1/create-qr-code/?size=100x100&data=VibeShift_App_${context?.detectedType}`} alt="QR Code" className="w-16 h-16" />
                       </div>
                       <div className="text-[10px] font-bold text-slate-300 uppercase tracking-wider flex items-center gap-1 group-hover/qr:text-white transition-colors">
                            <Smartphone size={10} /> Scan to Mobile
                       </div>
                  </div>
               </div>
            </div>

            {/* Dynamic Form Sections */}
            {(Object.entries(groupedItems) as [string, GenericItem[]][]).map(([category, catItems]) => (
                <div key={category} className="glass-card rounded-2xl overflow-hidden border border-slate-800">
                    <div className="bg-slate-900/60 px-6 py-4 border-b border-slate-700/50 backdrop-blur-sm flex items-center space-x-2">
                        <div className="w-1.5 h-4 rounded-full bg-gradient-to-b from-violet-500 to-indigo-500"></div>
                        <h3 className="font-bold text-slate-200 uppercase tracking-wider text-xs">{category}</h3>
                    </div>
                    <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                        {catItems.map(item => {
                            const inputType = item.type || (typeof item.value === 'number' ? 'number' : 'text');

                            return (
                                <div key={item.id} className={`${inputType === 'textarea' ? 'md:col-span-2' : ''} space-y-2 group`}>
                                    <label className="text-xs font-bold text-slate-500 uppercase tracking-wider group-hover:text-violet-400 transition-colors flex items-center gap-2">
                                        {inputType === 'date' && <Calendar size={12} />}
                                        {inputType === 'number' && <Hash size={12} />}
                                        {inputType === 'text' && <TypeIcon size={12} />}
                                        {item.name}
                                    </label>

                                    {inputType === 'textarea' ? (
                                        <textarea
                                            value={formValues[item.id] || ''}
                                            onChange={(e) => handleInputChange(item.id, e.target.value)}
                                            className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 text-slate-100 placeholder-slate-600 focus:ring-2 focus:ring-violet-500/50 focus:border-violet-500 outline-none transition-all h-24 resize-none"
                                            placeholder={item.description || `Enter ${item.name}...`}
                                        />
                                    ) : (
                                        <input
                                            type={inputType === 'number' ? 'number' : 'text'}
                                            value={formValues[item.id] || ''}
                                            onChange={(e) => handleInputChange(item.id, e.target.value)}
                                            className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 text-slate-100 placeholder-slate-600 focus:ring-2 focus:ring-violet-500/50 focus:border-violet-500 outline-none transition-all"
                                            placeholder={item.description || `Enter ${item.name}...`}
                                        />
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>
            ))}
        </div>

        {/* Sidebar / Progress & Actions */}
        <div className="xl:col-span-1">
            <div className="glass-card rounded-2xl flex flex-col h-[calc(100vh-180px)] sticky top-0 border border-slate-800 overflow-hidden">
                <div className="p-6 border-b border-slate-800 bg-slate-900/50">
                    <h3 className="font-bold text-white text-lg flex items-center gap-2">
                        <FileCheck size={18} className="text-indigo-500" />
                        Submission Status
                    </h3>
                </div>

                <div className="p-6 flex-1 overflow-y-auto custom-scrollbar flex flex-col space-y-6">
                    {/* Completion Meter */}
                    <div className="space-y-2">
                        <div className="flex justify-between text-xs font-bold text-slate-400 uppercase tracking-wider">
                            <span>Form Completion</span>
                            <span>{progressPercent}%</span>
                        </div>
                        <div className="w-full bg-slate-800 rounded-full h-2 overflow-hidden">
                            <div 
                                className="bg-gradient-to-r from-violet-500 to-indigo-500 h-full rounded-full transition-all duration-500" 
                                style={{ width: `${progressPercent}%` }}
                            ></div>
                        </div>
                        <p className="text-xs text-slate-500 text-right">{filledCount} of {items.length} fields filled</p>
                    </div>

                    {/* Logic Feedback */}
                    <div className={`rounded-xl p-4 border transition-all duration-300 ${
                        ruleTriggered 
                        ? 'bg-amber-500/10 border-amber-500/30 text-amber-200' 
                        : 'bg-emerald-500/5 border-emerald-500/20 text-emerald-200'
                    }`}>
                        <div className="flex items-start gap-3">
                            {ruleTriggered ? <AlertTriangle size={18} className="text-amber-500 shrink-0" /> : <ShieldCheck size={18} className="text-emerald-500 shrink-0" />}
                            <div>
                                <h4 className="font-bold text-sm mb-1">{ruleTriggered ? "Logic Triggered" : "System Valid"}</h4>
                                <p className="text-xs opacity-80">{rule ? ruleMessage : "Standard processing rules active."}</p>
                            </div>
                        </div>
                    </div>

                    {/* Instructions */}
                    <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-800">
                        <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Instructions</h4>
                        <p className="text-sm text-slate-400 leading-relaxed">
                            Review extracted data carefully. Fields marked with smart inference have been pre-filled. Confirm accuracy before finalizing.
                        </p>
                    </div>

                </div>

                <div className="bg-slate-900/80 p-6 border-t border-slate-800 backdrop-blur-xl">
                    <button 
                        onClick={() => setIsSubmitted(true)}
                        className="w-full py-4 bg-gradient-to-r from-violet-600 to-indigo-600 text-white rounded-xl font-bold hover:from-violet-500 hover:to-indigo-500 transition-all shadow-lg hover:shadow-[0_0_25px_rgba(124,58,237,0.4)] active:scale-95 flex items-center justify-center space-x-2 group"
                    >
                        <span>{context?.actionButtonLabel || "Save & Finalize Data"}</span>
                        <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />
                    </button>
                </div>
            </div>
        </div>
        </div>
    </div>
  );
};

