interface AnalysisReviewProps {
  extractedItems: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  onConfirm: () => void;
  onBack: () => void;
}

const AnalysisReview: React.FC<AnalysisReviewProps> = ({ extractedItems, context, rule, onConfirm, onBack }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const [activeStage, setActiveStage] = useState(0);

  useEffect(() => {
    const logMessages = [
      `[INIT] VibeShift Neural Engine v3.5 initialized.`,
      `[INFO] Multimodal Fusion: Loading tensor contexts...`,
      `[CV] OpenCV Module: Perspective correction & noise reduction applied.`,
      `[SUCCESS] OCR: Text extracted with 99.8% confidence.`,
      `[SUCCESS] NLP: Classification identified as '${context?.detectedType}'.`,
      `[DATA] Extraction: ${extractedItems.length} input fields mapped to schema.`,
      `[LOGIC] Business Rule: ${rule ? 'Conditional logic tokenized' : 'Standard aggregation applied'}.`,
      `[READY] System Checksum OK. Awaiting deployment.`
    ];

    // Use any[] to avoid TypeScript environment conflicts
    const timers: any[] = [];
    let delay = 0;

    setLogs([]);

    logMessages.forEach((msg, index) => {
      delay += 400; 
      const timer = setTimeout(() => {
        setLogs(prev => [...prev, msg]);
        if (index === 4) setActiveStage(1);
        if (index === 6) setActiveStage(2);
        if (index === 7) setActiveStage(3);
      }, delay);
      timers.push(timer);
    });

    return () => {
      timers.forEach(t => clearTimeout(t));
    };
  }, [context, extractedItems.length, rule]);

  return (
