import React, { useState, useMemo } from 'react';
import { GenericItem, BusinessRule, DocumentContext } from '../types';
import { Check, ArrowLeft, ArrowRight, Layers, Smartphone, FileCheck, Circle, Save, CreditCard, Calendar, Type as TypeIcon, Hash, AlertTriangle, ShieldCheck } from 'lucide-react';

interface GeneratedFormProps {
  items: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  onReset: () => void;
}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ items, context, rule, onReset }) => {
  const [formValues, setFormValues] = useState<Record<string, string | number>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);

  useMemo(() => {
    const initial: Record<string, string | number> = {};
    items.forEach(item => {
      initial[item.id] = item.value || "";
    });
    setFormValues(initial);
  }, [items]);

  const handleInputChange = (id: string, value: string | number) => {
    setFormValues(prev => ({
      ...prev,
      [id]: value
    }));
  };

  const groupedItems = useMemo(() => {
    const cats: Record<string, GenericItem[]> = {};
    items.forEach(item => {
      const c = item.category || 'General Information';
      if (!cats[c]) cats[c] = [];
      cats[c].push(item);
    });
    return cats;
  }, [items]);

  const numericTotal = Object.entries(formValues).reduce((acc, [key, val]) => {
     const num = parseFloat(val as string);
     return !isNaN(num) ? acc + num : acc;
  }, 0);

  const filledCount = Object.values(formValues).filter(v => v !== "" && v !== 0).length;
  const progressPercent = Math.min(100, Math.round((filledCount / items.length) * 100));

  let ruleTriggered = false;
  let ruleMessage = "";

  if (rule) {
     if (numericTotal >= rule.threshold) {
         ruleTriggered = true;
         ruleMessage = rule.actionName || "Approval Required";
         if (rule.type === 'threshold_discount') {
             ruleMessage = `Discount Applied: ${rule.benefitValue}%`;
         }
     } else {
         ruleMessage = `Current Total: ${numericTotal} / Threshold: ${rule.threshold}`;
     }
  }

  if (isSubmitted) {
    return (
      <div className="flex items-center justify-center h-full min-h-[500px]">
        <div className="max-w-md w-full glass-card rounded-2xl shadow-2xl p-10 text-center animate-in fade-in zoom-in duration-500 border border-slate-700">
          <div className="w-24 h-24 bg-emerald-500/10 text-emerald-400 rounded-full flex items-center justify-center mx-auto mb-6 shadow-[0_0_30px_rgba(16,185,129,0.3)]">
            <Check size={48} />
          </div>
          <h2 className="text-3xl font-bold text-white mb-3">Submission Successful</h2>
          <p className="text-slate-400 mb-10 leading-relaxed">
            Data for <span className="text-emerald-400 font-semibold">{context?.appTitle}</span> has been processed, validated against business rules, and synced to the core database.
          </p>
          <div className="bg-slate-900/50 rounded-xl p-4 mb-6 border border-slate-800 text-left">
              <div className="text-xs text-slate-500 uppercase font-bold mb-2">Transaction Summary</div>
              <div className="flex justify-between text-sm mb-1">
                  <span className="text-slate-400">Fields Captured</span>
                  <span className="text-white font-mono">{filledCount} / {items.length}</span>
              </div>
              <div className="flex justify-between text-sm">
                  <span className="text-slate-400">Logic Check</span>
                  <span className="text-emerald-400 font-bold">Passed</span>
              </div>
          </div>
          <button onClick={() => { setIsSubmitted(false); onReset(); }} className="w-full py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold transition-colors border border-slate-700">
            Process Next Document
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] animate-in fade-in duration-700">
        <div className="flex items-center justify-between mb-6 px-1">
             <button onClick={onReset} className="flex items-center space-x-2 text-slate-400 hover:text-white transition-colors bg-slate-900/50 px-4 py-2 rounded-full border border-slate-800 hover:border-slate-600">
                <ArrowLeft size={16} />
                <span className="font-medium text-sm">Back to Architect</span>
             </button>
             <div className="flex items-center space-x-2 px-4 py-1.5 bg-emerald-500/10 text-emerald-400 text-xs font-bold rounded-full border border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.2)]">
                <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                <span>VIBESHIFT LIVE DEPLOYMENT</span>
             </div>
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-4 gap-8 flex-1 overflow-hidden">

        <div className="xl:col-span-3 space-y-6 overflow-y-auto pr-2 pb-20 custom-scrollbar">

            <div className="glass-card rounded-2xl p-8 flex justify-between items-center relative overflow-hidden group border border-slate-700">
               <div className="absolute top-0 right-0 p-40 bg-gradient-to-br from-violet-600 to-indigo-600 rounded-full blur-[100px] -mr-20 -mt-20 opacity-20 pointer-events-none"></div>
               <div className="relative z-10 w-full flex justify-between items-center">
                  <div>
                    <div className="text-xs font-bold text-violet-400 uppercase tracking-widest mb-2 flex items-center gap-2">
