const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type
        }
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const extractDataFromImages = async (imageParts: Array<{ inlineData: { data: string; mimeType: string } }>): Promise<{ items: GenericItem[], context: DocumentContext }> => {
  const modelId = "gemini-2.5-flash";

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        ...imageParts,
        {
          text: `You are the VibeShift Multi-LLM RAG Engine. Your role is to "Architect" a robust, industry-standard digital data entry application based on the input document.

          PHASE 1: RAG CLASSIFICATION & VALIDATION
          - Analyze the document visual structure.
          - Simulate a Retrieval-Augmented Generation (RAG) lookup against a database of standard forms (HR, Finance, Government, Legal).
          - Classify the document type accurately (e.g., "US Dept of State Passport Form DS-11", "Standard Vendor Invoice", "Employee Leave Request").
          - Define a professional App Title.

          PHASE 2: ADAPTIVE FORM SYNTHESIS (DATA ENTRY FOCUS)
          - You must generate a DATA ENTRY FORM, not a shopping list.
          - Extract every fillable field found in the document.
          - Cross-reference with standard schemas to infer the correct data type ('text', 'number', 'date', 'textarea').
          - If a field is handwritten or filled, extract that text as the 'value'. If empty, leave 'value' empty.

          OUTPUT SCHEMA:
          - 'items': Array of form fields.
             - 'name': Professional label (e.g., "Date of Birth").
             - 'value': The default value or extracted text.
             - 'category': logical grouping (e.g., "Applicant Details", "Financials").
             - 'type': UI component hint.
          - 'context': Metadata about the app.
             - 'actionButtonLabel': Strong action verb (e.g., "Submit Application", "Process Invoice").
             - 'summaryLabel': Progress metric (e.g., "Fields Validated").
          `
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          context: {
            type: Type.OBJECT,
            properties: {
              detectedType: { type: Type.STRING },
              appTitle: { type: Type.STRING },
              actionButtonLabel: { type: Type.STRING },
