interface GeneratedFormProps {
  items: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  onReset: () => void;
}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ items, context, rule, onReset }) => {
  const [formValues, setFormValues] = useState<Record<string, string | number>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);

  useMemo(() => {
    const initial: Record<string, string | number> = {};
    items.forEach(item => {
      initial[item.id] = item.value || "";
    });
    setFormValues(initial);
  }, [items]);

  const handleInputChange = (id: string, value: string | number) => {
    setFormValues(prev => ({
      ...prev,
      [id]: value
    }));
  };

  const groupedItems = useMemo(() => {
    const cats: Record<string, GenericItem[]> = {};
    items.forEach(item => {
      const c = item.category || 'General Information';
      if (!cats[c]) cats[c] = [];
      cats[c].push(item);
    });
    return cats;
  }, [items]);

  const numericTotal = Object.entries(formValues).reduce((acc, [key, val]) => {
     const num = parseFloat(val as string);
     return !isNaN(num) ? acc + num : acc;
  }, 0);

  const filledCount = Object.values(formValues).filter(v => v !== "" && v !== 0).length;
  const progressPercent = Math.min(100, Math.round((filledCount / items.length) * 100));

  let ruleTriggered = false;
  let ruleMessage = "";

  if (rule) {
     if (numericTotal >= rule.threshold) {
         ruleTriggered = true;
         ruleMessage = rule.actionName || "Approval Required";
         if (rule.type === 'threshold_discount') {
             ruleMessage = `Benefit Applied: ${rule.benefitValue}%`;
         }
     } else {
         ruleMessage = `Value: ${numericTotal} / Threshold: ${rule.threshold}`;
     }
  }

  if (isSubmitted) {
    return (
      <div className="flex items-center justify-center h-full min-h-[500px]">
        <div className="max-w-md w-full glass-card rounded-2xl shadow-2xl p-10 text-center animate-in fade-in zoom-in duration-500 border border-slate-700">
          <div className="w-24 h-24 bg-emerald-500/10 text-emerald-400 rounded-full flex items-center justify-center mx-auto mb-6 shadow-[0_0_30px_rgba(16,185,129,0.3)]">
