  const formTotal = Object.entries(formValues).reduce((acc, [key, val]) => {
     const num = parseFloat(val as string);
     return !isNaN(num) ? acc + num : acc;
  }, 0);

  // CART TOTAL
  const cartTotal = items.reduce((acc, item) => {
    const qty = cart[item.id] || 0;
