const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [state, setState] = useState<AppState>({
    uploadedImages: [],
    uploadedAudio: null,
    manualRuleText: '',
    extractedItems: [],
    documentContext: null,
    rule: null,
    step: 'input',
    isLoading: false,
    loadingMessage: ''
  });

  const [isScanning, setIsScanning] = useState(false);

  const handleImageUpload = (file: File) => {
    setState(prev => ({ ...prev, uploadedImages: [file] }));
  };

  const handleAudioUpload = (file: File) => {
    setState(prev => ({ ...prev, uploadedAudio: file, manualRuleText: '' })); 
  };

  const handleRemoveImage = () => {
    setState(prev => ({ ...prev, uploadedImages: [] }));
  };

  const handleRemoveAudio = () => {
    setState(prev => ({ ...prev, uploadedAudio: null }));
  };

  const handleAnalyze = async () => {
    if (state.uploadedImages.length === 0) {
      alert("Please upload a business document first.");
      return;
    }

    setState(prev => ({ ...prev, isLoading: true, loadingMessage: 'VibeShift Engine Architecting Solution...' }));

    try {
      const imageParts = await Promise.all(state.uploadedImages.map(fileToGenerativePart));

      let rule: BusinessRule | null = null;
      if (state.uploadedAudio) {
        const audioPart = await fileToGenerativePart(state.uploadedAudio);
        rule = await extractRuleFromAudio(audioPart.inlineData.data, audioPart.inlineData.mimeType);
      } else if (state.manualRuleText.trim().length > 0) {
        rule = await extractRuleFromText(state.manualRuleText);
      }

      // Extract Data AND Context
      const { items, context } = await extractDataFromImages(imageParts);

      setState(prev => ({
        ...prev,
        extractedItems: items,
        documentContext: context,
        rule: rule,
        step: 'review',
        isLoading: false
      }));

    } catch (e) {
      console.error(e);
      setState(prev => ({ ...prev, isLoading: false }));
      alert("Analysis failed. Please check your inputs.");
    }
  };

  const handleReset = () => {
    setState({
      uploadedImages: [],
      uploadedAudio: null,
      manualRuleText: '',
      extractedItems: [],
      documentContext: null,
      rule: null,
      step: 'input',
      isLoading: false,
      loadingMessage: ''
    });
  };

  if (!isAuthenticated) {
    return <AuthLogin onLogin={() => setIsAuthenticated(true)} />;
  }

  return (
    <div className="min-h-screen flex flex-col font-sans text-slate-100 bg-[#020617] selection:bg-violet-500/30 selection:text-violet-200 overflow-x-hidden">

      {/* Background Grid & Effects */}
      <div className="fixed inset-0 z-0 pointer-events-none">
          <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20"></div>
          <div className="absolute inset-0 bg-[linear-gradient(to_right,#1e293b_1px,transparent_1px),linear-gradient(to_bottom,#1e293b_1px,transparent_1px)] bg-[size:4rem_4rem] [mask-image:radial-gradient(ellipse_60%_50%_at_50%_0%,#000_70%,transparent_100%)] opacity-20"></div>
      </div>

      {/* Navbar */}
      <header className="bg-[#020617]/80 backdrop-blur-xl sticky top-0 z-50 border-b border-white/5">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between relative z-10">
          <a 
            href={LINKEDIN_URL} 
            target="_blank" 
            rel="noopener noreferrer"
            className="flex items-center space-x-3 cursor-pointer group"
          >
            <div className="p-2 bg-gradient-to-br from-violet-600 to-indigo-600 rounded-xl shadow-[0_0_20px_rgba(139,92,246,0.3)] group-hover:scale-105 transition-all duration-300">
              <Command className="text-white" size={24} />
            </div>
            <span className="text-2xl font-bold tracking-tight text-white group-hover:text-violet-400 transition-colors">VibeShift</span>
          </a>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center space-x-8">
            <a href={LINKEDIN_URL} target="_blank" className="text-sm font-medium text-slate-400 hover:text-white transition-colors flex items-center gap-1 group">
              Features <ChevronDown size={14} className="text-slate-600 group-hover:text-violet-400 transition-colors" />
            </a>
            <a href={LINKEDIN_URL} target="_blank" className="text-sm font-medium text-slate-400 hover:text-white transition-colors flex items-center gap-1 group">
              Enterprise <ChevronDown size={14} className="text-slate-600 group-hover:text-violet-400 transition-colors" />
            </a>
            <a href={LINKEDIN_URL} target="_blank" className="text-sm font-medium text-slate-400 hover:text-white transition-colors">Pricing</a>
            <a href={LINKEDIN_URL} target="_blank" className="text-sm font-medium text-slate-400 hover:text-white transition-colors">Docs</a>

            <div className="h-6 w-px bg-slate-800"></div>

            <div className="flex items-center space-x-1 bg-slate-900/50 p-1 rounded-full border border-slate-800">
             {['input', 'review', 'app'].map((s, idx) => {
                const isActive = state.step === s;
                const isCompleted = (state.step === 'review' && idx === 0) || (state.step === 'app' && idx < 2);

                return (
                    <div key={s} className="flex items-center">
                        <div className={`
                            flex items-center space-x-2 px-4 py-1.5 rounded-full transition-all duration-500
                            ${isActive ? 'bg-slate-800 text-white shadow-lg border border-slate-700' : 
                              isCompleted ? 'text-emerald-500' : 'text-slate-500 hover:text-slate-300'}
                        `}>
                            <div className={`text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full 
                              ${isActive ? 'bg-violet-600 shadow-[0_0_10px_rgba(124,58,237,0.5)]' : 
                                isCompleted ? 'bg-emerald-500/20' : 'bg-slate-800'}`}>
                                {isCompleted ? <Zap size={10} /> : idx + 1}
                            </div>
                            <span className="capitalize font-medium text-sm tracking-wide hidden lg:inline">
                                {s === 'input' ? 'Ingest' : s === 'review' ? 'Analyze' : 'Deploy'}
                            </span>
                        </div>
                    </div>
                );
             })}
            </div>
          </nav>
        </div>
      </header>

      <main className="flex-1 w-full max-w-7xl mx-auto px-6 py-12 relative z-10">

        {/* Ambient background glows */}
        <div className="absolute top-0 left-0 w-full h-[500px] bg-violet-600/5 rounded-full blur-[120px] pointer-events-none -translate-y-1/2"></div>

        {/* Loading Overlay */}
        {state.isLoading && (
          <div className="fixed inset-0 bg-[#020617]/90 backdrop-blur-lg z-[60] flex flex-col items-center justify-center animate-in fade-in duration-500">
             <div className="relative mb-10 p-10">
                 <div className="absolute inset-0 border-t-2 border-violet-500 rounded-full animate-spin blur-[2px]"></div>
                 <div className="w-24 h-24 border-t-2 border-indigo-500 rounded-full animate-spin"></div>
                 <div className="absolute inset-0 flex items-center justify-center">
                   <Sparkles className="text-white animate-pulse" size={36} />
                 </div>
              </div>
              <h3 className="text-4xl font-bold text-white mb-3 tracking-tight">Processing Data</h3>
              <p className="text-violet-400 font-mono animate-pulse">{state.loadingMessage}</p>
          </div>
        )}

        {/* STEP 1: INPUT */}
        {state.step === 'input' && (
          <div className="max-w-5xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-700 pt-10">
             <div className="text-center mb-20 relative">
              <div className="inline-flex items-center space-x-2 px-4 py-1.5 rounded-full bg-indigo-500/10 border border-indigo-500/20 text-indigo-300 text-xs font-bold mb-8 tracking-widest uppercase shadow-[0_0_20px_rgba(99,102,241,0.1)]">
                 <Zap size={12} className="text-yellow-400 fill-yellow-400" /> 
                 <span>VibeShift AI Engine 3.0</span>
              </div>
              <h1 className="text-6xl md:text-8xl font-extrabold text-white mb-8 tracking-tight leading-none">
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-slate-200 to-slate-500">Transform</span> <br/>
                <span className="gradient-text drop-shadow-[0_0_30px_rgba(124,58,237,0.3)]">Chaos to Code.</span>
              </h1>
              <p className="text-xl text-slate-400 max-w-2xl mx-auto leading-relaxed">
                 Instantly transform static documents into fully functional Web Apps. No coding required.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-16">
                <div className="space-y-4">
                    <h2 className="text-lg font-bold text-slate-300 flex items-center gap-3 px-2">
                        <span className="bg-violet-500/20 text-violet-400 w-7 h-7 flex items-center justify-center rounded-lg text-xs border border-violet-500/30">1</span>
                        Source Material
                    </h2>

                    {isScanning ? (
                      <CameraScanner 
                         onCapture={handleImageUpload} 
                         onClose={() => setIsScanning(false)} 
                      />
                    ) : (
                      <div className="h-[320px] flex flex-col gap-4">
                        <div className="flex-1">
                          <FileUpload 
                              type="image"
                              label="Upload Document"
                              subLabel="Invoice, Contract, Inventory (JPG/PNG)"
                              onUpload={handleImageUpload}
                              currentFile={state.uploadedImages[0]}
                              onRemove={handleRemoveImage}
                          />
                        </div>
                        <button 
                           onClick={() => setIsScanning(true)}
                           className="w-full py-3 bg-slate-800 hover:bg-slate-700 border border-slate-700 text-slate-300 rounded-xl font-semibold transition-all flex items-center justify-center gap-2"
                        >
                           <Camera size={18} />
                           Scan Document (Camera)
                        </button>
                      </div>
                    )}
                </div>

                <div className="space-y-4">
                     <h2 className="text-lg font-bold text-slate-300 flex items-center gap-3 px-2">
                        <span className="bg-fuchsia-500/20 text-fuchsia-400 w-7 h-7 flex items-center justify-center rounded-lg text-xs border border-fuchsia-500/30">2</span>
                        Business Logic (Optional)
                    </h2>
                    <div className="glass-card rounded-2xl p-1 overflow-hidden h-[320px] flex flex-col hover:border-fuchsia-500/30 transition-colors duration-300">
                        <div className="flex-1 p-6 space-y-4 bg-slate-900/30 rounded-xl flex flex-col">
                             {/* Text Input area always visible if no audio, or vice versa logic */}
                             {!state.uploadedAudio && (
                                <textarea
                                    value={state.manualRuleText}
                                    onChange={(e) => setState(prev => ({ ...prev, manualRuleText: e.target.value }))}
                                    placeholder="Describe a workflow rule... (e.g. 'If total exceeds $5,000, flag for VP approval')"
                                    className="w-full flex-1 bg-slate-950/50 border border-slate-700/50 rounded-xl p-4 text-slate-200 focus:ring-2 focus:ring-violet-500/50 focus:border-violet-500 outline-none resize-none placeholder-slate-600 text-sm transition-all"
                                />
                             )}

                             {state.manualRuleText.length === 0 && (
                                <div className="border-t border-slate-800/50 pt-4 mt-auto">
                                     <FileUpload 
                                        type="audio"
                                        label="Or Record Voice Instruction"
                                        subLabel="MP3/WAV Audio"
                                        onUpload={handleAudioUpload}
                                        currentFile={state.uploadedAudio}
                                        onRemove={handleRemoveAudio}
                                    />
                                </div>
                             )}
                        </div>
                    </div>
                </div>
            </div>

            <div className="flex justify-center pb-12">
                <button
                    onClick={handleAnalyze}
                    disabled={state.uploadedImages.length === 0}
                    className="group relative inline-flex items-center justify-center px-12 py-6 font-bold text-white transition-all duration-300 bg-gradient-to-r from-violet-600 to-indigo-600 rounded-2xl hover:from-violet-500 hover:to-indigo-500 disabled:opacity-50 disabled:grayscale shadow-[0_0_40px_rgba(124,58,237,0.3)] hover:shadow-[0_0_60px_rgba(124,58,237,0.5)] transform hover:-translate-y-1 active:scale-95 text-lg"
                >
                    <span className="mr-3">Initiate Synthesis</span>
                    <Wand2 size={24} className="group-hover:rotate-12 transition-transform" />
                </button>
            </div>
          </div>
        )}

        {/* STEP 2: REVIEW */}
        {state.step === 'review' && (
             <AnalysisReview 
                extractedItems={state.extractedItems}
                context={state.documentContext}
                rule={state.rule}
                onBack={() => setState(prev => ({ ...prev, step: 'input' }))}
                onConfirm={() => setState(prev => ({ ...prev, step: 'app' }))}
             />
        )}

        {/* STEP 3: APP */}
        {state.step === 'app' && (
             <GeneratedForm 
               items={state.extractedItems} 
               context={state.documentContext}
               rule={state.rule} 
               onReset={handleReset}
             />
        )}

      </main>

      <Footer />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { GenericItem, BusinessRule, DocumentContext } from '../types';
import { Check, ArrowLeft, ArrowRight, Layers, Smartphone, FileCheck, Circle, Save, CreditCard, Calendar, Type as TypeIcon, Hash, AlertTriangle, ShieldCheck, Database, Server, Wifi, ShoppingCart, Plus, Minus, ListTodo, ClipboardCheck, ScanLine, Share2 } from 'lucide-react';

interface GeneratedFormProps {
  items: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  onReset: () => void;
}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ items, context, rule, onReset }) => {
  // STATE FOR FORM MODE
  const [formValues, setFormValues] = useState<Record<string, string | number>>({});

  // STATE FOR CATALOG MODE
  const [cart, setCart] = useState<Record<string, number>>({}); // Item ID -> Quantity

  // STATE FOR CHECKLIST MODE
  const [checkedItems, setCheckedItems] = useState<Record<string, boolean>>({});

  const [isSubmitted, setIsSubmitted] = useState(false);
  const [isLocalhost, setIsLocalhost] = useState(false);

  // Get the current URL for the QR code so mobile devices open this exact app
  const currentAppUrl = typeof window !== 'undefined' ? window.location.href : 'https://vibeshift.ai';
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(currentAppUrl)}&margin=10&bgcolor=ffffff&color=000000`;

  const layout = context?.layoutType || 'form';

  useEffect(() => {
    if (typeof window !== 'undefined' && window.location.hostname === 'localhost') {
      setIsLocalhost(true);
    }
  }, []);

  useMemo(() => {
    // Initialize Form Values
    const initial: Record<string, string | number> = {};
    items.forEach(item => {
      initial[item.id] = item.value || "";
    });
    setFormValues(initial);
  }, [items]);

  const groupedItems = useMemo(() => {
    const cats: Record<string, GenericItem[]> = {};
    items.forEach(item => {
      const c = item.category || 'General';
      if (!cats[c]) cats[c] = [];
      cats[c].push(item);
    });
    return cats;
  }, [items]);

  // --- LOGIC CALCULATIONS ---

  // FORM TOTAL
  const formTotal = Object.entries(formValues).reduce((acc, [key, val]) => {
     const num = parseFloat(val as string);
     return !isNaN(num) ? acc + num : acc;
  }, 0);

  // CART TOTAL
  const cartTotal = items.reduce((acc, item) => {
    const qty = cart[item.id] || 0;
    const price = parseFloat(item.value as string) || 0;
    return acc + (qty * price);
  }, 0);

  // CHECKLIST PROGRESS
  const checkedCount = Object.values(checkedItems).filter(Boolean).length;

  // SHARED PROGRESS METRIC
  let progressPercent = 0;
  let metricValue = 0;
  let metricLabel = "";

  if (layout === 'form') {
    const filledCount = Object.values(formValues).filter(v => v !== "" && v !== 0).length;
    progressPercent = Math.min(100, Math.round((filledCount / items.length) * 100));
    metricValue = filledCount;
    metricLabel = "Fields Filled";
  } else if (layout === 'catalog') {
    const totalItems = Object.values(cart).reduce((a: number, b: number) => a + b, 0);
    progressPercent = totalItems > 0 ? 100 : 0; // Simple binary progress for catalog
    metricValue = cartTotal;
    metricLabel = "Cart Value";
  } else if (layout === 'checklist') {
    progressPercent = Math.min(100, Math.round((checkedCount / items.length) * 100));
    metricValue = checkedCount;
    metricLabel = "Tasks Done";
  }

  // BUSINESS RULE LOGIC
  let ruleTriggered = false;
  let ruleMessage = "";
  const trackedValue = layout === 'catalog' ? cartTotal : formTotal;

  if (rule) {
     if (trackedValue >= rule.threshold) {
         ruleTriggered = true;
         ruleMessage = rule.actionName || "Approval Required";
         if (rule.type === 'threshold_discount') {
             ruleMessage = `Benefit Applied: ${rule.benefitValue}%`;
         }
     } else {
         ruleMessage = `Value: ${trackedValue} / Threshold: ${rule.threshold}`;
     }
  }

  // --- HANDLERS ---

  const handleFormChange = (id: string, value: string | number) => {
    setFormValues(prev => ({ ...prev, [id]: value }));
  };

  const handleAddToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const handleRemoveFromCart = (id: string) => {
    setCart(prev => {
      const newQty = (prev[id] || 0) - 1;
      if (newQty <= 0) {
        const { [id]: _, ...rest } = prev;
        return rest;
      }
      return { ...prev, [id]: newQty };
    });
  };

  const handleToggleCheck = (id: string) => {
    setCheckedItems(prev => ({ ...prev, [id]: !prev[id] }));
  };

  if (isSubmitted) {
    return (
      <div className="flex items-center justify-center min-h-[60vh] animate-in fade-in duration-500">
        <div className="max-w-md w-full glass-card rounded-2xl shadow-2xl p-10 text-center border border-slate-700">
          <div className="w-24 h-24 bg-emerald-500/10 text-emerald-400 rounded-full flex items-center justify-center mx-auto mb-6 shadow-[0_0_30px_rgba(16,185,129,0.3)]">
            <Check size={48} />
          </div>
          <h2 className="text-3xl font-bold text-white mb-3">
             {layout === 'catalog' ? 'Order Placed!' : layout === 'checklist' ? 'Audit Complete!' : 'Data Processed!'}
          </h2>
          <p className="text-slate-400 mb-10 leading-relaxed">
            The digital record for <span className="text-emerald-400 font-semibold">{context?.appTitle}</span> has been synced.
          </p>
          <button onClick={() => { setIsSubmitted(false); onReset(); }} className="w-full py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold transition-colors border border-slate-700">
            Process Another Document
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full pb-20 animate-in fade-in duration-700">

        {/* TOP NAVIGATION BAR */}
        <div className="flex items-center justify-between mb-10">
             <button onClick={onReset} className="flex items-center space-x-2 text-slate-400 hover:text-white transition-colors group">
                <div className="p-2 rounded-full bg-slate-800 border border-slate-700 group-hover:border-slate-600 transition-colors">
                    <ArrowLeft size={18} />
                </div>
                <span className="font-medium">Back to Analysis</span>
             </button>

             <div className="flex items-center space-x-3">
                 <div className="hidden md:flex items-center space-x-2 px-4 py-1.5 bg-slate-900/50 text-slate-400 text-xs font-medium rounded-full border border-slate-800">
                    <Database size={12} />
                    <span>PostgreSQL: Connected</span>
                 </div>
                 <div className="flex items-center space-x-2 px-4 py-1.5 bg-emerald-500/10 text-emerald-400 text-xs font-bold rounded-full border border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.2)]">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                    <span>LIVE {layout.toUpperCase()} APP</span>
                 </div>
             </div>
        </div>

        {/* GRID LAYOUT: 2/3 Main Content, 1/3 Sidebar */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 items-start">

            {/* --- MAIN CONTENT AREA (Left 8 Cols) --- */}
            <div className="lg:col-span-8 space-y-8">

                {/* APP HEADER CARD */}
                <div className="glass-card rounded-2xl p-8 relative overflow-hidden group border border-slate-700">
                    <div className="absolute top-0 right-0 p-40 bg-gradient-to-br from-violet-600 to-indigo-600 rounded-full blur-[100px] -mr-20 -mt-20 opacity-20 pointer-events-none"></div>
                    <div className="relative z-10">
                        <div className="text-xs font-bold text-violet-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                                <Layers size={14} /> {context?.detectedType}
                        </div>
                        <h1 className="text-4xl font-extrabold text-white mb-4 tracking-tight">{context?.appTitle}</h1>
                        <p className="text-slate-400 text-sm font-medium flex items-center gap-2">
                            <Server size={14} className="text-emerald-500" />
                            {layout === 'catalog' ? 'Real-time Inventory Sync' : layout === 'checklist' ? 'Audit Logs Active' : 'Secure Enterprise Gateway'}
                        </p>
                    </div>
                </div>

                {/* DYNAMIC CONTENT CARDS */}
                {(Object.entries(groupedItems) as [string, GenericItem[]][]).map(([category, catItems]) => (
                    <div key={category} className="glass-card rounded-2xl overflow-hidden border border-slate-800 transition-all hover:border-slate-700">
                        <div className="bg-slate-900/60 px-8 py-5 border-b border-slate-700/50 backdrop-blur-sm flex items-center space-x-3">
                            <div className="w-1 h-5 rounded-full bg-gradient-to-b from-violet-500 to-indigo-500"></div>
                            <h3 className="font-bold text-slate-200 uppercase tracking-wider text-sm">{category}</h3>
                        </div>

                        <div className="p-8">
                            {/* --- LAYOUT 1: CATALOG MODE --- */}
                            {layout === 'catalog' ? (
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    {catItems.map(item => (
                                        <div key={item.id} className="bg-slate-950/30 border border-slate-800 rounded-xl p-5 flex justify-between items-center group hover:border-violet-500/40 transition-all">
                                            <div className="flex items-center gap-4">
                                                <div className="w-14 h-14 bg-slate-800 rounded-lg flex items-center justify-center text-slate-500 group-hover:text-violet-400 transition-colors">
                                                    <ShoppingCart size={24} />
                                                </div>
                                                <div>
                                                    <div className="font-bold text-slate-200 text-lg">{item.name}</div>
                                                    <div className="text-emerald-400 font-mono font-medium">${item.value || '0.00'}</div>
                                                </div>
                                            </div>
                                            {cart[item.id] ? (
                                                <div className="flex items-center bg-slate-800 rounded-lg border border-slate-700 overflow-hidden">
                                                    <button onClick={() => handleRemoveFromCart(item.id)} className="p-3 hover:bg-slate-700 text-slate-400 hover:text-white transition-colors"><Minus size={16} /></button>
                                                    <span className="w-10 text-center font-bold text-white">{cart[item.id]}</span>
                                                    <button onClick={() => handleAddToCart(item.id)} className="p-3 hover:bg-slate-700 text-slate-400 hover:text-white transition-colors"><Plus size={16} /></button>
                                                </div>
                                            ) : (
                                                <button onClick={() => handleAddToCart(item.id)} className="p-3 bg-violet-600/10 text-violet-400 border border-violet-600/20 rounded-lg hover:bg-violet-600 hover:text-white transition-all">
                                                    <Plus size={20} />
                                                </button>
                                            )}
                                        </div>
                                    ))}
                                </div>
                            ) : 
                            /* --- LAYOUT 2: CHECKLIST MODE --- */
                            layout === 'checklist' ? (
                                <div className="space-y-4">
                                    {catItems.map(item => (
                                        <div 
                                        key={item.id} 
                                        onClick={() => handleToggleCheck(item.id)}
                                        className={`p-5 rounded-xl border flex items-center justify-between cursor-pointer transition-all group ${checkedItems[item.id] ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-slate-950/30 border-slate-800 hover:border-slate-600'}`}
                                        >
                                            <div className="flex items-center gap-4">
                                                <div className={`w-8 h-8 rounded-lg border flex items-center justify-center transition-all ${checkedItems[item.id] ? 'bg-emerald-500 border-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'border-slate-600 group-hover:border-slate-400'}`}>
                                                    {checkedItems[item.id] && <Check size={18} />}
                                                </div>
                                                <span className={`text-lg font-medium transition-colors ${checkedItems[item.id] ? 'text-emerald-400 line-through decoration-emerald-500/30' : 'text-slate-200'}`}>{item.name}</span>
                                            </div>
                                            <div className={`text-xs font-bold uppercase tracking-wider px-3 py-1 rounded-full ${checkedItems[item.id] ? 'bg-emerald-500/20 text-emerald-400' : 'bg-slate-800 text-slate-500'}`}>
                                                {checkedItems[item.id] ? 'Verified' : 'Pending'}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) :
                            /* --- LAYOUT 3: FORM MODE (Default) --- */
                            (
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                    {catItems.map(item => {
                                        const inputType = item.type || (typeof item.value === 'number' ? 'number' : 'text');
                                        return (
                                            <div key={item.id} className={`${inputType === 'textarea' ? 'md:col-span-2' : ''} space-y-3 group`}>
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-wider group-hover:text-violet-400 transition-colors flex items-center gap-2 ml-1">
                                                    {inputType === 'date' && <Calendar size={12} />}
                                                    {inputType === 'number' && <Hash size={12} />}
                                                    {inputType === 'text' && <TypeIcon size={12} />}
                                                    {item.name}
                                                </label>

                                                {inputType === 'textarea' ? (
                                                    <textarea
                                                        value={formValues[item.id] || ''}
                                                        onChange={(e) => handleFormChange(item.id, e.target.value)}
                                                        className="w-full bg-slate-950/50 border border-slate-700 rounded-xl px-4 py-4 text-slate-100 placeholder-slate-600 focus:ring-2 focus:ring-violet-500/50 focus:border-violet-500 outline-none transition-all h-32 resize-none hover:bg-slate-900"
                                                        placeholder={item.description || `Enter ${item.name}...`}
                                                    />
                                                ) : (
                                                    <input
                                                        type={inputType === 'number' ? 'number' : 'text'}
                                                        value={formValues[item.id] || ''}
                                                        onChange={(e) => handleFormChange(item.id, e.target.value)}
                                                        className="w-full bg-slate-950/50 border border-slate-700 rounded-xl px-4 py-4 text-slate-100 placeholder-slate-600 focus:ring-2 focus:ring-violet-500/50 focus:border-violet-500 outline-none transition-all hover:bg-slate-900"
                                                        placeholder={item.description || `Enter ${item.name}...`}
                                                    />
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
