              </p>
            </div>

            {/* MAIN UPLOAD AREA - The Hero */}
            <div className="mb-12">
               {isScanning ? (
                      <CameraScanner 
                         onCapture={handleImageUpload} 
                         onClose={() => setIsScanning(false)} 
