interface CameraScannerProps {
  onCapture: (file: File) => void;
  onClose: () => void;
  lang: string;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose, lang }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [facingMode, setFacingMode] = useState<'environment' | 'user'>('environment');

  useEffect(() => {
    let activeStream: MediaStream | null = null;
    const startCamera = async () => {
      try {
        setError(null);
        activeStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: facingMode } 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = activeStream;
        }
      } catch (err) {
        if (facingMode === 'environment') {
          try {
            activeStream = await navigator.mediaDevices.getUserMedia({ video: true });
            if (videoRef.current) videoRef.current.srcObject = activeStream;
          } catch (retryErr) {
            setError(lang === 'hi' ? "कैमरा एक्सेस नहीं मिला।" : "Camera access denied or unavailable.");
          }
        } else {
          setError(lang === 'hi' ? "कैमरा एक्सेस नहीं मिला।" : "Camera access denied.");
        }
      }
    };
    startCamera();
    return () => {
      if (activeStream) activeStream.getTracks().forEach(track => track.stop());
    };
  }, [facingMode, lang]);

  const handleCapture = () => {
    if (videoRef.current) {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        if (facingMode === 'user') {
          ctx.translate(canvas.width, 0);
          ctx.scale(-1, 1);
        }
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        canvas.toBlob((blob) => {
          if (blob) {
            onCapture(new File([blob], "scan.jpg", { type: 'image/jpeg' }));
            onClose();
          }
        }, 'image/jpeg', 0.9);
      }
    }
  };

  return (
    <div className="relative glass-card rounded-2xl overflow-hidden bg-black h-[480px]">
      {error ? (
        <div className="flex flex-col items-center justify-center h-full p-8 text-center">
          <p className="text-red-400 mb-4">{error}</p>
          <button onClick={onClose} className="px-4 py-2 bg-slate-800 rounded-lg">Close</button>
        </div>
      ) : (
        <>
          <video ref={videoRef} autoPlay playsInline muted className={`w-full h-full object-cover ${facingMode === 'user' ? 'scale-x-[-1]' : ''}`} />
          <div className="absolute inset-0 pointer-events-none border-emerald-500/30 border-8 border-double"></div>
          <div className="absolute top-0 left-0 w-full h-1 bg-emerald-400 animate-[scan_2s_infinite] shadow-lg shadow-emerald-400/50"></div>
          <div className="absolute bottom-8 left-0 right-0 flex justify-center items-center gap-8">
            <button onClick={() => setFacingMode(prev => prev === 'environment' ? 'user' : 'environment')} className="p-3 bg-white/20 backdrop-blur-md rounded-full text-white"><RefreshCw size={24} /></button>
            <button onClick={handleCapture} className="w-16 h-16 rounded-full border-4 border-white bg-white/20 backdrop-blur-md flex items-center justify-center"><div className="w-12 h-12 bg-white rounded-full"></div></button>
            <button onClick={onClose} className="p-3 bg-red-500/20 backdrop-blur-md rounded-full text-white"><X size={24} /></button>
          </div>
        </>
      )}
    </div>
  );
};

