            <button onClick={() => setCurrentView('integrations')} className={`text-sm font-bold tracking-widest ${currentView === 'integrations' ? 'text-violet-400' : 'text-slate-400 hover:text-white'} transition-colors uppercase`}>Integrations</button>
            <button onClick={() => setCurrentView('dashboard')} className={`text-sm font-bold tracking-widest ${currentView === 'dashboard' ? 'text-violet-400' : 'text-slate-400 hover:text-white'} transition-colors uppercase`}>Dashboard</button>
