const TRANSLATIONS: Record<string, any> = {
  en: {
    heroTitle: "Transform",
    heroSlogan: "Chaos to Code.",
    heroSub: "The global bridge from paper to high-scale digital infrastructure. Transform legacy workflows in minutes.",
    startBtn: "Launch Engine",
    viewSolutions: "Explore Solutions",
    footerScalability: "Scalability",
    footerIntegrations: "Integrations",
    footerConnect: "Connect"
  },
  hi: {
    heroTitle: "परिवर्तन",
    heroSlogan: "अराजकता से कोड तक।",
    heroSub: "कागज से उच्च-स्तरीय डिजिटल बुनियादी ढांचे तक वैश्विक पुल। मिनटों में विरासत वर्कफ़्लो को बदलें।",
    startBtn: "इंजन लॉन्च करें",
    viewSolutions: "समाधान देखें",
    footerScalability: "स्केलेबिलिटी",
    footerIntegrations: "इंटीग्रेशन",
    footerConnect: "कनेक्ट"
  }
};

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setCurrentView] = useState<View>('landing');
  const [language, setLanguage] = useState('en');
  // State to toggle the visibility of the advanced configuration section
  const [showLogic, setShowLogic] = useState(false);
  const [state, setState] = useState<AppState>({
    uploadedImages: [],
    uploadedAudio: null,
    manualRuleText: '',
    extractedItems: [],
    documentContext: null,
    rule: null,
    step: 'input',
    isLoading: false,
    loadingMessage: ''
  });

  const t = (key: string) => TRANSLATIONS[language][key] || key;

  // --- ENGINE HANDLERS ---
  const handleAnalyze = async () => {
    if (state.uploadedImages.length === 0) return alert(language === 'hi' ? "कृपया एक दस्तावेज़ अपलोड करें।" : "Please upload a document.");
    setState(prev => ({ ...prev, isLoading: true, loadingMessage: "VibeShift Synthesis: Cross-referencing ERP Protocols..." }));
    try {
      const imageParts = await Promise.all(state.uploadedImages.map(fileToGenerativePart));
      let rule: BusinessRule | null = null;
      if (state.uploadedAudio) {
        const audioPart = await fileToGenerativePart(state.uploadedAudio);
        rule = await extractRuleFromAudio(audioPart.inlineData.data, audioPart.inlineData.mimeType);
      } else if (state.manualRuleText.trim()) {
        rule = await extractRuleFromText(state.manualRuleText);
      }
      const { items, context } = await extractDataFromImages(imageParts);
      setState(prev => ({ ...prev, extractedItems: items, documentContext: context, rule, step: 'review', isLoading: false }));
    } catch (e) {
