import React, { useState, useMemo, useEffect } from 'react';
import { GenericItem, BusinessRule, DocumentContext } from '../types.ts';
import { Check, ArrowLeft, ArrowRight, Layers, Smartphone, FileCheck, Circle, Save, CreditCard, Calendar, Type as TypeIcon, Hash, AlertTriangle, ShieldCheck, Database, Server, Wifi, ShoppingCart, Plus, Minus, ListTodo, ClipboardCheck, ScanLine, Share2, Code2, Download, X, Globe, Network, Terminal, Info, AlertCircle } from 'lucide-react';
import confetti from 'canvas-confetti';

interface GeneratedFormProps {
  items: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  lang: string;
  onReset: () => void;
}

const GeneratedForm: React.FC<GeneratedFormProps> = ({ items, context, rule, lang, onReset }) => {
  const [formValues, setFormValues] = useState<Record<string, string | number>>({});
  const [cart, setCart] = useState<Record<string, number>>({});
  const [checkedItems, setCheckedItems] = useState<Record<string, boolean>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showCode, setShowCode] = useState(false);
  const [activeTab, setActiveTab] = useState<'view' | 'integrations'>('view');
  const [errors, setErrors] = useState<Record<string, boolean>>({});
  const [submitError, setSubmitError] = useState<string | null>(null);

  const layout = context?.layoutType || 'form';
  const t = (en: string, hi: string) => lang === 'hi' ? hi : en;

  useMemo(() => {
    const initial: Record<string, string | number> = {};
    items.forEach(item => { initial[item.id] = item.value || ""; });
    setFormValues(initial);
  }, [items]);

  const handleSubmit = () => {
    // Basic Validation: Ensure at least some data is present
    const newErrors: Record<string, boolean> = {};
    let hasEmptyFields = false;

    if (layout === 'form') {
      items.forEach(item => {
        if (!formValues[item.id] || String(formValues[item.id]).trim() === "") {
          newErrors[item.id] = true;
          hasEmptyFields = true;
        }
      });
    } else if (layout === 'catalog') {
      if (Object.values(cart).reduce((a, b) => a + b, 0) === 0) {
        setSubmitError(t("Please add at least one item to cart.", "कृपया कार्ट में कम से कम एक आइटम जोड़ें।"));
        return;
      }
    } else if (layout === 'checklist') {
      if (Object.values(checkedItems).every(v => v === false)) {
        setSubmitError(t("Please mark at least one item as complete.", "कृपया कम से कम एक आइटम को पूर्ण के रूप में चिह्नित करें।"));
        return;
      }
    }

    if (hasEmptyFields) {
      setErrors(newErrors);
      setSubmitError(t("Please fill out all required fields.", "कृपया सभी आवश्यक फ़ील्ड भरें।"));
      return;
    }

    // Success flow
    setSubmitError(null);
    setIsSubmitted(true);
    confetti({ 
      particleCount: 200, 
      spread: 90, 
      origin: { y: 0.5 }, 
      colors: ['#8b5cf6', '#3b82f6', '#10b981', '#ffffff'] 
    });
  };

  const downloadCSV = () => {
    const headers = ["ID", "Field Name", "Extracted Value", "User Modified Value"];
    const rows = items.map(item => [
      item.id,
      item.name,
      item.value,
      formValues[item.id] || ''
    ]);

    if (layout === 'catalog') {
      rows.push(['---', '---', '---', '---']);
      rows.push(['Cart Total', '', '', cartTotal.toFixed(2)]);
    }

    const csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n" 
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `${context?.appTitle?.replace(/\s/g, '_') || 'VibeShift_Data'}_${new Date().toISOString().slice(0,10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const cartTotal = items.reduce((acc, item) => {
    const qty = cart[item.id] || 0;
    const price = parseFloat(item.value as string) || 0;
    return acc + (qty * price);
  }, 0);

