            >
              <Download size={22}/> {t("Export ERP Payload (CSV)", "ERP पेलोड एक्सपोर्ट करें")}
            </button>
            <button onClick={onReset} className="w-full py-4 text-slate-500 text-sm font-black uppercase tracking-[0.2em] hover:text-white transition-colors">
              {t("Execute New Ingestion", "नया इंजेक्शन निष्पादित करें")}
            </button>
          </div>
        </div>
      </div>
    );
  }

