          <span>{t("ABORT & RE-SYNTHESIZE", "निरस्त करें और पुनः सिंथेसाइज")}</span>
        </button>
        <div className="flex gap-4">
          <button onClick={() => setShowCode(true)} className="px-6 py-2.5 bg-slate-950/80 border border-slate-800 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3 hover:bg-slate-900 transition-all shadow-xl">
            <Code2 size={16} className="text-violet-500"/> {t("VIEW LOGIC", "लॉजिक देखें")}
          </button>
          <div className="px-6 py-2.5 bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3 shadow-xl">
            <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.5)]"></div> 
            {t("INFRA CONNECTED", "इंफ्रा जुड़ा हुआ")}
          </div>
        </div>
      </div>

      <div className="flex border-b border-slate-800/50 mb-12 space-x-12">
        <button onClick={() => setActiveTab('view')} className={`pb-5 text-[11px] font-black tracking-[0.2em] transition-all uppercase ${activeTab === 'view' ? 'text-violet-500 border-b-4 border-violet-500' : 'text-slate-500 hover:text-slate-300'}`}>
          01. {t("USER INTERFACE", "यूजर इंटरफेस")}
        </button>
        <button onClick={() => setActiveTab('integrations')} className={`pb-5 text-[11px] font-black tracking-[0.2em] transition-all uppercase ${activeTab === 'integrations' ? 'text-violet-500 border-b-4 border-violet-500' : 'text-slate-500 hover:text-slate-300'}`}>
          02. {t("BACKEND PIPELINE", "बैकेंड पाइपलाइन")}
