      contents: {
        parts: [{ text: `Extract logic from: "${text}"` }]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING, enum: ["threshold_action", "threshold_discount"] },
            threshold: { type: Type.NUMBER },
            benefitValue: { type: Type.NUMBER },
            originalText: { type: Type.STRING },
            actionName: { type: Type.STRING }
          },
          required: ["type", "threshold", "benefitValue", "originalText"]
        }
      }
    });

    if (response.text) {
      return JSON.parse(cleanJsonString(response.text)) as BusinessRule;
    }
  } catch (error) {
    console.error("Rule Extraction Error", error);
  }
  return null;
};

export const extractRuleFromAudio = async (base64Data: string, mimeType: string): Promise<BusinessRule | null> => {
  const modelId = "gemini-3-flash-preview";
  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [
          { text: "Extract business logic from this audio rule." },
          { inlineData: { data: base64Data, mimeType } }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING, enum: ["threshold_action", "threshold_discount"] },
            threshold: { type: Type.NUMBER },
            benefitValue: { type: Type.NUMBER },
            originalText: { type: Type.STRING },
            actionName: { type: Type.STRING }
          },
          required: ["type", "threshold", "benefitValue", "originalText"]
        }
      }
    });

    if (response.text) {
      return JSON.parse(cleanJsonString(response.text)) as BusinessRule;
    }
  } catch (error) {
    console.error("Audio Rule Extraction Error", error);
  }
  return null;
};

