const FileUpload: React.FC<FileUploadProps> = ({ type, onUpload, label, subLabel, currentFile, onRemove }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const processFile = (file: File) => {
    if (!file) return;
    if (type === 'image' && !file.type.startsWith('image/')) return alert('Image files only.');
    if (type === 'audio' && !file.type.startsWith('audio/')) return alert('Audio files only.');
    onUpload(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files[0]) processFile(e.dataTransfer.files[0]);
  };

  const hasFile = !!currentFile;

  return (
    <div 
      className={`relative bento-card rounded-[3rem] p-12 cursor-pointer transition-all duration-500 group min-h-[400px] flex items-center justify-center
        ${isDragging 
          ? 'border-violet-500/50 bg-violet-900/10' 
          : 'border-white/5 hover:border-white/20 hover:bg-[#0f0f0f]'}
        ${hasFile ? 'border-emerald-500/20 bg-emerald-500/5' : ''}
      `}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      onClick={() => fileInputRef.current?.click()}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} 
        className="hidden" 
        accept={type === 'image' ? "image/*" : "audio/*"}
      />

      {hasFile && onRemove && (
        <button
          onClick={(e) => { e.stopPropagation(); onRemove(); }}
          className="absolute top-8 right-8 p-3 bg-black/40 hover:bg-red-500 text-slate-400 hover:text-white rounded-2xl transition-all z-10 border border-white/10"
        >
          <X size={20} />
        </button>
      )}

      <div className="relative z-10 flex flex-col items-center text-center space-y-8">
        {hasFile ? (
           <div className="relative">
              <div className="absolute inset-0 bg-emerald-500 blur-3xl opacity-20 rounded-full animate-pulse"></div>
              <div className="text-emerald-400 bg-emerald-500/10 p-8 rounded-[2.5rem] mb-4 border border-emerald-500/20 shadow-2xl animate-in zoom-in duration-500">
                <CheckCircle size={48} />
              </div>
           </div>
        ) : (
          <div className={`p-8 rounded-[2.5rem] transition-all duration-700 relative
            ${type === 'image' 
              ? 'bg-white/5 text-slate-400 group-hover:bg-violet-600 group-hover:text-white' 
              : 'bg-white/5 text-slate-400 group-hover:bg-fuchsia-600 group-hover:text-white'}`}>
             {type === 'image' ? <Layers size={48} /> : <FileAudio size={48} />}
          </div>
        )}

        <div>
          <h3 className="text-2xl font-black text-white tracking-tight flex items-center justify-center gap-3">
            {hasFile ? currentFile.name : label}
            {!hasFile && <Sparkles size={20} className="text-violet-400" />}
          </h3>
          <p className="text-slate-500 text-sm mt-3 font-medium uppercase tracking-[0.2em]">
            {hasFile ? 'PROTOCOL READY' : subLabel}
          </p>
        </div>
      </div>
    </div>
  );
};

