import { GoogleGenAI, Type } from "@google/genai";
import { GenericItem, BusinessRule, DocumentContext } from "../types";

// The "Brain" is initialized here using the Google GenAI SDK.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const cleanJsonString = (str: string): string => {
  return str.replace(/```json\n?/, '').replace(/\n?```/, '').trim();
};

export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type
        }
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * CORE LLM INTEGRATION
 * This function communicates with Gemini 3 Flash.
 * It doesn't just OCR text; it understands the BUSINESS CONTEXT.
 */
export const extractDataFromImages = async (imageParts: Array<{ inlineData: { data: string; mimeType: string } }>): Promise<{ items: GenericItem[], context: DocumentContext }> => {
  const modelId = "gemini-3-flash-preview";

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        ...imageParts,
        {
          text: `ACT AS A WORLD-CLASS DIGITAL TRANSFORMATION ARCHITECT.

          TASK: Reverse-engineer the provided visual document into a High-Fidelity Enterprise Hub.

          DIAGNOSTIC PROTOCOLS:
          1. STRUCTURE: Identify if this is a Transactional Document (Receipt/Invoice), an Informational Document (ID/Business Card), or a Logistical Document (Checklist/Form).
          2. UI INFERENCE: 
             - Use 'catalog' ONLY if there are clear line items with prices (Commerce intent).
             - Use 'checklist' if there are status markers, inspection points, or to-dos.
             - Use 'form' for all general data ingestion.
          3. GENUINE CONTENT: Extract EXACT values from the OCR. If a field is blank on the form, keep the value as "". If it's a filled receipt, extract the exact data.
          4. METADATA: Invent a startup-ready "App Title" that sounds professional (e.g., 'Nexus Expense Core', 'Aura Patient Portal').

          The output must be strictly valid JSON according to the schema.`
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          context: {
            type: Type.OBJECT,
            properties: {
              detectedType: { type: Type.STRING },
              appTitle: { type: Type.STRING },
              actionButtonLabel: { type: Type.STRING },
              summaryLabel: { type: Type.STRING },
              layoutType: { type: Type.STRING, enum: ['form', 'catalog', 'checklist'] }
            },
            required: ["detectedType", "appTitle", "actionButtonLabel", "summaryLabel", "layoutType"]
          },
          items: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                name: { type: Type.STRING },
                value: { type: Type.STRING },
                category: { type: Type.STRING },
                description: { type: Type.STRING },
                type: { type: Type.STRING, enum: ['text', 'number', 'date', 'textarea', 'currency', 'boolean'] }
              },
              required: ["id", "name", "category"]
            }
          }
        },
        required: ["context", "items"]
      }
    }
  });

  if (response.text) {
    try {
      return JSON.parse(cleanJsonString(response.text)) as { items: GenericItem[], context: DocumentContext };
    } catch (e) {
      console.error("LLM Extraction Error", e);
      throw new Error("Architecture Synthesis Failed: The LLM could not parse the document structure.");
    }
  }
  throw new Error("No response from Synthesis Engine.");
};

