import React, { useEffect, useState } from 'react';
import { GenericItem, BusinessRule, DocumentContext } from '../types';
import { ArrowRight, Sparkles, FileText, Zap, BrainCircuit, ScanLine, Terminal, CheckCircle2, Search, Database, Fingerprint, Lock, Cpu, Server, LayoutTemplate, ShieldCheck, Activity } from 'lucide-react';

interface AnalysisReviewProps {
  extractedItems: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  onConfirm: () => void;
  onBack: () => void;
}

const AnalysisReview: React.FC<AnalysisReviewProps> = ({ extractedItems, context, rule, onConfirm, onBack }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const [activeStage, setActiveStage] = useState(0);

  useEffect(() => {
    const logMessages = [
      `[HANDSHAKE] Initializing VibeShift Multi-LLM Protocol...`,
      `[SECURITY] AES-256 Tunnel established for Document Ingestion.`,
      `[OCR] Gemini Vision Analysis in progress...`,
      `[BRAIN] Identifying Business Context: '${context?.detectedType?.toUpperCase()}'.`,
      `[ARCHITECT] Designing ${context?.layoutType?.toUpperCase()} Architecture for Enterprise Scale.`,
      `[DATA] Synthesizing ${extractedItems.length} core data nodes...`,
      `[RULES] Injecting Business Logic Layers...`,
      `[FINAL] Architecture Integrity Verified. Deployment Lock Active.`
    ];

    let delay = 0;
    setLogs([]);
    setActiveStage(0);

    logMessages.forEach((msg, index) => {
      delay += (index === 0) ? 400 : 350; 
      const timer = setTimeout(() => {
        setLogs(prev => [...prev, msg]);
        if (index === 3) setActiveStage(1);
        if (index === 5) setActiveStage(2);
        if (index === 7) setActiveStage(3);
      }, delay);
    });
  }, [context, extractedItems.length]);

  return (
    <div className="max-w-7xl mx-auto animate-in fade-in slide-in-from-bottom-12 duration-1000">
