        <div className="lg:col-span-7 space-y-8">
            <div className={`glass-card rounded-[3rem] p-10 border transition-all duration-700 ${activeStage >= 1 ? 'border-emerald-500/30 bg-emerald-950/10' : 'border-slate-800 opacity-50'}`}>
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-4">
                        <div className={`p-4 rounded-2xl ${activeStage >= 1 ? 'bg-emerald-500 text-white shadow-2xl' : 'bg-slate-800 text-slate-500'}`}><LayoutTemplate size={28} /></div>
                        <div>
                            <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest mb-1">Architecture Decision</h3>
                            <p className="text-2xl font-black text-white">{context?.detectedType}</p>
                        </div>
                    </div>
                    {activeStage >= 1 && <ShieldCheck size={28} className="text-emerald-500" />}
                </div>
                <div className="pl-16">
                    <div className="bg-slate-950/80 rounded-3xl p-6 border border-slate-800 shadow-inner">
                        <span className="text-[10px] text-violet-400 font-black uppercase tracking-widest block mb-2">Target UX Pattern</span>
                        <div className="text-3xl font-black text-white uppercase tracking-tighter">{context?.layoutType} HUB</div>
                    </div>
                </div>
            </div>

            <div className={`glass-card rounded-[3rem] p-10 border transition-all duration-700 ${activeStage >= 2 ? 'border-blue-500/30 bg-blue-950/10' : 'border-slate-800 opacity-50'}`}>
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-4">
                        <div className={`p-4 rounded-2xl ${activeStage >= 2 ? 'bg-blue-500 text-white shadow-2xl' : 'bg-slate-800 text-slate-500'}`}><Cpu size={28} /></div>
                        <div>
                            <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest mb-1">Synthesized Data Nodes</h3>
                            <p className="text-2xl font-black text-white">{extractedItems.length} Entities Mapped</p>
                        </div>
