  const [state, setState] = useState<AppState>({
    uploadedImages: [],
    uploadedAudio: null,
    customLogicText: '',
    industryMode: 'default',
    extractedItems: [],
    documentContext: null,
    rule: null,
    step: 'input',
    isLoading: false,
    loadingMessage: ''
  });

  useEffect(() => {
    localStorage.setItem('lang', language);
  }, [language]);

  const t = (key: keyof typeof DICTIONARY.en) => DICTIONARY[language][key];

  const handleAnalyze = async () => {
    if (state.uploadedImages.length === 0) {
      setToast({ message: "Architecture requires a source document.", type: 'error' });
      return;
    }
    setState(prev => ({ ...prev, isLoading: true, loadingMessage: "Initializing Neural Reconstruction Layer..." }));
    try {
      const imageParts = await Promise.all(state.uploadedImages.map(fileToGenerativePart));
      const result = await extractDataFromImages(imageParts);

      let extractedRule = null;
      if (state.customLogicText) {
        extractedRule = await extractRuleFromText(state.customLogicText);
      }

      setState(prev => ({ 
        ...prev, 
        extractedItems: result.items, 
        documentContext: result.context, 
        rule: extractedRule,
        step: 'review', 
        isLoading: false 
      }));
    } catch (e: any) {
      setState(prev => ({ ...prev, isLoading: false }));
      setToast({ message: e.message || "Synthesis failed.", type: 'error' });
    }
  };

  const handleCameraCapture = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setState(p => ({...p, uploadedImages: [file]}));
    }
  };

  const handleAudioUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
