        }`}>
           <div className={`p-3.5 rounded-2xl ${toast.type === 'error' ? 'bg-red-500' : 'bg-emerald-500'}`}>
              {toast.type === 'error' ? <AlertCircle size={24} className="text-white"/> : <CheckCircle2 size={24} className="text-white"/>}
