const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activeTab, setActiveTab] = useState<'synthesis' | 'settings'>('synthesis');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('lang') as Language) || 'en');
  const [isWorkflowExpanded, setIsWorkflowExpanded] = useState(false);
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: 'error' | 'success' | 'info' } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const audioInputRef = useRef<HTMLInputElement>(null);

  const [state, setState] = useState<AppState>({
    uploadedImages: [],
    uploadedAudio: null,
    customLogicText: '',
    industryMode: 'default',
    extractedItems: [],
    documentContext: null,
    rule: null,
    step: 'input',
    isLoading: false,
    loadingMessage: ''
  });

  useEffect(() => {
    localStorage.setItem('lang', language);
  }, [language]);

  const t = (key: keyof typeof DICTIONARY.en) => DICTIONARY[language][key];

  // REAL-TIME CAMERA CAPTURE LOGIC
  const startCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      setToast({ message: "Camera Access Denied: Check Permissions", type: 'error' });
      setShowCamera(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
      tracks.forEach(track => track.stop());
    }
    setShowCamera(false);
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      canvasRef.current.width = videoRef.current.videoWidth;
      canvasRef.current.height = videoRef.current.videoHeight;
      context?.drawImage(videoRef.current, 0, 0);
      canvasRef.current.toBlob((blob) => {
        if (blob) {
          const file = new File([blob], "scan_capture.jpg", { type: "image/jpeg" });
          setState(p => ({...p, uploadedImages: [file]}));
          stopCamera();
        }
      }, 'image/jpeg');
    }
  };

  // Fix: Added missing handleAudioUpload function to process audio file selection.
  const handleAudioUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setState(p => ({ ...p, uploadedAudio: file }));
    }
  };

  const handleAnalyze = async () => {
    if (state.uploadedImages.length === 0) {
      setToast({ message: "Architecture requires a source document.", type: 'error' });
      return;
    }
    setState(prev => ({ ...prev, isLoading: true, loadingMessage: "Initializing Neural Reconstruction Layer..." }));
    try {
      const imageParts = await Promise.all(state.uploadedImages.map(fileToGenerativePart));
      const result = await extractDataFromImages(imageParts);

      let extractedRule = null;
      if (state.customLogicText) {
        extractedRule = await extractRuleFromText(state.customLogicText);
      } else if (state.uploadedAudio) {
        // Extract logic from audio if custom text is not provided.
        const audioPart = await fileToGenerativePart(state.uploadedAudio);
        extractedRule = await extractRuleFromAudio(audioPart.inlineData.data, audioPart.inlineData.mimeType);
      }

      setState(prev => ({ 
        ...prev, 
        extractedItems: result.items, 
        documentContext: result.context, 
        rule: extractedRule,
        step: 'review', 
        isLoading: false 
      }));
    } catch (e: any) {
      setState(prev => ({ ...prev, isLoading: false }));
      setToast({ message: e.message || "Synthesis failed.", type: 'error' });
    }
  };

  if (!isAuthenticated) return <AuthLogin onLogin={() => setIsAuthenticated(true)} />;

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#020202] text-slate-100 selection:bg-violet-500/30">
