import React, { useState, useEffect, useRef } from 'react';
import { 
  Command, Layers, User, ChevronRight, Activity, 
  Zap, Globe, Cpu, Sparkles, ScanLine, Building2,
  GraduationCap, AlertCircle, Github, Linkedin,
  Camera, Smartphone, Laptop, Mic,
  ChevronDown, LogOut, MessageSquareCode, ArrowLeft,
  X, BarChart3, Terminal, Settings as SettingsIcon
} from 'lucide-react';
import FileUpload from './components/FileUpload.tsx';
import GeneratedForm from './components/GeneratedForm.tsx';
import AnalysisReview from './components/AnalysisReview.tsx';
import AuthLogin from './components/AuthLogin.tsx';
import { AppState, Language, IndustryType } from './types.ts';
import { extractDataFromImages, extractRuleFromText, fileToGenerativePart } from './services/gemini.ts';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activeTab, setActiveTab] = useState<'synthesis' | 'analytics'>('synthesis');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('lang') as Language) || 'en');
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: 'error' | 'success' } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const [state, setState] = useState<AppState>({
    uploadedImages: [],
    uploadedAudio: null,
    customLogicText: '',
    industryMode: 'default',
    extractedItems: [],
    documentContext: null,
    rule: null,
    step: 'input',
    isLoading: false,
    loadingMessage: ''
  });

  const startCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) videoRef.current.srcObject = stream;
    } catch (err) {
      setToast({ message: "Camera access denied", type: 'error' });
      setShowCamera(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
    }
    setShowCamera(false);
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      canvasRef.current.width = videoRef.current.videoWidth;
      canvasRef.current.height = videoRef.current.videoHeight;
      context?.drawImage(videoRef.current, 0, 0);
      canvasRef.current.toBlob((blob) => {
        if (blob) {
          const file = new File([blob], "capture.jpg", { type: "image/jpeg" });
          setState(p => ({...p, uploadedImages: [file]}));
          stopCamera();
        }
      }, 'image/jpeg');
    }
  };

  const handleAnalyze = async () => {
    if (state.uploadedImages.length === 0) {
      setToast({ message: "Upload a document first", type: 'error' });
      return;
    }
    setState(p => ({ ...p, isLoading: true, loadingMessage: "Neural Reconstruction In Progress..." }));
    try {
      const imageParts = await Promise.all(state.uploadedImages.map(fileToGenerativePart));
      const result = await extractDataFromImages(imageParts);
      let rule = state.customLogicText ? await extractRuleFromText(state.customLogicText) : null;
      setState(p => ({ ...p, extractedItems: result.items, documentContext: result.context, rule, step: 'review', isLoading: false }));
    } catch (e: any) {
      setState(p => ({ ...p, isLoading: false }));
      setToast({ message: "Synthesis failed", type: 'error' });
    }
  };

  if (!isAuthenticated) return <AuthLogin onLogin={() => setIsAuthenticated(true)} />;

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#020203] text-slate-100">
      {/* SIDEBAR */}
      <aside className="w-64 flex flex-col border-r border-white/5 bg-[#050507] z-50">
        <div className="p-8 flex items-center gap-4">
          <div className="bg-white p-1.5 rounded-lg shadow-2xl"><Command size={22} className="text-black" /></div>
          <span className="text-xl font-black tracking-tighter text-white uppercase">VibeShift</span>
        </div>

        <nav className="flex-1 px-4 py-8 space-y-2">
          {[
            { id: 'synthesis', icon: <Zap size={18}/>, label: 'Engine' },
            { id: 'analytics', icon: <BarChart3 size={18}/>, label: 'Analytics' }
          ].map(item => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as any)}
              className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${activeTab === item.id ? 'bg-white/5 text-white' : 'opacity-40 hover:opacity-100'}`}
            >
              {item.icon} {item.label}
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-white/5">
           <div className="flex items-center gap-3 px-4 py-3 bg-violet-500/5 rounded-2xl">
              <Activity size={14} className="text-violet-500 animate-pulse" />
              <span className="text-[9px] font-black uppercase text-violet-400 tracking-widest">Core Active</span>
           </div>
        </div>
      </aside>

      {/* MAIN */}
      <div className="flex-1 flex flex-col relative overflow-hidden">
        <header className="h-20 border-b border-white/5 flex items-center justify-between px-10 bg-black/40 backdrop-blur-3xl z-40">
          <div className="flex items-center gap-4 text-slate-500 text-[10px] font-black uppercase tracking-[0.4em]">
             {state.step !== 'input' ? (
               <button onClick={() => setState(p => ({...p, step: 'input'}))} className="flex items-center gap-2 text-white bg-white/5 px-4 py-2 rounded-xl mr-4"><ArrowLeft size={14}/> Back</button>
             ) : (
               <>SYSTEM <ChevronRight size={14}/> <span className="text-white">NODE_01</span></>
             )}
          </div>

          <div className="relative">
            <div 
              onClick={() => setIsProfileOpen(!isProfileOpen)}
              className="w-10 h-10 rounded-full bg-slate-800 border border-white/10 flex items-center justify-center cursor-pointer hover:border-violet-500 transition-all"
            >
               <User size={18} />
            </div>
            {isProfileOpen && (
              <div className="absolute top-14 right-0 w-64 bg-[#0a0a0f] border border-white/10 rounded-3xl p-6 shadow-4xl animate-in fade-in slide-in-from-top-4 z-[100]">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">Account</p>
                <div className="mb-6">
                  <p className="text-xs font-bold text-white uppercase">Lead Architect</p>
                  <p className="text-[10px] text-slate-500">vaibhav@engine.ai</p>
                </div>
                <button onClick={() => setIsAuthenticated(false)} className="w-full flex items-center justify-between text-xs font-black uppercase tracking-widest text-red-500 hover:text-red-400 pt-4 border-t border-white/5">
                  Sign Out <LogOut size={14} />
                </button>
              </div>
            )}
          </div>
        </header>

        <main className="flex-1 overflow-y-auto custom-scrollbar p-12 lg:p-20">
          {activeTab === 'synthesis' && (
            <div className="max-w-6xl mx-auto">
              {state.step === 'input' && (
                <div className="space-y-24">
                  <div className="text-center space-y-12">
                    <div className="inline-flex items-center gap-3 px-5 py-2.5 bg-violet-600/5 border border-violet-600/20 rounded-full text-violet-400 text-[10px] font-black tracking-[0.3em] uppercase shadow-2xl">
                      <Zap size={14} className="fill-violet-400" /> VIBESHIFT ENGINE 3.0
                    </div>

                    {/* REFINED SLOGAN SECTION */}
                    <h1 className="hero-title text-[100px] lg:text-[140px] font-black text-white uppercase max-w-5xl mx-auto">
                      <span className="word-gap">Transform</span> <br/>
                      <span className="chaos-gradient">Chaos to Code.</span>
                    </h1>

                    <p className="text-slate-400 text-2xl font-semibold max-w-3xl mx-auto tracking-tight">
                      Instantly transform static documents into fully functional Web Apps. No coding required.
                    </p>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    <FileUpload 
                      type="image" 
                      label="Upload Document" 
                      subLabel="CAD, OCR, or Form" 
                      onUpload={f => setState(p => ({...p, uploadedImages: [f]}))} 
                      currentFile={state.uploadedImages[0]}
                      onRemove={() => setState(p => ({...p, uploadedImages: []}))}
                    />

                    <div 
                      onClick={startCamera}
                      className="bento-card relative p-16 rounded-[4rem] flex flex-col items-center justify-center text-center cursor-pointer group hover:border-violet-500/30 transition-all"
                    >
                      <div className="p-10 bg-violet-600/10 text-violet-500 rounded-full mb-8 group-hover:scale-110 group-hover:bg-violet-600 group-hover:text-white transition-all">
                        <Camera size={48} />
                      </div>
                      <h4 className="text-3xl font-black text-white uppercase tracking-tighter">Live Scan</h4>
                      <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-2">Real-time Neural Capture</p>
                    </div>
                  </div>

                  <div className="flex justify-center">
                    <button onClick={handleAnalyze} className="px-24 py-8 bg-white text-black hover:bg-slate-200 rounded-full text-2xl font-black uppercase tracking-tighter flex items-center gap-8 shadow-4xl active:scale-95 transition-all">
                      Initiate Synthesis <Sparkles size={28} />
                    </button>
                  </div>
                </div>
              )}

              {state.step === 'review' && <AnalysisReview extractedItems={state.extractedItems} context={state.documentContext} rule={state.rule} onBack={() => setState(p => ({...p, step: 'input'}))} onConfirm={() => setState(p => ({...p, step: 'app'}))} />}
              {state.step === 'app' && <GeneratedForm items={state.extractedItems} context={state.documentContext} rule={state.rule} lang={language} onReset={() => setState(p => ({...p, step: 'input'}))} />}
            </div>
          )}

          {activeTab === 'analytics' && (
            <div className="max-w-6xl mx-auto space-y-12">
               <h2 className="text-6xl font-black text-white uppercase tracking-tighter">Neural Analytics</h2>
               <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                  {[1,2,3].map(i => (
                    <div key={i} className="bento-card p-10 rounded-[3rem]">
                       <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Metrics Layer 0{i}</p>
                       <div className="text-5xl font-black text-white mb-6">99.{i}%</div>
                       <div className="h-2 w-full bg-white/5 rounded-full overflow-hidden">
                          <div className="h-full bg-violet-600" style={{width: `${70 + i*10}%`}}></div>
                       </div>
                    </div>
                  ))}
               </div>
               <div className="bento-card p-12 rounded-[4rem] h-96 flex items-end gap-2">
                  {[...Array(20)].map((_, i) => (
                    <div key={i} className="flex-1 bg-violet-600/20 rounded-t-lg hover:bg-violet-600 transition-all cursor-pointer" style={{height: `${Math.random() * 80 + 20}%`}}></div>
                  ))}
               </div>
            </div>
          )}
        </main>
      </div>

      {/* CAMERA OVERLAY */}
      {showCamera && (
        <div className="fixed inset-0 z-[200] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-8 animate-in zoom-in">
          <div className="relative w-full max-w-4xl h-[70vh] bg-black rounded-[4rem] overflow-hidden border border-white/10 shadow-4xl">
            <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
            <canvas ref={canvasRef} className="hidden" />
            <div className="absolute inset-0 border-[2px] border-violet-500/20 pointer-events-none">
              <div className="absolute top-0 left-0 w-full h-1 bg-violet-500 shadow-[0_0_30px_rgba(124,58,237,1)] animate-scan-line"></div>
            </div>
            <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex items-center gap-8">
               <button onClick={stopCamera} className="p-6 bg-red-500/10 text-red-500 rounded-full hover:bg-red-500 hover:text-white transition-all"><X size={32}/></button>
               <button onClick={captureFrame} className="p-10 bg-white text-black rounded-full hover:scale-110 active:scale-95 transition-all shadow-4xl"><ScanLine size={40}/></button>
            </div>
          </div>
        </div>
      )}

      {state.isLoading && (
        <div className="fixed inset-0 bg-black/95 backdrop-blur-3xl z-[300] flex flex-col items-center justify-center">
           <div className="w-24 h-24 border-4 border-white/5 border-t-violet-500 rounded-full animate-spin mb-10"></div>
           <h2 className="text-3xl font-black text-white tracking-tighter uppercase">{state.loadingMessage}</h2>
        </div>
      )}

      {toast && (
        <div className={`fixed bottom-12 right-12 z-[500] px-8 py-5 rounded-3xl border backdrop-blur-3xl animate-in slide-in-from-bottom-8 flex items-center gap-4 ${toast.type === 'error' ? 'bg-red-500/10 border-red-500/30 text-red-400' : 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400'}`}>
          <AlertCircle size={20} />
          <span className="text-xs font-black uppercase tracking-widest">{toast.message}</span>
        </div>
      )}
    </div>
  );
};

export default App;

