                setActiveTab(item.id as any);
                setState(prev => ({...prev, step: 'input'}));
              }}
              className={`flex-1 lg:flex-none flex items-center gap-4 px-5 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.3em] transition-all ${activeTab === item.id ? 'bg-white/5 text-white' : 'opacity-40 hover:opacity-100 hover:bg-white/[0.02]'}`}
            >
              {item.icon} <span className="hidden lg:inline">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-white/5 hidden lg:block space-y-4">
           <div className="flex items-center gap-3 px-4 py-3 bg-violet-600/5 rounded-2xl border border-violet-600/10">
              <Activity size={14} className="text-violet-500 animate-pulse" />
