import { GoogleGenAI, Type } from "@google/genai";
import { GenericItem, BusinessRule, DocumentContext } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const cleanJsonString = (str: string): string => {
  return str.replace(/```json\n?/, '').replace(/\n?```/, '').trim();
};

export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type
        }
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * FAST EXTRACTION SERVICE
 * Uses Gemini 2.5 Flash Lite for low-latency document reasoning.
 */
export const extractDataFromImages = async (imageParts: Array<{ inlineData: { data: string; mimeType: string } }>): Promise<{ items: GenericItem[], context: DocumentContext }> => {
  const modelId = "gemini-2.5-flash-lite-latest";

  const response = await ai.models.generateContent({
    model: modelId,
    contents: {
      parts: [
        ...imageParts,
        {
          text: `ACT AS A WORLD-CLASS DIGITAL TRANSFORMATION ARCHITECT.

          TASK: Reverse-engineer the provided visual document into a High-Fidelity Enterprise Hub.

          DIAGNOSTIC PROTOCOLS:
          1. UI INFERENCE: 
             - Use 'catalog' ONLY if there are clear line items with prices.
             - Use 'checklist' if there are status markers.
             - Use 'form' for general data ingestion.
          2. GENUINE CONTENT: Extract EXACT values. 
          3. METADATA: Create a professional App Title.

          Output must be strictly valid JSON.`
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          context: {
            type: Type.OBJECT,
            properties: {
              detectedType: { type: Type.STRING },
              appTitle: { type: Type.STRING },
              actionButtonLabel: { type: Type.STRING },
              summaryLabel: { type: Type.STRING },
              layoutType: { type: Type.STRING, enum: ['form', 'catalog', 'checklist'] }
            },
            required: ["detectedType", "appTitle", "actionButtonLabel", "summaryLabel", "layoutType"]
          },
          items: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                name: { type: Type.STRING },
                value: { type: Type.STRING },
                category: { type: Type.STRING },
                description: { type: Type.STRING },
                type: { type: Type.STRING, enum: ['text', 'number', 'date', 'textarea', 'currency', 'boolean'] }
              },
              required: ["id", "name", "category"]
            }
          }
        },
        required: ["context", "items"]
      }
    }
  });

  if (response.text) {
    try {
      return JSON.parse(cleanJsonString(response.text)) as { items: GenericItem[], context: DocumentContext };
    } catch (e) {
      console.error("LLM Extraction Error", e);
      throw new Error("Architecture Synthesis Failed.");
    }
  }
  throw new Error("No response from Synthesis Engine.");
};

/**
 * IMAGE GENERATION SERVICE
 * Uses Gemini 3 Pro Image Preview (Nano Banana Pro)
 */
export const generateDesignImage = async (prompt: string, size: "1K" | "2K" | "4K"): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: {
      parts: [{ text: prompt }],
    },
    config: {
      imageConfig: {
        aspectRatio: "16:9",
        imageSize: size
      }
    },
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  throw new Error("Image generation failed to return data.");
};

export const extractRuleFromText = async (text: string): Promise<BusinessRule | null> => {
  const modelId = "gemini-2.5-flash-lite-latest";
  try {
    const response = await ai.models.generateContent({
      model: modelId,
      contents: {
        parts: [{ text: `Extract logic from: "${text}"` }]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING, enum: ["threshold_action", "threshold_discount"] },
            threshold: { type: Type.NUMBER },
            benefitValue: { type: Type.NUMBER },
            originalText: { type: Type.STRING },
            actionName: { type: Type.STRING }
          },
          required: ["type", "threshold", "benefitValue", "originalText"]
        }
      }
    });

    if (response.text) {
      return JSON.parse(cleanJsonString(response.text)) as BusinessRule;
    }
  } catch (error) {
    console.error("Rule Extraction Error", error);
  }
  return null;
};

