const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activeTab, setActiveTab] = useState<'synthesis' | 'design' | 'protocols'>('synthesis');
  const [userName, setUserName] = useState<string>('Guest Architect');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('lang') as Language) || 'en');
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [toast, setToast] = useState<{ message: string; type: 'error' | 'success' } | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isWorkflowExpanded, setIsWorkflowExpanded] = useState(false);

  // Image Generation State
  const [imagePrompt, setImagePrompt] = useState('');
  const [imageSize, setImageSize] = useState<'1K' | '2K' | '4K'>('1K');
  const [generatedImageUrl, setGeneratedImageUrl] = useState<string | null>(null);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioInputRef = useRef<HTMLInputElement>(null);

  const [state, setState] = useState<AppState>({
    uploadedImages: [],
    uploadedAudio: null,
    customLogicText: '',
    industryMode: 'default',
    extractedItems: [],
    documentContext: null,
    rule: null,
    step: 'input',
    isLoading: false,
    loadingMessage: ''
  });

  const startCamera = async () => {
    setShowCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().catch(e => console.error("Play error:", e));
        };
      }
    } catch (err) {
      setToast({ message: "Camera access restricted.", type: 'error' });
      setShowCamera(false);
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
    }
    setShowCamera(false);
  };

  const captureFrame = () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      canvasRef.current.width = videoRef.current.videoWidth;
      canvasRef.current.height = videoRef.current.videoHeight;
      context?.drawImage(videoRef.current, 0, 0);
      canvasRef.current.toBlob((blob) => {
        if (blob) {
          const file = new File([blob], "capture.jpg", { type: "image/jpeg" });
          setState(p => ({...p, uploadedImages: [file]}));
          stopCamera();
          setToast({ message: "Visual Node Captured", type: 'success' });
        }
      }, 'image/jpeg');
    }
  };

  const handleAnalyze = async () => {
    if (state.uploadedImages.length === 0) {
      setToast({ message: "Please upload a source document.", type: 'error' });
      return;
    }
    setState(p => ({ ...p, isLoading: true, loadingMessage: "Initializing Core Reconstruction..." }));
    try {
      const imageParts = await Promise.all(state.uploadedImages.map(fileToGenerativePart));
      const result = await extractDataFromImages(imageParts);

      let rule = null;
      if (state.customLogicText) {
        rule = await extractRuleFromText(state.customLogicText);
      } else if (state.uploadedAudio) {
        const audioPart = await fileToGenerativePart(state.uploadedAudio);
        rule = await extractRuleFromAudio(audioPart);
      }

      setState(p => ({ ...p, extractedItems: result.items, documentContext: result.context, rule, step: 'review', isLoading: false }));
    } catch (e: any) {
      setState(p => ({ ...p, isLoading: false }));
      setToast({ message: "Synthesis process failed.", type: 'error' });
    }
  };

  const handleGenerateImage = async () => {
    if (!imagePrompt) return;
    setIsGeneratingImage(true);
    try {
      const url = await generateDesignImage(imagePrompt, imageSize);
      setGeneratedImageUrl(url);
      setToast({ message: "Visual Asset Generated", type: 'success' });
    } catch (e) {
      setToast({ message: "Generation failed.", type: 'error' });
    } finally {
      setIsGeneratingImage(false);
    }
  };

  if (!isAuthenticated) return <AuthLogin onLogin={(name) => { setIsAuthenticated(true); setUserName(name || 'Lead Architect'); }} />;

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#020204] text-slate-100">
      {/* MOBILE HEADER */}
      <div className="lg:hidden fixed top-0 left-0 w-full h-16 bg-black/40 backdrop-blur-3xl border-b border-white/5 flex items-center justify-between px-6 z-[100]">
        <div className="flex items-center gap-3">
          <Command size={20} className="text-white" />
          <span className="text-sm font-black tracking-tighter uppercase">VibeShift</span>
        </div>
        <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2">
          {isSidebarOpen ? <X size={24}/> : <Monitor size={24}/>}
        </button>
