import React, { useEffect, useState } from 'react';
import { GenericItem, BusinessRule, DocumentContext } from '../types';
import { ArrowRight, Sparkles, FileText, Zap, BrainCircuit, ScanLine, Terminal, CheckCircle2, Search, Database, Fingerprint, Lock, Cpu, Server, LayoutTemplate, ShieldCheck, Activity, MessageSquareCode } from 'lucide-react';

interface AnalysisReviewProps {
  extractedItems: GenericItem[];
  context: DocumentContext | null;
  rule: BusinessRule | null;
  onConfirm: () => void;
  onBack: () => void;
}

const AnalysisReview: React.FC<AnalysisReviewProps> = ({ extractedItems, context, rule, onConfirm, onBack }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const [activeStage, setActiveStage] = useState(0);

  useEffect(() => {
    const logMessages = [
      `[HANDSHAKE] Initializing VibeShift Logic Protocol...`,
      `[OCR] Visual analysis complete. Entities identified.`,
      `[BRAIN] Mapping ${context?.detectedType?.toUpperCase()} logic layers.`,
      `[ARCHITECTURE] Structuring ${context?.layoutType?.toUpperCase()} HUB components.`,
      rule ? `[RULES] Injection detected: ${rule.originalText.slice(0, 30)}...` : `[RULES] Default logic protocols active.`,
      `[VALIDATION] Node integrity verified. Ready for deployment.`
    ];

    let delay = 0;
    setLogs([]);
    setActiveStage(0);

    logMessages.forEach((msg, index) => {
      delay += 500; 
      setTimeout(() => {
        setLogs(prev => [...prev, msg]);
        if (index === 2) setActiveStage(1);
        if (index === 4) setActiveStage(2);
        if (index === 5) setActiveStage(3);
      }, delay);
    });
  }, [context, extractedItems.length, rule]);

  return (
    <div className="max-w-7xl mx-auto animate-in fade-in slide-in-from-bottom-12 duration-1000">
      <div className="text-center mb-16 space-y-4">
        <div className="inline-flex items-center space-x-3 px-5 py-2 rounded-full bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-[10px] font-black tracking-[0.3em] mb-4 shadow-xl uppercase">
           <Activity size={14} className="animate-pulse" />
           <span>Synthesis Layer: ACTIVE</span>
        </div>
        <h1 className="text-6xl font-black text-white tracking-tighter uppercase leading-none">
           Architecture <span className="gradient-text">Validation</span>
        </h1>
        <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Confirming Node Mapping and Custom Protocols</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-7 space-y-8">
            <div className={`glass-card rounded-[3rem] p-10 border transition-all duration-700 ${activeStage >= 1 ? 'border-emerald-500/30 bg-emerald-950/10' : 'border-slate-800 opacity-50'}`}>
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-4">
                        <div className={`p-4 rounded-2xl ${activeStage >= 1 ? 'bg-emerald-500 text-white shadow-2xl' : 'bg-slate-800 text-slate-500'}`}><LayoutTemplate size={28} /></div>
                        <div>
                            <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest mb-1">Architecture Node</h3>
                            <p className="text-2xl font-black text-white">{context?.detectedType}</p>
                        </div>
                    </div>
                    {activeStage >= 1 && <ShieldCheck size={28} className="text-emerald-500" />}
                </div>
                <div className="pl-16">
                    <div className="bg-slate-950/80 rounded-3xl p-6 border border-slate-800 shadow-inner">
                        <span className="text-[10px] text-violet-400 font-black uppercase tracking-widest block mb-2">Interface Pattern</span>
                        <div className="text-3xl font-black text-white uppercase tracking-tighter">{context?.layoutType} Core</div>
                    </div>
                </div>
            </div>

            {rule && (
              <div className={`glass-card rounded-[3rem] p-10 border transition-all duration-700 ${activeStage >= 2 ? 'border-violet-500/30 bg-violet-950/10' : 'border-slate-800 opacity-50'}`}>
                  <div className="flex items-center justify-between mb-8">
                      <div className="flex items-center gap-4">
                          <div className={`p-4 rounded-2xl ${activeStage >= 2 ? 'bg-violet-500 text-white shadow-2xl' : 'bg-slate-800 text-slate-500'}`}><MessageSquareCode size={28} /></div>
                          <div>
                              <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest mb-1">Injected Logic Layer</h3>
                              <p className="text-2xl font-black text-white">Custom Business Protocol</p>
                          </div>
                      </div>
                  </div>
                  <div className="pl-16">
                      <div className="p-6 bg-black border border-violet-500/20 rounded-3xl">
                         <p className="text-xs text-violet-300 font-bold uppercase tracking-widest mb-2 italic">"{rule.originalText}"</p>
                         <div className="flex gap-4">
                            <span className="text-[9px] font-black text-white bg-violet-600 px-3 py-1 rounded-lg uppercase tracking-widest">Active Rule</span>
                            <span className="text-[9px] font-black text-slate-400 border border-slate-700 px-3 py-1 rounded-lg uppercase tracking-widest">{rule.type}</span>
                         </div>
                      </div>
                  </div>
              </div>
            )}

            <div className={`glass-card rounded-[3rem] p-10 border transition-all duration-700 ${activeStage >= 2 ? 'border-blue-500/30 bg-blue-950/10' : 'border-slate-800 opacity-50'}`}>
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-4">
                        <div className={`p-4 rounded-2xl ${activeStage >= 2 ? 'bg-blue-500 text-white shadow-2xl' : 'bg-slate-800 text-slate-500'}`}><Cpu size={28} /></div>
                        <div>
                            <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest mb-1">Synthesized Entities</h3>
                            <p className="text-2xl font-black text-white">{extractedItems.length} Fields Mapped</p>
                        </div>
                    </div>
                </div>
                <div className="pl-16 flex flex-wrap gap-3">
                   {extractedItems.slice(0, 8).map((item, idx) => (
                      <span key={idx} className="px-4 py-2 bg-slate-900 border border-slate-800 rounded-xl text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.name}</span>
                   ))}
                </div>
            </div>
        </div>

        <div className="lg:col-span-5 flex flex-col space-y-8">
            <div className="glass-card rounded-[3rem] border border-slate-800 bg-black/40 overflow-hidden shadow-3xl relative flex-1 min-h-[400px]">
                <div className="bg-slate-900/60 px-6 py-4 border-b border-slate-800 flex items-center justify-between">
                    <div className="flex items-center gap-3"><Terminal size={18} className="text-emerald-500" /><span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Node Logs</span></div>
                    <div className="flex gap-2"><div className="w-2.5 h-2.5 rounded-full bg-red-500/40"></div><div className="w-2.5 h-2.5 rounded-full bg-emerald-500/40"></div></div>
                </div>
                <div className="p-8 font-mono text-xs text-slate-300 space-y-4">
                    {logs.map((log, i) => (
                        <div key={i} className="flex items-start gap-4 animate-in slide-in-from-left-4 duration-500">
                            <span className="text-emerald-500 font-black">»</span>
                            <span>{log}</span>
                        </div>
                    ))}
                    <div className="w-2 h-4 bg-emerald-500 animate-pulse inline-block"></div>
                </div>
            </div>

            <div className="space-y-4 pt-4">
                <button 
                    onClick={onConfirm}
                    disabled={activeStage < 3}
                    className="w-full py-6 rounded-[2rem] bg-gradient-to-r from-violet-600 to-indigo-600 text-white disabled:opacity-30 font-black text-xl shadow-2xl hover:shadow-violet-600/40 transition-all flex items-center justify-center gap-4 group active:scale-95"
                >
                    <Fingerprint size={28} />
                    <span>LAUNCH HUB</span>
                    <ArrowRight className="group-hover:translate-x-2 transition-transform" />
                </button>
                 <button onClick={onBack} className="w-full py-4 rounded-2xl border border-slate-800 text-slate-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-widest">
                    Abort Protocol
                </button>
            </div>
        </div>
      </div>
    </div>
  );
};

export default AnalysisReview;
